/* ────────────────────────────────────────────────────────────────────────
   learnroman-lotte.js — „La vuelta de Lotte" · Zielsprache Spanisch · KRONE (B1)
   Fester Inhalt, kein API-Call. Root-Helfer, KEIN vercel.json-Eintrag.
   Wird von learnroman-daten.js als Buch eingetragen.

   IDEE (Leo, 15.10.2026): „Für LA wähle einige dieser Orte … Puede ser un
   trotamundos que hace una vuelta por LA." · „Otro personaje, el resto
   decídelo tú, pero nada de política."
   Lotte de Vries (31, Fotografin aus Utrecht) reist zehn Monate durch
   Lateinamerika für ihren Bildband «Agua». Jede Station = eine B1-Szene des
   Geführten Gesprächs (Lernpfad b1.*, dieselben drei Lernersätze):
     1 hotel CDMX · 2 familie Oaxaca (Día de Muertos) · 3 wetter Monteverde ·
     4 arzt Quito · 5 einkaufen Otavalo · 6 bahnhof Quitumbe→Tena ·
     7 taxi Asunción · 8 cafe Buenos Aires · 9 restaurant El Calafate ·
     10 wegbeschreibung Canaima (Salto Ángel) · 11 Epilog Morrocoy.
   KRONE = ganz in der Sprache: JEDER Block ist Spanisch {z}, die Brücke tr
   {de, en, el} ist eingeklappt und kommt auf Knopfdruck.
   SPANISCH: neutrales Lateinamerika (ustedes, celular, boleto), NIE voseo,
   keine Politik. Running Gag „vale" (Spanien) → „con gusto".
   Entstehung: Bibel (Claude) → 3 Autoren-Agenten → Chef-Lektor (Kontinuität,
   alle 30 Lernersätze der Szenen wörtlich im Roman, Brücken geprüft).
   ──────────────────────────────────────────────────────────────────────── */
(function (w) {
  if (w.SPIKIU_LR_LOTTE) return;

  function Z(z, de, en, el) { return { z: z, tr: { de: de, en: en, el: el } }; }
  function S(n, thema, title, teaser, body) {
    return { level: 'anwendung', n: n, thema: thema, title: title, teaser: teaser, body: body };
  }

  var K = [];

  // ── Station 1 · hotel ──────────────────────────────
  K.push(S(1, "hotel", "Algo que tenga luz",
    { de: "Oktober, Mexiko-Stadt: Lotte kommt mit einer alten Leica und einem Projekt namens «Agua» — und sucht ein Zimmer für einen Monat.",
      en: "October, Mexico City: Lotte arrives with an old Leica and a project called «Agua» — and looks for a room for one month.",
      el: "Οκτώβριος, Πόλη του Μεξικού: η Λότε φτάνει με μια παλιά Leica κι ένα πρότζεκτ που λέγεται «Agua» — και ψάχνει δωμάτιο για έναν μήνα." },
  [
    Z("Ciudad de México, un martes de octubre. Desde el avión, la ciudad no termina nunca: luces y más luces, hasta las montañas.",
      "Mexiko-Stadt, ein Dienstag im Oktober. Vom Flugzeug aus hört die Stadt nicht auf: Lichter und noch mehr Lichter, bis zu den Bergen.",
      "Mexico City, a Tuesday in October. From the plane, the city never ends: lights and more lights, all the way to the mountains.",
      "Πόλη του Μεξικού, μια Τρίτη του Οκτωβρίου. Από το αεροπλάνο η πόλη δεν τελειώνει ποτέ: φώτα και κι άλλα φώτα, ως τα βουνά."),
    Z("En la fila veintitrés va una mujer de pelo rojo y rizado, con una cámara vieja —una Leica— y un cuaderno. En la tapa dice: AGUA.",
      "In Reihe dreiundzwanzig sitzt eine Frau mit roten, lockigen Haaren, mit einer alten Kamera — einer Leica — und einem Notizbuch. Auf dem Umschlag steht: AGUA.",
      "In row twenty-three sits a woman with curly red hair, with an old camera — a Leica — and a notebook. On the cover it says: AGUA.",
      "Στη σειρά είκοσι τρία κάθεται μια γυναίκα με κόκκινα σγουρά μαλλιά, με μια παλιά φωτογραφική μηχανή — μια Leica — κι ένα σημειωματάριο. Στο εξώφυλλο γράφει: AGUA."),
    Z("Se llama Lotte de Vries, tiene treinta y un años, es fotógrafa y viene de Utrecht, en los Países Bajos. Aprendió español hace años, un verano en Salamanca.",
      "Sie heißt Lotte de Vries, ist einunddreißig, Fotografin und kommt aus Utrecht in den Niederlanden. Spanisch hat sie vor Jahren gelernt, einen Sommer lang in Salamanca.",
      "Her name is Lotte de Vries, she's thirty-one, a photographer, and she comes from Utrecht, in the Netherlands. She learnt Spanish years ago, one summer in Salamanca.",
      "Τη λένε Λότε ντε Φρις, είναι τριάντα ενός χρονών, φωτογράφος, κι έρχεται από την Ουτρέχτη, στην Ολλανδία. Έμαθε ισπανικά πριν από χρόνια, ένα καλοκαίρι στη Σαλαμάνκα."),
    Z("Lotte mira por la ventanilla y piensa: «Esta ciudad era un lago». Hace quinientos años, aquí había agua, islas y canoas. Hoy hay calles, carros y más de veinte millones de personas.",
      "Lotte schaut aus dem Fenster und denkt: „Diese Stadt war ein See.“ Vor fünfhundert Jahren gab es hier Wasser, Inseln und Kanus. Heute gibt es Straßen, Autos und mehr als zwanzig Millionen Menschen.",
      "Lotte looks out of the window and thinks: “This city was a lake.” Five hundred years ago there was water here, islands and canoes. Today there are streets, cars and more than twenty million people.",
      "Η Λότε κοιτάζει από το παράθυρο και σκέφτεται: «Αυτή η πόλη ήταν λίμνη». Πριν από πεντακόσια χρόνια εδώ υπήρχε νερό, νησιά και κανό. Σήμερα υπάρχουν δρόμοι, αυτοκίνητα και πάνω από είκοσι εκατομμύρια άνθρωποι."),
    Z("—¿Motivo del viaje? —pregunta un señor de uniforme en migración.",
      "„Grund der Reise?“, fragt ein Herr in Uniform bei der Einreisekontrolle.",
      "“Purpose of your trip?” asks a man in uniform at immigration.",
      "«Σκοπός του ταξιδιού;» ρωτάει ένας κύριος με στολή στον έλεγχο διαβατηρίων."),
    Z("Lotte respira. Practicó la respuesta en el avión.",
      "Lotte atmet ein. Sie hat die Antwort im Flugzeug geübt.",
      "Lotte takes a breath. She practised the answer on the plane.",
      "Η Λότε παίρνει ανάσα. Εξασκήθηκε στην απάντηση μέσα στο αεροπλάνο."),
    Z("—Soy fotógrafa. Estoy haciendo un libro de fotos. Se llama «Agua».",
      "Ich bin Fotografin. Ich mache ein Fotobuch. Es heißt «Agua».",
      "I'm a photographer. I'm making a photo book. It's called «Agua».",
      "Είμαι φωτογράφος. Φτιάχνω ένα βιβλίο με φωτογραφίες. Λέγεται «Agua»."),
    Z("—¿Agua? ¿Como la que uno toma?",
      "Wasser? So wie das, was man trinkt?",
      "Water? Like the kind you drink?",
      "Νερό; Σαν αυτό που πίνουμε;"),
    Z("—Sí. El agua de América Latina: lagos, ríos, glaciares, lluvia. Voy a viajar nueve meses, de México hasta Venezuela. En cada lugar busco un agua diferente.",
      "Ja. Das Wasser Lateinamerikas: Seen, Flüsse, Gletscher, Regen. Ich reise neun Monate, von Mexiko bis Venezuela. An jedem Ort suche ich ein anderes Wasser.",
      "Yes. The water of Latin America: lakes, rivers, glaciers, rain. I'm going to travel for nine months, from Mexico to Venezuela. In every place I'm looking for a different water.",
      "Ναι. Το νερό της Λατινικής Αμερικής: λίμνες, ποτάμια, παγετώνες, βροχή. Θα ταξιδέψω εννιά μήνες, από το Μεξικό ως τη Βενεζουέλα. Σε κάθε τόπο ψάχνω ένα διαφορετικό νερό."),
    Z("—¡Qué padre! —dice el señor, y pone el sello—. Pues bienvenida.",
      "„Wie toll!“, sagt der Herr und drückt den Stempel auf. „Na dann, willkommen.“",
      "“How cool!” says the man, and stamps the passport. “Well, welcome.”",
      "«Τι ωραία!» λέει ο κύριος και βάζει τη σφραγίδα. «Λοιπόν, καλώς ήρθατε.»"),
    Z("—Vale, gracias.",
      "Okay, danke.",
      "Okay, thanks.",
      "Εντάξει, ευχαριστώ."),
    Z("¿Por qué el agua? Primero, porque en los Países Bajos casi la mitad del país está debajo del nivel del mar. Los holandeses viven con el agua desde siempre. La miran, la temen y la quieren.",
      "Warum das Wasser? Erstens, weil in den Niederlanden fast die Hälfte des Landes unter dem Meeresspiegel liegt. Die Niederländer leben schon immer mit dem Wasser. Sie beobachten es, sie fürchten es und sie lieben es.",
      "Why water? First, because in the Netherlands almost half the country lies below sea level. The Dutch have always lived with water. They watch it, they fear it and they love it.",
      "Γιατί το νερό; Πρώτα, γιατί στην Ολλανδία σχεδόν η μισή χώρα βρίσκεται κάτω από το επίπεδο της θάλασσας. Οι Ολλανδοί ζουν πάντα με το νερό. Το παρατηρούν, το φοβούνται και το αγαπούν."),
    Z("Y segundo, por Opa Kees, su abuelo. Durante cuarenta años fue guardián de una esclusa en un canal cerca de Utrecht. Cada mañana abría las puertas para los barcos, y cada tarde le contaba a Lotte de dónde venía el agua y adónde iba.",
      "Und zweitens wegen Opa Kees, ihrem Großvater. Vierzig Jahre lang war er Schleusenwärter an einem Kanal bei Utrecht. Jeden Morgen öffnete er die Tore für die Schiffe, und jeden Abend erzählte er Lotte, woher das Wasser kam und wohin es ging.",
      "And second, because of Opa Kees, her grandfather. For forty years he was a lock keeper on a canal near Utrecht. Every morning he opened the gates for the boats, and every evening he told Lotte where the water came from and where it was going.",
      "Και δεύτερον, εξαιτίας του Όπα Κέις, του παππού της. Για σαράντα χρόνια ήταν φύλακας σε έναν υδατοφράκτη σε ένα κανάλι κοντά στην Ουτρέχτη. Κάθε πρωί άνοιγε τις πύλες για τα καράβια, και κάθε βράδυ έλεγε στη Λότε από πού ερχόταν το νερό και πού πήγαινε."),
    Z("Opa Kees murió hace cinco años. Desde entonces, Lotte fotografía el agua. Es su manera de seguir hablando con él.",
      "Opa Kees ist vor fünf Jahren gestorben. Seitdem fotografiert Lotte das Wasser. Es ist ihre Art, weiter mit ihm zu sprechen.",
      "Opa Kees died five years ago. Since then, Lotte has been photographing water. It's her way of going on talking to him.",
      "Ο Όπα Κέις πέθανε πριν από πέντε χρόνια. Από τότε η Λότε φωτογραφίζει το νερό. Είναι ο τρόπος της να συνεχίζει να μιλάει μαζί του."),
    Z("El jueves, a las siete de la mañana, llega un mensaje de voz de Bram, su editor en Ámsterdam: «Lotte, soy Bram. Ya llegaste, ¿no? ¿Dónde están las fotos?».",
      "Am Donnerstag um sieben Uhr morgens kommt eine Sprachnachricht von Bram, ihrem Lektor in Amsterdam: „Lotte, hier ist Bram. Du bist doch schon da, oder? Wo sind die Fotos?“",
      "On Thursday, at seven in the morning, a voice message arrives from Bram, her editor in Amsterdam: “Lotte, it's Bram. You've arrived, haven't you? Where are the pictures?”",
      "Την Πέμπτη, στις εφτά το πρωί, έρχεται ένα φωνητικό μήνυμα από τον Μπραμ, τον επιμελητή της στο Άμστερνταμ: «Λότε, ο Μπραμ είμαι. Έφτασες ήδη, έτσι; Πού είναι οι φωτογραφίες;»"),
    Z("Lotte llegó hace treinta y seis horas.",
      "Lotte ist vor sechsunddreißig Stunden angekommen.",
      "Lotte arrived thirty-six hours ago.",
      "Η Λότε έφτασε πριν από τριάντα έξι ώρες."),
    Z("Lotte necesita un cuarto para un mes, tranquilo y con luz. Esa tarde toma el metro hasta Coyoacán: calles de piedra, casas de colores, árboles enormes.",
      "Lotte braucht ein Zimmer für einen Monat, ruhig und hell. An diesem Nachmittag nimmt sie die Metro bis Coyoacán: Straßen aus Stein, bunte Häuser, riesige Bäume.",
      "Lotte needs a room for a month, quiet and full of light. That afternoon she takes the metro to Coyoacán: stone streets, colourful houses, enormous trees.",
      "Η Λότε χρειάζεται ένα δωμάτιο για έναν μήνα, ήσυχο και φωτεινό. Εκείνο το απόγευμα παίρνει το μετρό ως το Κογιοακάν: πέτρινοι δρόμοι, πολύχρωμα σπίτια, τεράστια δέντρα."),
    Z("En una puerta azul hay un cartel escrito a mano: SE RENTA CUARTO AMUEBLADO. INFORMES AL TELÉFONO… Lotte llama desde la esquina. Contesta una voz de señora:",
      "An einer blauen Tür hängt ein handgeschriebenes Schild: MÖBLIERTES ZIMMER ZU VERMIETEN. AUSKUNFT UNTER DER NUMMER … Lotte ruft von der Ecke aus an. Eine Frauenstimme meldet sich:",
      "On a blue door there's a handwritten sign: FURNISHED ROOM TO LET. ENQUIRIES ON THIS NUMBER… Lotte calls from the corner. A woman's voice answers:",
      "Σε μια μπλε πόρτα υπάρχει μια χειρόγραφη πινακίδα: ΕΝΟΙΚΙΑΖΕΤΑΙ ΕΠΙΠΛΩΜΕΝΟ ΔΩΜΑΤΙΟ. ΠΛΗΡΟΦΟΡΙΕΣ ΣΤΟ ΤΗΛΕΦΩΝΟ… Η Λότε τηλεφωνεί από τη γωνία. Απαντά μια γυναικεία φωνή:"),
    Z("—¿Mande?",
      "Ja, bitte?",
      "Yes?",
      "Ορίστε;"),
    Z("En México, «¿mande?» es una forma muy amable de decir «¿sí?».",
      "In Mexiko ist „¿mande?“ eine sehr höfliche Art, „ja, bitte?“ zu sagen.",
      "In Mexico, “¿mande?” is a very polite way of saying “yes?”.",
      "Στο Μεξικό το «¿mande?» είναι ένας πολύ ευγενικός τρόπος να πεις «ναι;»."),
    Z("—Buenas tardes. Llamo por el cuarto. ¿Puedo pasar a verlo hoy?",
      "Guten Tag. Ich rufe wegen des Zimmers an. Kann ich heute vorbeikommen und es mir ansehen?",
      "Good afternoon. I'm calling about the room. Could I come round and see it today?",
      "Καλησπέρα. Τηλεφωνώ για το δωμάτιο. Μπορώ να περάσω να το δω σήμερα;"),
    Z("—Cómo no, mija. Es la puerta azul. Aquí la espero.",
      "Aber gern, Kindchen. Es ist die blaue Tür. Ich warte hier auf Sie.",
      "Of course, love. It's the blue door. I'll be waiting for you.",
      "Και βέβαια, κορίτσι μου. Είναι η μπλε πόρτα. Σας περιμένω εδώ."),
    Z("Cinco minutos después, Lotte toca la puerta azul. Abre una señora bajita, con un delantal de flores y un perro pequeño debajo del brazo.",
      "Fünf Minuten später klopft Lotte an die blaue Tür. Eine kleine Frau öffnet, mit einer geblümten Schürze und einem kleinen Hund unter dem Arm.",
      "Five minutes later, Lotte knocks on the blue door. A short woman opens it, wearing a flowery apron, with a little dog under her arm.",
      "Πέντε λεπτά αργότερα, η Λότε χτυπάει την μπλε πόρτα. Ανοίγει μια κοντή κυρία με λουλουδάτη ποδιά κι ένα μικρό σκυλάκι κάτω από το μπράτσο."),
    Z("—Buenas tardes, pásele. ¿Usted es quien llamó por el cuarto?",
      "Guten Tag, kommen Sie rein. Sind Sie die, die wegen des Zimmers angerufen hat?",
      "Good afternoon, come in. Are you the one who called about the room?",
      "Καλησπέρα, περάστε. Εσείς τηλεφωνήσατε για το δωμάτιο;"),
    Z("—Sí, soy yo. Quería ver el cuarto; busco algo que esté cerca del metro. Y que tenga luz.",
      "Ja, das bin ich. Ich würde gern das Zimmer sehen; ich suche etwas, das nah an der Metro liegt. Und das hell ist.",
      "Yes, that's me. I'd like to see the room; I'm looking for something close to the metro. And with plenty of light.",
      "Ναι, εγώ είμαι. Θα ήθελα να δω το δωμάτιο· ψάχνω κάτι που να είναι κοντά στο μετρό. Και να έχει φως."),
    Z("—Está a cinco minutos de la estación. La renta son seis mil pesos al mes. Pásele, pásele. Soy Lupita. Doña Lupita, para los inquilinos. Y este es Chicharrón.",
      "Die Station ist fünf Minuten von hier. Die Miete beträgt sechstausend Pesos im Monat. Kommen Sie rein, kommen Sie rein. Ich bin Lupita. Doña Lupita, für die Mieter. Und das ist Chicharrón.",
      "It's five minutes from the station. The rent is six thousand pesos a month. Come in, come in. I'm Lupita. Doña Lupita, to the tenants. And this is Chicharrón.",
      "Είναι πέντε λεπτά από τον σταθμό. Το νοίκι είναι έξι χιλιάδες πέσος τον μήνα. Περάστε, περάστε. Είμαι η Λουπίτα. Η κυρία Λουπίτα, για τους ενοικιαστές. Κι αυτός είναι ο Τσιτσαρόν."),
    Z("El cuarto tiene una cama, un escritorio y una ventana grande que da a un patio con una jacaranda.",
      "Das Zimmer hat ein Bett, einen Schreibtisch und ein großes Fenster zu einem Innenhof mit einem Jacarandabaum.",
      "The room has a bed, a desk and a big window that looks onto a courtyard with a jacaranda tree.",
      "Το δωμάτιο έχει ένα κρεβάτι, ένα γραφείο κι ένα μεγάλο παράθυρο που βλέπει σε μια αυλή με μια τζακαράντα."),
    Z("—Es perfecto. ¿El precio incluye la luz y el internet?",
      "Es ist perfekt. Sind Strom und Internet im Preis enthalten?",
      "It's perfect. Does the price include electricity and internet?",
      "Είναι τέλειο. Η τιμή περιλαμβάνει ρεύμα και ίντερνετ;"),
    Z("—Sí, todo incluido. Solo le pido un mes de depósito y firmamos un contrato sencillo. Ah, y el gas va aparte, pero es poquito.",
      "Ja, alles inklusive. Ich verlange nur eine Monatsmiete Kaution, und wir unterschreiben einen einfachen Vertrag. Ach ja, das Gas kommt extra dazu, aber das ist nur ganz wenig.",
      "Yes, everything included. I just ask for one month's deposit, and we sign a simple contract. Oh, and gas is extra, but it's only a tiny bit.",
      "Ναι, όλα μέσα. Σας ζητάω μόνο ένα νοίκι εγγύηση και υπογράφουμε ένα απλό συμβόλαιο. Α, και το γκάζι είναι χωριστά, αλλά είναι λιγάκι."),
    Z("—¿Y el depósito me lo devuelve al final?",
      "Und die Kaution bekomme ich am Ende zurück?",
      "And do I get the deposit back at the end?",
      "Και την εγγύηση μου την επιστρέφετε στο τέλος;"),
    Z("—Claro. Se lo devuelvo cuando se vaya, si todo está bien.",
      "Natürlich. Die gebe ich Ihnen zurück, wenn Sie ausziehen, wenn alles in Ordnung ist.",
      "Of course. I'll give it back to you when you leave, if everything's fine.",
      "Βεβαίως. Σας την επιστρέφω όταν φύγετε, αν όλα είναι εντάξει."),
    Z("—Perfecto. Quería quedarme desde el lunes, si le parece bien.",
      "Perfekt. Ich würde gern ab Montag bleiben, wenn es Ihnen recht ist.",
      "Perfect. I'd like to stay from Monday, if that suits you.",
      "Τέλεια. Θα ήθελα να μείνω από τη Δευτέρα, αν σας είναι εντάξει."),
    Z("—Claro que sí. Hacemos el contrato de un mes, sencillito, y listo.",
      "Aber natürlich. Wir machen den Vertrag über einen Monat, ganz einfach, und fertig.",
      "Of course. We'll do the contract for one month, nice and simple, and that's that.",
      "Και βέβαια. Κάνουμε το συμβόλαιο για έναν μήνα, απλό απλό, και τελειώσαμε."),
    Z("—Muy bien. ¿Y vosotros vivís aquí también?",
      "Sehr gut. Und wohnt ihr auch hier?",
      "Very good. And do you all live here too?",
      "Πολύ ωραία. Κι εσείς μένετε επίσης εδώ;"),
    Z("—¿Vosotros? ¡Ay, qué bonito! Así hablan en España. Aquí decimos «ustedes», mija. ¿Que si ustedes viven aquí? Sí: mi hijo Toño, Chicharrón y yo.",
      "„Vosotros“? Ach, wie hübsch! So spricht man in Spanien. Hier sagen wir „ustedes“, Kindchen. Ob wir hier wohnen? Ja: mein Sohn Toño, Chicharrón und ich.",
      "“Vosotros”? Oh, how lovely! That's how they talk in Spain. Here we say “ustedes”, love. Whether we live here? Yes: my son Toño, Chicharrón and me.",
      "«Vosotros»; Αχ, τι ωραίο! Έτσι μιλάνε στην Ισπανία. Εδώ λέμε «ustedes», κορίτσι μου. Αν μένουμε εδώ; Ναι: ο γιος μου ο Τόνιο, ο Τσιτσαρόν κι εγώ."),
    Z("—Entonces, ¿se lo queda?",
      "Also, nehmen Sie es?",
      "So, will you take it?",
      "Λοιπόν, το κρατάτε;"),
    Z("—Sí. Vale.",
      "Ja. Okay.",
      "Yes. Okay.",
      "Ναι. Εντάξει."),
    Z("—¿Vale? Aquí no decimos «vale», mija. Decimos «sale» o «está bien». Pero se le entiende todo, no se preocupe.",
      "„Vale“? Hier sagen wir nicht „vale“, Kindchen. Wir sagen „sale“ oder „está bien“. Aber man versteht Sie ganz genau, keine Sorge.",
      "“Vale”? Here we don't say “vale”, love. We say “sale” or “está bien”. But we understand you perfectly, don't worry.",
      "«Vale»; Εδώ δεν λέμε «vale», κορίτσι μου. Λέμε «sale» ή «está bien». Αλλά σας καταλαβαίνουμε μια χαρά, μην ανησυχείτε."),
    Z("—¿Me da su número de móvil, doña Lupita?",
      "Geben Sie mir Ihre Handynummer, Doña Lupita?",
      "Could you give me your mobile number, Doña Lupita?",
      "Μου δίνετε τον αριθμό του κινητού σας, κυρία Λουπίτα;"),
    Z("—De celular, querrá decir. Aquí un móvil es eso que cuelga encima de la cuna de un bebé.",
      "Von meinem Celular, meinen Sie wohl. Hier ist ein „móvil“ das Ding, das über dem Babybett hängt.",
      "My celular, you mean. Here a “móvil” is that thing that hangs over a baby's cot.",
      "Του «celular», θέλετε να πείτε. Εδώ «móvil» είναι αυτό που κρέμεται πάνω από την κούνια ενός μωρού."),
    Z("—¿Y me puede dar las llaves hoy?",
      "Und können Sie mir heute die Schlüssel geben?",
      "And can you give me the keys today?",
      "Και μπορείτε να μου δώσετε τα κλειδιά σήμερα;"),
    Z("—Sí, ahorita se las doy.",
      "Ja, ich gebe sie Ihnen gleich.",
      "Yes, I'll give them to you right now.",
      "Ναι, σας τα δίνω αμέσως."),
    Z("Lotte espera. Media hora. Doña Lupita prepara café de olla, con canela, y le enseña fotos de sus nietos. A las dos horas aparecen las llaves.",
      "Lotte wartet. Eine halbe Stunde. Doña Lupita kocht Café de olla mit Zimt und zeigt ihr Fotos von ihren Enkeln. Nach zwei Stunden tauchen die Schlüssel auf.",
      "Lotte waits. Half an hour. Doña Lupita makes café de olla with cinnamon and shows her photos of her grandchildren. Two hours later, the keys turn up.",
      "Η Λότε περιμένει. Μισή ώρα. Η κυρία Λουπίτα φτιάχνει café de olla με κανέλα και της δείχνει φωτογραφίες από τα εγγόνια της. Ύστερα από δύο ώρες εμφανίζονται τα κλειδιά."),
    Z("Primera palabra del lugar en el cuaderno: ahorita. Significa «ahora». O «dentro de un rato». O «mañana». Depende.",
      "Erstes Wort des Ortes im Notizbuch: ahorita. Es bedeutet „jetzt“. Oder „gleich“. Oder „morgen“. Kommt darauf an.",
      "First word of the place in the notebook: ahorita. It means “now”. Or “in a little while”. Or “tomorrow”. It depends.",
      "Πρώτη λέξη του τόπου στο σημειωματάριο: ahorita. Σημαίνει «τώρα». Ή «σε λίγο». Ή «αύριο». Εξαρτάται."),
    Z("El domingo, doña Lupita la lleva a Xochimilco, a los últimos canales del gran lago: agua verde, flores y trajineras, unas barcas largas de colores.",
      "Am Sonntag nimmt Doña Lupita sie mit nach Xochimilco, zu den letzten Kanälen des großen Sees: grünes Wasser, Blumen und Trajineras, lange bunte Boote.",
      "On Sunday, Doña Lupita takes her to Xochimilco, to the last canals of the great lake: green water, flowers and trajineras, long colourful boats.",
      "Την Κυριακή η κυρία Λουπίτα την πάει στο Σοτσιμίλκο, στα τελευταία κανάλια της μεγάλης λίμνης: πράσινο νερό, λουλούδια και τραχινέρας, μακριές πολύχρωμες βάρκες."),
    Z("Lotte levanta la Leica. Una trajinera que se llama Lupita, el reflejo de las flores en el agua. Clic. La primera foto de «Agua».",
      "Lotte hebt die Leica. Eine Trajinera, die Lupita heißt, das Spiegelbild der Blumen im Wasser. Klick. Das erste Foto für «Agua».",
      "Lotte raises the Leica. A trajinera called Lupita, the reflection of the flowers in the water. Click. The first picture of «Agua».",
      "Η Λότε σηκώνει τη Leica. Μια τραχινέρα που λέγεται Λουπίτα, η αντανάκλαση των λουλουδιών στο νερό. Κλικ. Η πρώτη φωτογραφία του «Agua»."),
    Z("Esa noche le manda la foto a Bram. Su respuesta llega en cuatro segundos: «¡Por fin!».",
      "An diesem Abend schickt sie Bram das Foto. Seine Antwort kommt nach vier Sekunden: „Endlich!“",
      "That night she sends Bram the picture. His reply arrives in four seconds: “At last!”",
      "Εκείνο το βράδυ στέλνει τη φωτογραφία στον Μπραμ. Η απάντησή του έρχεται σε τέσσερα δευτερόλεπτα: «Επιτέλους!»"),
    Z("Postal para Oma Fenna, Utrecht: «Querida Oma: vivo en una casa azul con una señora que se llama Lupita y un perro que se llama Chicharrón. Aquí la ciudad era un lago. A Opa Kees le encantaría. Besos, Lotte».",
      "Postkarte an Oma Fenna, Utrecht: „Liebe Oma, ich wohne in einem blauen Haus mit einer Frau, die Lupita heißt, und einem Hund, der Chicharrón heißt. Hier war die Stadt ein See. Opa Kees würde es lieben. Küsse, Lotte.“",
      "Postcard to Oma Fenna, Utrecht: “Dear Oma, I live in a blue house with a lady called Lupita and a dog called Chicharrón. Here the city used to be a lake. Opa Kees would love it. Love, Lotte.”",
      "Καρτ ποστάλ για την Όμα Φένα, Ουτρέχτη: «Αγαπημένη γιαγιά, μένω σε ένα μπλε σπίτι με μια κυρία που τη λένε Λουπίτα κι ένα σκύλο που τον λένε Τσιτσαρόν. Εδώ η πόλη ήταν λίμνη. Ο Όπα Κέις θα το λάτρευε. Φιλιά, Λότε.»")
  ]));

  // ── Station 2 · familie ──────────────────────────────
  K.push(S(2, "familie", "Un vaso de agua para los que vuelven",
    { de: "Día de Muertos in Oaxaca: Doña Lupitas Familie baut die Ofrenda auf — und erzählt von den Großeltern. Lotte erzählt von Opa Kees.",
      en: "Day of the Dead in Oaxaca: Doña Lupita's family sets up the ofrenda — and tells stories about their grandparents. Lotte tells them about Opa Kees.",
      el: "Ημέρα των Νεκρών στην Οαχάκα: η οικογένεια της κυρίας Λουπίτα στήνει την ofrenda — και διηγείται ιστορίες για τους παππούδες. Η Λότε μιλάει για τον Όπα Κέις." },
  [
    Z("A finales de octubre, la casa azul de Coyoacán huele a chocolate y a flores naranjas.",
      "Ende Oktober riecht das blaue Haus in Coyoacán nach Schokolade und orangefarbenen Blumen.",
      "At the end of October, the blue house in Coyoacán smells of chocolate and orange flowers.",
      "Στα τέλη Οκτωβρίου το μπλε σπίτι στο Κογιοακάν μυρίζει σοκολάτα και πορτοκαλί λουλούδια."),
    Z("—Mija, ¿qué va a hacer el uno de noviembre? —le pregunta doña Lupita una mañana.",
      "„Kindchen, was machen Sie am ersten November?“, fragt Doña Lupita sie eines Morgens.",
      "“Love, what are you doing on the first of November?” Doña Lupita asks her one morning.",
      "«Κορίτσι μου, τι θα κάνετε την πρώτη Νοεμβρίου;» τη ρωτάει ένα πρωί η κυρία Λουπίτα."),
    Z("—Nada especial. ¿Por qué?",
      "Nichts Besonderes. Warum?",
      "Nothing special. Why?",
      "Τίποτα ιδιαίτερο. Γιατί;"),
    Z("—Porque se viene con nosotros a Oaxaca, al pueblo de mi familia. Es Día de Muertos. Toño maneja.",
      "Weil Sie mit uns nach Oaxaca kommen, in das Dorf meiner Familie. Es ist Día de Muertos. Toño fährt.",
      "Because you're coming with us to Oaxaca, to my family's village. It's the Day of the Dead. Toño's driving.",
      "Γιατί θα έρθετε μαζί μας στην Οαχάκα, στο χωριό της οικογένειάς μου. Είναι η Ημέρα των Νεκρών. Οδηγεί ο Τόνιο."),
    Z("No es una pregunta. Lotte ya lo sabe: cuando doña Lupita dice «se viene», uno va.",
      "Das ist keine Frage. Lotte weiß es inzwischen: Wenn Doña Lupita „Sie kommen mit“ sagt, dann fährt man mit.",
      "It isn't a question. Lotte knows by now: when Doña Lupita says “you're coming”, you go.",
      "Δεν είναι ερώτηση. Η Λότε το ξέρει πια: όταν η κυρία Λουπίτα λέει «θα έρθετε», πηγαίνεις."),
    Z("Toño es su hijo: treinta y ocho años, bigote, ingeniero, y un carro rojo que tiene casi su misma edad. Su hija Ximena, de nueve años, viene también.",
      "Toño ist ihr Sohn: achtunddreißig Jahre alt, Schnurrbart, Ingenieur, und ein rotes Auto, das fast so alt ist wie er. Seine Tochter Ximena, neun Jahre alt, kommt auch mit.",
      "Toño is her son: thirty-eight, moustache, engineer, and a red car that's almost as old as he is. His daughter Ximena, nine years old, is coming too.",
      "Ο Τόνιο είναι ο γιος της: τριάντα οκτώ χρονών, μουστάκι, μηχανικός, κι ένα κόκκινο αυτοκίνητο σχεδόν όσο χρονών είναι κι αυτός. Η κόρη του η Χιμένα, εννιά χρονών, έρχεται κι αυτή."),
    Z("Salen de noche. Toño maneja seis horas por la sierra, con música de banda y una bolsa de cacahuates. Ximena se duerme con la cabeza en el hombro de Lotte.",
      "Sie fahren nachts los. Toño fährt sechs Stunden durch die Berge, mit Banda-Musik und einer Tüte Erdnüsse. Ximena schläft mit dem Kopf auf Lottes Schulter ein.",
      "They leave at night. Toño drives for six hours through the mountains, with banda music and a bag of peanuts. Ximena falls asleep with her head on Lotte's shoulder.",
      "Ξεκινούν νύχτα. Ο Τόνιο οδηγεί έξι ώρες μέσα από τα βουνά, με μουσική μπάντα κι ένα σακουλάκι φιστίκια. Η Χιμένα αποκοιμιέται με το κεφάλι στον ώμο της Λότε."),
    Z("Al amanecer llegan al valle de Oaxaca. A los dos lados del camino hay campos enormes de flores naranjas.",
      "Bei Sonnenaufgang erreichen sie das Tal von Oaxaca. Auf beiden Seiten der Straße gibt es riesige Felder mit orangefarbenen Blumen.",
      "At dawn they reach the valley of Oaxaca. On both sides of the road there are huge fields of orange flowers.",
      "Με το χάραμα φτάνουν στην κοιλάδα της Οαχάκα. Και από τις δύο πλευρές του δρόμου υπάρχουν τεράστια χωράφια με πορτοκαλί λουλούδια."),
    Z("—Es cempasúchil —explica Toño—. La flor de los muertos. Este verano llovió mucho, por eso hay tantas.",
      "„Das ist Cempasúchil“, erklärt Toño. „Die Blume der Toten. Diesen Sommer hat es viel geregnet, deshalb gibt es so viele.“",
      "“It's cempasúchil,” Toño explains. “The flower of the dead. It rained a lot this summer, that's why there are so many.”",
      "«Είναι cempasúchil», εξηγεί ο Τόνιο. «Το λουλούδι των νεκρών. Αυτό το καλοκαίρι έβρεξε πολύ, γι' αυτό υπάρχουν τόσα πολλά.»"),
    Z("La lluvia de julio, convertida en flores en noviembre. Lotte saca la cámara por la ventanilla.",
      "Der Regen vom Juli, im November zu Blumen geworden. Lotte hält die Kamera aus dem Fenster.",
      "July's rain, turned into flowers in November. Lotte holds the camera out of the window.",
      "Η βροχή του Ιουλίου, που έγινε λουλούδια τον Νοέμβριο. Η Λότε βγάζει τη μηχανή από το παράθυρο."),
    Z("Por la tarde van al panteón, el cementerio del pueblo. Hay familias enteras limpiando las tumbas: barren, lavan las piedras con cubetas de agua, ponen flores y velas.",
      "Am Nachmittag gehen sie zum Panteón, dem Friedhof des Dorfes. Ganze Familien putzen die Gräber: Sie fegen, waschen die Steine mit Eimern voll Wasser, stellen Blumen und Kerzen auf.",
      "In the afternoon they go to the panteón, the village cemetery. Whole families are cleaning the graves: they sweep, wash the stones with buckets of water, put out flowers and candles.",
      "Το απόγευμα πηγαίνουν στο panteón, το νεκροταφείο του χωριού. Ολόκληρες οικογένειες καθαρίζουν τους τάφους: σκουπίζουν, πλένουν τις πέτρες με κουβάδες νερό, βάζουν λουλούδια και κεριά."),
    Z("Nadie está triste. Los niños corren, alguien toca la guitarra y una señora vende tamales.",
      "Niemand ist traurig. Die Kinder rennen herum, jemand spielt Gitarre, und eine Frau verkauft Tamales.",
      "Nobody is sad. The children run around, someone plays the guitar and a woman sells tamales.",
      "Κανείς δεν είναι λυπημένος. Τα παιδιά τρέχουν, κάποιος παίζει κιθάρα και μια κυρία πουλάει ταμάλες."),
    Z("En la casa del pueblo, la familia pone la ofrenda: una mesa con tres escalones, papel picado de colores, velas, pan de muerto, chocolate, fruta y muchas fotos.",
      "Im Haus im Dorf baut die Familie die Ofrenda auf: einen Tisch mit drei Stufen, buntes Scherenschnittpapier, Kerzen, Pan de muerto, Schokolade, Obst und viele Fotos.",
      "In the house in the village, the family sets up the ofrenda: a table with three steps, coloured cut-paper banners, candles, pan de muerto, chocolate, fruit and lots of photos.",
      "Στο σπίτι του χωριού η οικογένεια στήνει την ofrenda: ένα τραπέζι με τρία σκαλοπάτια, πολύχρωμο σκαλιστό χαρτί, κεριά, pan de muerto, σοκολάτα, φρούτα και πολλές φωτογραφίες."),
    Z("—¿Y ese vaso de agua? —pregunta Lotte.",
      "„Und dieses Glas Wasser?“, fragt Lotte.",
      "“And that glass of water?” Lotte asks.",
      "«Κι αυτό το ποτήρι νερό;» ρωτάει η Λότε."),
    Z("—Es para los muertos —dice Ximena, muy seria—. Vienen de muy lejos y llegan con sed.",
      "„Das ist für die Toten“, sagt Ximena sehr ernst. „Sie kommen von ganz weit her und haben Durst, wenn sie ankommen.“",
      "“It's for the dead,” says Ximena, very seriously. “They come from very far away and they arrive thirsty.”",
      "«Είναι για τους νεκρούς», λέει η Χιμένα πολύ σοβαρά. «Έρχονται από πολύ μακριά και φτάνουν διψασμένοι.»"),
    Z("Doña Lupita pone una foto en blanco y negro en el centro: un señor con sombrero y una sonrisa enorme.",
      "Doña Lupita stellt ein Schwarz-Weiß-Foto in die Mitte: ein Mann mit Hut und einem riesigen Lächeln.",
      "Doña Lupita places a black-and-white photo in the middle: a man in a hat with an enormous smile.",
      "Η κυρία Λουπίτα βάζει στη μέση μια ασπρόμαυρη φωτογραφία: ένας κύριος με καπέλο κι ένα τεράστιο χαμόγελο."),
    Z("—Este era mi abuelo, don Chencho. Era campesino. Sembraba maíz y frijol aquí, en el valle. Todas las mañanas se levantaba a las cinco y cantaba.",
      "„Das war mein Großvater, Don Chencho. Er war Bauer. Er baute hier im Tal Mais und Bohnen an. Jeden Morgen stand er um fünf auf und sang.“",
      "“This was my grandfather, Don Chencho. He was a farmer. He grew maize and beans here, in the valley. Every morning he got up at five and sang.”",
      "«Αυτός ήταν ο παππούς μου, ο δον Τσέντσο. Ήταν αγρότης. Έσπερνε καλαμπόκι και φασόλια εδώ, στην κοιλάδα. Κάθε πρωί σηκωνόταν στις πέντε και τραγουδούσε.»"),
    Z("—¿Y cantaba bien?",
      "Und sang er gut?",
      "And did he sing well?",
      "Και τραγουδούσε καλά;"),
    Z("—Cantaba fatal. Pero cantaba.",
      "Er sang furchtbar. Aber er sang.",
      "He sang terribly. But he sang.",
      "Τραγουδούσε απαίσια. Αλλά τραγουδούσε."),
    Z("Toda la familia se ríe. Toño imita al bisabuelo, con voz de gallo.",
      "Die ganze Familie lacht. Toño macht den Urgroßvater nach, mit einer Stimme wie ein Hahn.",
      "The whole family laughs. Toño does an impression of his great-grandfather, with a voice like a rooster.",
      "Όλη η οικογένεια γελάει. Ο Τόνιο μιμείται τον προπάππου, με φωνή κόκορα."),
    Z("—Un año no llovió nada —sigue doña Lupita—. El maíz se secó. Entonces mi abuelo hizo un pozo con sus propias manos. Tardó tres meses. Y un día encontró agua.",
      "„Ein Jahr hat es überhaupt nicht geregnet“, erzählt Doña Lupita weiter. „Der Mais vertrocknete. Da grub mein Großvater mit seinen eigenen Händen einen Brunnen. Er brauchte drei Monate. Und eines Tages fand er Wasser.“",
      "“One year it didn't rain at all,” Doña Lupita goes on. “The maize dried up. So my grandfather dug a well with his own hands. It took him three months. And one day he found water.”",
      "«Μια χρονιά δεν έβρεξε καθόλου», συνεχίζει η κυρία Λουπίτα. «Το καλαμπόκι ξεράθηκε. Τότε ο παππούς μου έσκαψε ένα πηγάδι με τα ίδια του τα χέρια. Του πήρε τρεις μήνες. Και μια μέρα βρήκε νερό.»"),
    Z("—¿Y qué hizo cuando lo encontró?",
      "Und was hat er gemacht, als er es fand?",
      "And what did he do when he found it?",
      "Και τι έκανε όταν το βρήκε;"),
    Z("—Se puso a cantar, claro. Y esa noche todo el pueblo vino a tomar agua de su pozo.",
      "Er fing an zu singen, natürlich. Und an diesem Abend kam das ganze Dorf, um Wasser aus seinem Brunnen zu trinken.",
      "He started singing, of course. And that night the whole village came to drink water from his well.",
      "Άρχισε να τραγουδάει, φυσικά. Κι εκείνο το βράδυ όλο το χωριό ήρθε να πιει νερό από το πηγάδι του."),
    Z("—Por eso, en esta casa, el vaso de agua siempre es el más grande de la ofrenda —dice Toño.",
      "„Deshalb ist in diesem Haus das Glas Wasser immer das größte auf der Ofrenda“, sagt Toño.",
      "“That's why, in this house, the glass of water is always the biggest one on the ofrenda,” says Toño.",
      "«Γι' αυτό, σε αυτό το σπίτι, το ποτήρι με το νερό είναι πάντα το πιο μεγάλο της ofrenda», λέει ο Τόνιο."),
    Z("Toño pone otra foto, más pequeña: el papá de doña Lupita, con lentes gruesos y un vaso en la mano. Después mira a Lotte.",
      "Toño stellt ein zweites, kleineres Foto dazu: Doña Lupitas Vater, mit dicker Brille und einem Glas in der Hand. Dann sieht er Lotte an.",
      "Toño puts up another, smaller photo: Doña Lupita's father, with thick glasses and a glass in his hand. Then he looks at Lotte.",
      "Ο Τόνιο βάζει άλλη μια φωτογραφία, πιο μικρή: τον πατέρα της κυρίας Λουπίτα, με χοντρά γυαλιά κι ένα ποτήρι στο χέρι. Ύστερα κοιτάζει τη Λότε."),
    Z("—Este es mi abuelo Chucho; le encantaba el mezcal. ¿Quieres poner una foto de alguien tuyo?",
      "Das ist mein Opa Chucho; er liebte Mezcal. Willst du ein Foto von jemandem aus deiner Familie dazustellen?",
      "This is my grandad Chucho; he loved mezcal. Would you like to put up a photo of someone of yours?",
      "Αυτός είναι ο παππούς μου ο Τσούτσο· λάτρευε το μεσκάλ. Θέλεις να βάλεις μια φωτογραφία από κάποιον δικό σου;"),
    Z("—Sí, una foto de mi abuelo. Murió hace cinco años, en invierno. Ese día el canal estaba congelado.",
      "Ja, ein Foto von meinem Großvater. Er ist vor fünf Jahren gestorben, im Winter. An diesem Tag war der Kanal zugefroren.",
      "Yes, a photo of my grandfather. He died five years ago, in winter. That day the canal was frozen.",
      "Ναι, μια φωτογραφία του παππού μου. Πέθανε πριν από πέντε χρόνια, τον χειμώνα. Εκείνη τη μέρα το κανάλι ήταν παγωμένο."),
    Z("Lotte saca la foto de dentro del cuaderno: Opa Kees con su gorra azul, delante de la esclusa.",
      "Lotte holt das Foto aus dem Notizbuch: Opa Kees mit seiner blauen Mütze vor der Schleuse.",
      "Lotte takes the photo out of her notebook: Opa Kees in his blue cap, in front of the lock.",
      "Η Λότε βγάζει τη φωτογραφία από το σημειωματάριο: ο Όπα Κέις με το μπλε του κασκέτο, μπροστά στον υδατοφράκτη."),
    Z("—¿Y cómo era? ¿Qué le gustaba hacer? —pregunta Toño.",
      "„Und wie war er? Was hat er gern gemacht?“, fragt Toño.",
      "“And what was he like? What did he like doing?” asks Toño.",
      "«Και πώς ήταν; Τι του άρεσε να κάνει;» ρωτάει ο Τόνιο."),
    Z("—Era muy tranquilo. Tenía un barco y pescaba todos los domingos. Y era guardián de una esclusa. ¿Saben qué es una esclusa?",
      "Er war sehr ruhig. Er hatte ein Boot und ging jeden Sonntag angeln. Und er war Schleusenwärter. Wisst ihr, was eine Schleuse ist?",
      "He was very calm. He had a boat and went fishing every Sunday. And he was a lock keeper. Do you know what a lock is?",
      "Ήταν πολύ ήρεμος. Είχε μια βάρκα και ψάρευε κάθε Κυριακή. Και ήταν φύλακας σε υδατοφράκτη. Ξέρετε τι είναι υδατοφράκτης;"),
    Z("Nadie lo sabe. Lotte lo explica con las manos: una puerta en el canal, el agua sube, el barco pasa.",
      "Niemand weiß es. Lotte erklärt es mit den Händen: ein Tor im Kanal, das Wasser steigt, das Schiff fährt durch.",
      "Nobody knows. Lotte explains it with her hands: a gate in the canal, the water rises, the boat goes through.",
      "Κανείς δεν ξέρει. Η Λότε το εξηγεί με τα χέρια: μια πύλη στο κανάλι, το νερό ανεβαίνει, το καράβι περνάει."),
    Z("—Cuando yo era niña, pasaba los veranos con él. Él abría las puertas y yo contaba los barcos. Un día pasaron ciento doce. Fue el mejor día de mi vida.",
      "Als ich ein Kind war, verbrachte ich die Sommer bei ihm. Er öffnete die Tore, und ich zählte die Schiffe. Einmal fuhren hundertzwölf durch. Das war der schönste Tag meines Lebens.",
      "When I was a little girl, I used to spend the summers with him. He opened the gates and I counted the boats. One day a hundred and twelve went through. It was the best day of my life.",
      "Όταν ήμουν παιδί, περνούσα τα καλοκαίρια μαζί του. Εκείνος άνοιγε τις πύλες κι εγώ μετρούσα τα καράβια. Μια μέρα πέρασαν εκατόν δώδεκα. Ήταν η καλύτερη μέρα της ζωής μου."),
    Z("Todos miran la foto en silencio. Después doña Lupita le toca el brazo a Lotte, toma la foto y la pone en la ofrenda, al lado de don Chencho.",
      "Alle betrachten schweigend das Foto. Dann berührt Doña Lupita Lottes Arm, nimmt das Foto und stellt es auf die Ofrenda, neben Don Chencho.",
      "Everyone looks at the photo in silence. Then Doña Lupita touches Lotte's arm, takes the photo and puts it on the ofrenda, next to Don Chencho.",
      "Όλοι κοιτάζουν σιωπηλοί τη φωτογραφία. Ύστερα η κυρία Λουπίτα αγγίζει το μπράτσο της Λότε, παίρνει τη φωτογραφία και τη βάζει στην ofrenda, δίπλα στον δον Τσέντσο."),
    Z("—Ya está. Un campesino que buscaba agua y un guardián del agua. Se van a llevar muy bien.",
      "So. Ein Bauer, der Wasser suchte, und ein Wächter des Wassers. Die zwei werden sich sehr gut verstehen.",
      "There we are. A farmer who searched for water and a keeper of water. They'll get on very well.",
      "Ορίστε. Ένας αγρότης που έψαχνε νερό κι ένας φύλακας του νερού. Θα τα πάνε πολύ καλά."),
    Z("—Entonces le ponemos un vaso de agua fresca. ¿Y tu abuela vive todavía? —pregunta Toño.",
      "„Dann stellen wir ihm ein Glas frisches Wasser hin. Und deine Oma, lebt sie noch?“, fragt Toño.",
      "“Then we'll put out a glass of fresh water for him. And is your grandmother still alive?” asks Toño.",
      "«Τότε του βάζουμε ένα ποτήρι δροσερό νερό. Κι η γιαγιά σου ζει ακόμα;» ρωτάει ο Τόνιο."),
    Z("—Sí, mi abuela Fenna vive en Utrecht. Ayer le mandé una postal. Tiene ochenta y siete años y todavía anda en bicicleta.",
      "Ja, meine Oma Fenna lebt in Utrecht. Gestern habe ich ihr eine Postkarte geschickt. Sie ist siebenundachtzig und fährt immer noch Fahrrad.",
      "Yes, my grandmother Fenna lives in Utrecht. I sent her a postcard yesterday. She's eighty-seven and she still rides a bike.",
      "Ναι, η γιαγιά μου η Φένα ζει στην Ουτρέχτη. Χθες της έστειλα μια κάρτα. Είναι ογδόντα εφτά χρονών και κάνει ακόμα ποδήλατο."),
    Z("—¿En bicicleta? —Ximena no lo puede creer.",
      "„Fahrrad?“ Ximena kann es nicht glauben.",
      "“A bike?” Ximena can't believe it.",
      "«Ποδήλατο;» Η Χιμένα δεν μπορεί να το πιστέψει."),
    Z("—¿Le puedo poner yo el vaso de agua a tu abuelo? —pregunta Ximena.",
      "„Darf ich deinem Opa das Glas Wasser hinstellen?“, fragt Ximena.",
      "“Can I put the glass of water out for your grandad?” asks Ximena.",
      "«Μπορώ να βάλω εγώ το ποτήρι νερό για τον παππού σου;» ρωτάει η Χιμένα."),
    Z("—Vale.",
      "Okay.",
      "Okay.",
      "Εντάξει."),
    Z("—¿Vale? —Ximena se ríe—. Aquí no decimos «vale», Lotte. Decimos «sale». O «sí» y ya.",
      "„Vale?“ Ximena lacht. „Hier sagen wir nicht ‚vale‘, Lotte. Wir sagen ‚sale‘. Oder einfach ‚sí‘.“",
      "“Vale?” Ximena laughs. “Here we don't say ‘vale’, Lotte. We say ‘sale’. Or just ‘sí’.”",
      "«Vale;» Η Χιμένα γελάει. «Εδώ δεν λέμε “vale”, Λότε. Λέμε “sale”. Ή απλώς “sí”.»"),
    Z("Esa noche, en el panteón, hay miles de velas. Las familias se sientan junto a las tumbas, comen y platican, con los vivos y con los muertos.",
      "In dieser Nacht brennen auf dem Friedhof tausende Kerzen. Die Familien sitzen an den Gräbern, essen und plaudern, mit den Lebenden und mit den Toten.",
      "That night, in the cemetery, there are thousands of candles. The families sit by the graves, eating and chatting, with the living and with the dead.",
      "Εκείνη τη νύχτα, στο νεκροταφείο, υπάρχουν χιλιάδες κεριά. Οι οικογένειες κάθονται δίπλα στους τάφους, τρώνε και κουβεντιάζουν, με τους ζωντανούς και με τους νεκρούς."),
    Z("A las once vibra el celular. Bram: «Lotte, ¿fotos de un cementerio? ¿No era un libro sobre el agua?».",
      "Um elf vibriert das Handy. Bram: „Lotte, Fotos von einem Friedhof? War das nicht ein Buch über das Wasser?“",
      "At eleven her phone buzzes. Bram: “Lotte, pictures of a cemetery? Wasn't this a book about water?”",
      "Στις έντεκα δονείται το κινητό. Ο Μπραμ: «Λότε, φωτογραφίες από νεκροταφείο; Δεν ήταν ένα βιβλίο για το νερό;»"),
    Z("Lotte le contesta con una sola foto: el vaso de agua entre las velas, con la luz temblando dentro. Y una frase: «Bram, confía en mí».",
      "Lotte antwortet ihm mit einem einzigen Foto: das Glas Wasser zwischen den Kerzen, mit dem Licht, das darin zittert. Und einem Satz: „Bram, vertrau mir.“",
      "Lotte replies with a single picture: the glass of water among the candles, the light trembling inside it. And one sentence: “Bram, trust me.”",
      "Η Λότε του απαντά με μία μόνο φωτογραφία: το ποτήρι με το νερό ανάμεσα στα κεριά, με το φως να τρεμοπαίζει μέσα του. Και μια φράση: «Μπραμ, εμπιστέψου με.»"),
    Z("Palabra del lugar: ofrenda. Lo que uno da a la gente que quiere, aunque ya no esté.",
      "Wort des Ortes: ofrenda. Das, was man den Menschen gibt, die man liebt, auch wenn sie nicht mehr da sind.",
      "Word of the place: ofrenda. What you give to the people you love, even if they're no longer here.",
      "Λέξη του τόπου: ofrenda. Αυτό που δίνεις στους ανθρώπους που αγαπάς, ακόμα κι αν δεν είναι πια εδώ."),
    Z("Postal para Oma Fenna: «Querida Oma: Opa Kees pasó la noche en Oaxaca, al lado de un campesino que cantaba fatal. Le pusimos un vaso de agua. Creo que le gustó. Tú sigue en bicicleta, por favor. Te quiero, Lotte».",
      "Postkarte an Oma Fenna: „Liebe Oma, Opa Kees hat die Nacht in Oaxaca verbracht, neben einem Bauern, der furchtbar sang. Wir haben ihm ein Glas Wasser hingestellt. Ich glaube, es hat ihm gefallen. Und du fährst bitte weiter Fahrrad. Hab dich lieb, Lotte.“",
      "Postcard to Oma Fenna: “Dear Oma, Opa Kees spent the night in Oaxaca, next to a farmer who sang terribly. We put out a glass of water for him. I think he liked it. And you keep riding your bike, please. Love you, Lotte.”",
      "Καρτ ποστάλ για την Όμα Φένα: «Αγαπημένη γιαγιά, ο Όπα Κέις πέρασε τη νύχτα στην Οαχάκα, δίπλα σε έναν αγρότη που τραγουδούσε απαίσια. Του βάλαμε ένα ποτήρι νερό. Νομίζω ότι του άρεσε. Κι εσύ συνέχισε το ποδήλατο, σε παρακαλώ. Σ' αγαπώ, Λότε.»")
  ]));

  // ── Station 3 · wetter ──────────────────────────────
  K.push(S(3, "wetter", "El bosque que bebe nubes",
    { de: "Dezember, Nebelwald von Monteverde: Der Führer Mauricio erklärt das Wetter — und Lotte plant ihren Tag nach den Wolken.",
      en: "December, the Monteverde cloud forest: the guide Mauricio explains the weather — and Lotte plans her day around the clouds.",
      el: "Δεκέμβριος, το δάσος των νεφών στο Μοντεβέρδε: ο οδηγός Μαουρίσιο εξηγεί τον καιρό — κι η Λότε σχεδιάζει τη μέρα της με βάση τα σύννεφα." },
  [
    Z("Diciembre. Lotte deja México con la maleta más pesada —dos kilos de chocolate de Oaxaca— y con una costumbre menos: ya casi no dice «vale». Casi.",
      "Dezember. Lotte verlässt Mexiko mit einem schwereren Koffer — zwei Kilo Schokolade aus Oaxaca — und einer Gewohnheit weniger: Sie sagt fast nicht mehr „vale“. Fast.",
      "December. Lotte leaves Mexico with a heavier suitcase — two kilos of chocolate from Oaxaca — and one habit fewer: she hardly ever says “vale” any more. Hardly.",
      "Δεκέμβριος. Η Λότε φεύγει από το Μεξικό με πιο βαριά βαλίτσα — δύο κιλά σοκολάτα από την Οαχάκα — και με μια συνήθεια λιγότερη: σχεδόν δεν λέει πια «vale». Σχεδόν."),
    Z("En Costa Rica, el bus sube durante tres horas por un camino de curvas, entre vacas, cafetales y niebla.",
      "In Costa Rica fährt der Bus drei Stunden lang eine kurvige Straße hinauf, zwischen Kühen, Kaffeeplantagen und Nebel.",
      "In Costa Rica, the bus climbs for three hours along a winding road, past cows, coffee plantations and mist.",
      "Στην Κόστα Ρίκα το λεωφορείο ανεβαίνει για τρεις ώρες έναν δρόμο γεμάτο στροφές, ανάμεσα σε αγελάδες, φυτείες καφέ και ομίχλη."),
    Z("Monteverde está a unos mil cuatrocientos metros, justo donde pasan las nubes. Aquí el bosque es tan verde que parece pintado.",
      "Monteverde liegt auf etwa vierzehnhundert Metern, genau dort, wo die Wolken vorbeiziehen. Hier ist der Wald so grün, dass er wie gemalt aussieht.",
      "Monteverde lies at about fourteen hundred metres, exactly where the clouds pass by. Here the forest is so green that it looks painted.",
      "Το Μοντεβέρδε βρίσκεται σε υψόμετρο περίπου χίλια τετρακόσια μέτρα, ακριβώς εκεί όπου περνούν τα σύννεφα. Εδώ το δάσος είναι τόσο πράσινο που μοιάζει ζωγραφισμένο."),
    Z("Lotte lo leyó antes de venir: en el bosque nuboso, la lluvia no es lo más importante. Las nubes pasan entre los árboles, el musgo las atrapa y el bosque se las bebe.",
      "Lotte hat es vor der Reise gelesen: Im Nebelwald ist der Regen nicht das Wichtigste. Die Wolken ziehen zwischen den Bäumen hindurch, das Moos fängt sie ein, und der Wald trinkt sie.",
      "Lotte read it before she came: in the cloud forest, rain isn't the most important thing. The clouds drift between the trees, the moss catches them and the forest drinks them.",
      "Η Λότε το διάβασε πριν έρθει: στο δάσος των νεφών η βροχή δεν είναι το πιο σημαντικό. Τα σύννεφα περνούν ανάμεσα στα δέντρα, τα βρύα τα πιάνουν και το δάσος τα πίνει."),
    Z("Un bosque que bebe nubes. Para un libro que se llama «Agua», no hay nada mejor.",
      "Ein Wald, der Wolken trinkt. Für ein Buch, das «Agua» heißt, gibt es nichts Besseres.",
      "A forest that drinks clouds. For a book called «Agua», there's nothing better.",
      "Ένα δάσος που πίνει σύννεφα. Για ένα βιβλίο που λέγεται «Agua», δεν υπάρχει τίποτα καλύτερο."),
    Z("A las siete de la mañana la espera el guía en la entrada de la reserva. Se llama Mauricio: unos cuarenta años, botas de hule, un telescopio al hombro y una sonrisa que no se le quita nunca.",
      "Um sieben Uhr morgens wartet der Führer am Eingang des Reservats auf sie. Er heißt Mauricio: um die vierzig, Gummistiefel, ein Fernrohr über der Schulter und ein Lächeln, das nie verschwindet.",
      "At seven in the morning the guide is waiting for her at the entrance to the reserve. His name is Mauricio: about forty, rubber boots, a telescope on his shoulder and a smile that never goes away.",
      "Στις εφτά το πρωί ο οδηγός την περιμένει στην είσοδο του καταφυγίου. Τον λένε Μαουρίσιο: γύρω στα σαράντα, λαστιχένιες μπότες, ένα τηλεσκόπιο στον ώμο κι ένα χαμόγελο που δεν φεύγει ποτέ."),
    Z("—¡Buenos días! ¡Pura vida! Usted es la fotógrafa, ¿verdad? La mañana está despejada, pero aquí el tiempo cambia muy rápido.",
      "Guten Morgen! Pura vida! Sie sind die Fotografin, oder? Der Morgen ist klar, aber hier ändert sich das Wetter sehr schnell.",
      "Good morning! Pura vida! You're the photographer, aren't you? The morning's clear, but the weather changes very fast here.",
      "Καλημέρα! Pura vida! Εσείς είστε η φωτογράφος, σωστά; Το πρωί είναι καθαρό, αλλά εδώ ο καιρός αλλάζει πολύ γρήγορα."),
    Z("«Pura vida», aprende Lotte ese mismo día, sirve para todo en Costa Rica: hola, adiós, gracias, todo bien, no se preocupe.",
      "„Pura vida“, lernt Lotte noch am selben Tag, passt in Costa Rica für alles: hallo, tschüss, danke, alles gut, keine Sorge.",
      "“Pura vida”, Lotte learns that very same day, works for everything in Costa Rica: hello, goodbye, thanks, all good, don't worry.",
      "Το «pura vida», μαθαίνει η Λότε την ίδια κιόλας μέρα, χρησιμεύει για όλα στην Κόστα Ρίκα: γεια, αντίο, ευχαριστώ, όλα καλά, μην ανησυχείτε."),
    Z("En el grupo hay dos personas más: una pareja de Canadá con ponchos de plástico nuevos, todavía con la etiqueta.",
      "In der Gruppe sind noch zwei weitere Leute: ein Paar aus Kanada mit neuen Plastikponchos, an denen noch das Etikett hängt.",
      "There are two more people in the group: a couple from Canada in new plastic ponchos, with the labels still on.",
      "Στην ομάδα υπάρχουν άλλοι δύο: ένα ζευγάρι από τον Καναδά με καινούργια πλαστικά πόντσο, ακόμα με την ετικέτα."),
    Z("—¿Qué tiempo hará por la tarde? Quiero sacar fotos de la catarata.",
      "Wie wird das Wetter am Nachmittag? Ich will den Wasserfall fotografieren.",
      "What will the weather be like this afternoon? I want to take photos of the waterfall.",
      "Τι καιρό θα κάνει το απόγευμα; Θέλω να φωτογραφίσω τον καταρράκτη."),
    Z("—Después de las dos llegará la neblina, y casi siempre llueve un rato. La catarata está al final del sendero, a dos horas de aquí.",
      "Nach zwei Uhr kommt der Nebel, und fast immer regnet es eine Weile. Der Wasserfall liegt am Ende des Pfads, zwei Stunden von hier.",
      "After two the mist will come in, and it almost always rains for a while. The waterfall is at the end of the trail, two hours from here.",
      "Μετά τις δύο θα έρθει η ομίχλη, και σχεδόν πάντα βρέχει για λίγο. Ο καταρράκτης είναι στο τέλος του μονοπατιού, δύο ώρες από εδώ."),
    Z("—¿Llueve fuerte?",
      "Regnet es stark?",
      "Does it rain hard?",
      "Βρέχει δυνατά;"),
    Z("—No. En diciembre, por la tarde, casi siempre cae pelo de gato.",
      "Nein. Im Dezember fällt am Nachmittag fast immer Katzenhaar.",
      "No. In December, in the afternoon, it's almost always cat's hair.",
      "Όχι. Τον Δεκέμβριο, το απόγευμα, σχεδόν πάντα πέφτει τρίχα γάτας."),
    Z("—¿Pelo de gato?",
      "Katzenhaar?",
      "Cat's hair?",
      "Τρίχα γάτας;"),
    Z("—Una llovizna finita, finita, como el pelo de un gato. No moja mucho, pero moja siempre.",
      "Ein ganz, ganz feiner Nieselregen, wie das Fell einer Katze. Er macht nicht sehr nass, aber er macht immer nass.",
      "A very, very fine drizzle, like a cat's fur. It doesn't make you very wet, but it always makes you wet.",
      "Ένα ψιλό, ψιλό ψιχάλισμα, σαν τρίχωμα γάτας. Δεν σε βρέχει πολύ, αλλά σε βρέχει πάντα."),
    Z("—Si llueve, guardaré la cámara en la mochila. ¿Mejor vamos ahora?",
      "Wenn es regnet, packe ich die Kamera in den Rucksack. Gehen wir lieber jetzt?",
      "If it rains, I'll put the camera in my backpack. Shall we go now instead?",
      "Αν βρέξει, θα βάλω τη μηχανή στο σακίδιο. Καλύτερα να πάμε τώρα;"),
    Z("—Tuanis, buena idea. Si salimos ya, llegaremos antes de la lluvia. Y si tenemos suerte, en el camino veremos el quetzal: con sol, los pájaros comen temprano.",
      "Tuanis, gute Idee. Wenn wir gleich losgehen, kommen wir vor dem Regen an. Und wenn wir Glück haben, sehen wir unterwegs den Quetzal: Bei Sonne fressen die Vögel früh.",
      "Tuanis, good idea. If we leave now, we'll get there before the rain. And if we're lucky, we'll see the quetzal on the way: when it's sunny, the birds feed early.",
      "Tuanis, καλή ιδέα. Αν ξεκινήσουμε τώρα, θα φτάσουμε πριν από τη βροχή. Κι αν είμαστε τυχεροί, θα δούμε στον δρόμο το κετσάλ: με ήλιο, τα πουλιά τρώνε νωρίς."),
    Z("Lotte no sabe qué es «tuanis», pero suena bien. Lo anota en el cuaderno, con un signo de interrogación.",
      "Lotte weiß nicht, was „tuanis“ ist, aber es klingt gut. Sie schreibt es ins Notizbuch, mit einem Fragezeichen.",
      "Lotte doesn't know what “tuanis” is, but it sounds good. She writes it in her notebook, with a question mark.",
      "Η Λότε δεν ξέρει τι είναι το «tuanis», αλλά ακούγεται ωραίο. Το σημειώνει στο σημειωματάριο, μ' ένα ερωτηματικό."),
    Z("—De acuerdo. Me pondré el impermeable por si acaso.",
      "Einverstanden. Ich ziehe für alle Fälle die Regenjacke an.",
      "All right. I'll put on my raincoat just in case.",
      "Εντάξει. Θα φορέσω το αδιάβροχο για καλό και για κακό."),
    Z("—Y si llueve fuerte, nos tomamos un café en la soda de doña Flor y esperamos. Aquí la lluvia nunca dura mucho.",
      "Und wenn es stark regnet, trinken wir einen Kaffee in Doña Flors Soda und warten. Hier dauert der Regen nie lange.",
      "And if it rains hard, we'll have a coffee at Doña Flor's soda and wait. The rain never lasts long here.",
      "Κι αν βρέξει δυνατά, πίνουμε έναν καφέ στη soda της κυρίας Φλορ και περιμένουμε. Εδώ η βροχή δεν κρατάει ποτέ πολύ."),
    Z("Una soda, le explica Mauricio, es un restaurante pequeño y barato, de comida casera. No tiene nada que ver con una bebida.",
      "Eine Soda, erklärt ihr Mauricio, ist ein kleines, günstiges Restaurant mit Hausmannskost. Mit einem Getränk hat das nichts zu tun.",
      "A soda, Mauricio explains, is a small, cheap restaurant serving home cooking. It has nothing to do with a drink.",
      "Η soda, της εξηγεί ο Μαουρίσιο, είναι ένα μικρό, φτηνό εστιατόριο με σπιτικό φαγητό. Δεν έχει καμία σχέση με αναψυκτικό."),
    Z("A las ocho y media, Mauricio se para de repente y pone el telescopio en el suelo.",
      "Um halb neun bleibt Mauricio plötzlich stehen und stellt das Fernrohr auf.",
      "At half past eight, Mauricio suddenly stops and sets up the telescope.",
      "Στις οκτώμισι ο Μαουρίσιο σταματάει ξαφνικά και στήνει το τηλεσκόπιο."),
    Z("—Ahí está. No se mueva.",
      "Da ist er. Nicht bewegen.",
      "There it is. Don't move.",
      "Εκεί είναι. Μην κουνηθείτε."),
    Z("En una rama, a veinte metros, hay un pájaro verde y rojo con una cola larguísima que brilla como el metal. El quetzal.",
      "Auf einem Ast, zwanzig Meter entfernt, sitzt ein grün-roter Vogel mit einem sehr langen Schwanz, der wie Metall glänzt. Der Quetzal.",
      "On a branch, twenty metres away, sits a green and red bird with a very long tail that shines like metal. The quetzal.",
      "Πάνω σε ένα κλαδί, είκοσι μέτρα μακριά, κάθεται ένα πράσινο και κόκκινο πουλί με μια πολύ μακριά ουρά που λάμπει σαν μέταλλο. Το κετσάλ."),
    Z("Lotte no saca la foto enseguida. Primero solo mira. Opa Kees siempre decía: «Primero mira. La foto viene después».",
      "Lotte macht das Foto nicht sofort. Zuerst schaut sie nur. Opa Kees sagte immer: „Erst schauen. Das Foto kommt danach.“",
      "Lotte doesn't take the picture straight away. At first she just looks. Opa Kees always used to say: “Look first. The picture comes afterwards.”",
      "Η Λότε δεν βγάζει αμέσως τη φωτογραφία. Πρώτα απλώς κοιτάζει. Ο Όπα Κέις έλεγε πάντα: «Πρώτα κοίτα. Η φωτογραφία έρχεται μετά»."),
    Z("A las once llegan a la catarata, un chorro blanco entre helechos gigantes. Lotte hace sus fotos con sol. Y a las dos en punto llega la neblina: no cae del cielo, entra caminando entre los árboles, despacito, como si buscara a alguien.",
      "Um elf erreichen sie den Wasserfall, einen weißen Strahl zwischen riesigen Farnen. Lotte macht ihre Fotos bei Sonne. Und um Punkt zwei kommt der Nebel: Er fällt nicht vom Himmel, er spaziert zwischen den Bäumen herein, ganz langsam, als ob er jemanden suchte.",
      "At eleven they reach the waterfall, a white stream between giant ferns. Lotte takes her pictures in the sun. And at two on the dot the mist arrives: it doesn't fall from the sky, it comes walking in between the trees, very slowly, as if it were looking for someone.",
      "Στις έντεκα φτάνουν στον καταρράκτη, ένα άσπρο νερό που πέφτει ανάμεσα σε γιγάντιες φτέρες. Η Λότε βγάζει τις φωτογραφίες της με ήλιο. Και στις δύο ακριβώς έρχεται η ομίχλη: δεν πέφτει από τον ουρανό, μπαίνει περπατώντας ανάμεσα στα δέντρα, σιγά σιγά, σαν να ψάχνει κάποιον."),
    Z("De regreso, en los puentes colgantes, el mundo desaparece. Arriba, nube. Abajo, nube. En medio, Lotte, un puente que se mueve y gotas en todas las hojas.",
      "Auf dem Rückweg, auf den Hängebrücken, verschwindet die Welt. Oben Wolke. Unten Wolke. Dazwischen Lotte, eine Brücke, die schwankt, und Tropfen an allen Blättern.",
      "On the way back, on the hanging bridges, the world disappears. Above, cloud. Below, cloud. In between, Lotte, a swaying bridge and drops on every leaf.",
      "Στην επιστροφή, στις κρεμαστές γέφυρες ο κόσμος εξαφανίζεται. Πάνω, σύννεφο. Κάτω, σύννεφο. Στη μέση, η Λότε, μια γέφυρα που κουνιέται και σταγόνες σε όλα τα φύλλα."),
    Z("—¿Ve? —dice Mauricio, y toca el musgo de una rama. Está mojado, pero no ha llovido—. El bosque está tomando agua. Por eso los ríos de aquí nunca se secan.",
      "„Sehen Sie?“, sagt Mauricio und berührt das Moos auf einem Ast. Es ist nass, aber es hat nicht geregnet. „Der Wald trinkt Wasser. Deshalb trocknen die Flüsse hier nie aus.“",
      "“See?” says Mauricio, touching the moss on a branch. It's wet, but it hasn't rained. “The forest is drinking water. That's why the rivers here never dry up.”",
      "«Βλέπετε;» λέει ο Μαουρίσιο κι αγγίζει τα βρύα σε ένα κλαδί. Είναι βρεγμένα, αλλά δεν έχει βρέξει. «Το δάσος πίνει νερό. Γι' αυτό τα ποτάμια εδώ δεν ξεραίνονται ποτέ.»"),
    Z("Clic. Una gota en el musgo, y dentro de la gota, todo el bosque al revés.",
      "Klick. Ein Tropfen auf dem Moos, und in dem Tropfen der ganze Wald, auf dem Kopf.",
      "Click. A drop on the moss, and inside the drop, the whole forest upside down.",
      "Κλικ. Μια σταγόνα στα βρύα, και μέσα στη σταγόνα όλο το δάσος ανάποδα."),
    Z("A las tres empieza el pelo de gato, exactamente como dijo Mauricio. Lotte guarda la Leica en la mochila y se pone la capucha del impermeable. La pareja de Canadá le ofrece un poncho para la mochila: compraron tres, por si acaso.",
      "Um drei fängt das Katzenhaar an, genau wie Mauricio gesagt hat. Lotte packt die Leica in den Rucksack und zieht die Kapuze ihrer Regenjacke auf. Das Paar aus Kanada bietet ihr einen Poncho für den Rucksack an: Sie haben drei gekauft, für alle Fälle.",
      "At three the cat's hair begins, exactly as Mauricio said. Lotte puts the Leica in her backpack and pulls up the hood of her raincoat. The Canadian couple offer her a poncho for the backpack: they bought three, just in case.",
      "Στις τρεις αρχίζει η τρίχα γάτας, ακριβώς όπως είπε ο Μαουρίσιο. Η Λότε βάζει τη Leica στο σακίδιο και φοράει την κουκούλα του αδιάβροχου. Το ζευγάρι από τον Καναδά της προσφέρει ένα πόντσο για το σακίδιο: αγόρασαν τρία, για καλό και για κακό."),
    Z("—¡Muchas gracias! Vale, perfecto.",
      "Vielen Dank! Okay, perfekt.",
      "Thank you so much! Okay, perfect.",
      "Ευχαριστώ πολύ! Εντάξει, τέλεια."),
    Z("—¿Vale? —Mauricio levanta las cejas—. Aquí no decimos «vale». Aquí decimos «tuanis», como esta mañana. Es como decir «genial».",
      "„Vale?“ Mauricio zieht die Augenbrauen hoch. „Hier sagen wir nicht ‚vale‘. Hier sagen wir ‚tuanis‘, wie heute Morgen. Das ist so, wie wenn man ‚super‘ sagt.“",
      "“Vale?” Mauricio raises his eyebrows. “Here we don't say ‘vale’. Here we say ‘tuanis’, like this morning. It's like saying ‘great’.”",
      "«Vale;» Ο Μαουρίσιο σηκώνει τα φρύδια. «Εδώ δεν λέμε “vale”. Εδώ λέμε “tuanis”, όπως το πρωί. Είναι σαν να λες “τέλειο”.»"),
    Z("—Tuanis —repite Lotte, y en el cuaderno tacha el signo de interrogación. El poncho, por supuesto, todavía tiene la etiqueta.",
      "„Tuanis“, wiederholt Lotte und streicht im Notizbuch das Fragezeichen durch. Am Poncho hängt natürlich noch das Etikett.",
      "“Tuanis,” Lotte repeats, and crosses out the question mark in her notebook. The poncho, of course, still has the label on.",
      "«Tuanis», επαναλαμβάνει η Λότε, και στο σημειωματάριο σβήνει το ερωτηματικό. Το πόντσο, φυσικά, έχει ακόμα την ετικέτα."),
    Z("—Mañana, si el viento sigue así, va a haber más niebla —dice Mauricio al final—. Si quiere fotos con niebla, venga a las siete. Si quiere sol… mejor no venga. El sol en Monteverde es como el quetzal: aparece, pero no cuando usted quiere.",
      "„Morgen, wenn der Wind so bleibt, wird es mehr Nebel geben“, sagt Mauricio am Ende. „Wenn Sie Fotos mit Nebel wollen, kommen Sie um sieben. Wenn Sie Sonne wollen … kommen Sie lieber nicht. Die Sonne in Monteverde ist wie der Quetzal: Sie kommt, aber nicht, wann Sie es wollen.“",
      "“Tomorrow, if the wind keeps up like this, there'll be more mist,” says Mauricio at the end. “If you want pictures with mist, come at seven. If you want sun… better not come. The sun in Monteverde is like the quetzal: it shows up, but not when you want it to.”",
      "«Αύριο, αν ο αέρας συνεχίσει έτσι, θα έχει περισσότερη ομίχλη», λέει στο τέλος ο Μαουρίσιο. «Αν θέλετε φωτογραφίες με ομίχλη, ελάτε στις εφτά. Αν θέλετε ήλιο… καλύτερα μην έρθετε. Ο ήλιος στο Μοντεβέρδε είναι σαν το κετσάλ: εμφανίζεται, αλλά όχι όταν το θέλετε εσείς.»"),
    Z("En la soda de doña Flor, con un café y un gallo pinto, vibra el celular. Bram: «Lotte, las fotos están muy grises. ¿No hay sol en Costa Rica?».",
      "In Doña Flors Soda, bei einem Kaffee und einem Gallo pinto, vibriert das Handy. Bram: „Lotte, die Fotos sind sehr grau. Gibt es in Costa Rica keine Sonne?“",
      "At Doña Flor's soda, over a coffee and a plate of gallo pinto, her phone buzzes. Bram: “Lotte, the pictures are very grey. Isn't there any sun in Costa Rica?”",
      "Στη soda της κυρίας Φλορ, με έναν καφέ κι ένα gallo pinto, δονείται το κινητό. Ο Μπραμ: «Λότε, οι φωτογραφίες είναι πολύ γκρίζες. Δεν έχει ήλιο η Κόστα Ρίκα;»"),
    Z("Lotte escribe: «No son grises, Bram. Son nubes. Y aquí las nubes son agua que todavía no ha decidido caer».",
      "Lotte schreibt: „Sie sind nicht grau, Bram. Das sind Wolken. Und hier sind die Wolken Wasser, das sich noch nicht entschieden hat zu fallen.“",
      "Lotte writes: “They're not grey, Bram. They're clouds. And here the clouds are water that hasn't decided to fall yet.”",
      "Η Λότε γράφει: «Δεν είναι γκρίζες, Μπραμ. Είναι σύννεφα. Κι εδώ τα σύννεφα είναι νερό που δεν έχει αποφασίσει ακόμα να πέσει.»"),
    Z("Palabra del lugar: pura vida.",
      "Wort des Ortes: pura vida.",
      "Word of the place: pura vida.",
      "Λέξη του τόπου: pura vida."),
    Z("Postal para Oma Fenna: «Querida Oma: hoy caminé dentro de una nube y vi un pájaro con cola de metal. Mañana, si llueve, voy a tomar café. Si no llueve, también. Pura vida —así se dice aquí—. Lotte».",
      "Postkarte an Oma Fenna: „Liebe Oma, heute bin ich in einer Wolke spazieren gegangen und habe einen Vogel mit einem Schwanz aus Metall gesehen. Wenn es morgen regnet, trinke ich Kaffee. Wenn es nicht regnet, auch. Pura vida — so sagt man hier. Lotte.“",
      "Postcard to Oma Fenna: “Dear Oma, today I walked inside a cloud and saw a bird with a metal tail. Tomorrow, if it rains, I'll have a coffee. If it doesn't rain, I'll have one too. Pura vida — that's what they say here. Lotte.”",
      "Καρτ ποστάλ για την Όμα Φένα: «Αγαπημένη γιαγιά, σήμερα περπάτησα μέσα σε ένα σύννεφο κι είδα ένα πουλί με μεταλλική ουρά. Αύριο, αν βρέχει, θα πιω καφέ. Αν δεν βρέχει, πάλι. Pura vida — έτσι λένε εδώ. Λότε.»")
  ]));

  // ── Station 4 · arzt ──────────────────────────────
  K.push(S(4, "arzt", "Le recomiendo que descanse",
    { de: "Januar, Quito auf 2850 Metern: Kopfweh, Schwindel, keine Nacht Schlaf. In der Apotheke weiß Doña Carmen, was hilft — und wie oft.",
      en: "January, Quito at 2,850 metres: headache, dizziness, a sleepless night. At the pharmacy, Doña Carmen knows what helps — and how often.",
      el: "Ιανουάριος, το Κίτο στα 2.850 μέτρα: πονοκέφαλος, ζαλάδα, μια νύχτα χωρίς ύπνο. Στο φαρμακείο η κυρία Κάρμεν ξέρει τι βοηθάει — και πόσο συχνά." },
  [
    Z("Enero. Quito: dos mil ochocientos cincuenta metros sobre el nivel del mar.",
      "Januar. Quito: zweitausendachthundertfünfzig Meter über dem Meeresspiegel.",
      "January. Quito: two thousand eight hundred and fifty metres above sea level.",
      "Ιανουάριος. Κίτο: δύο χιλιάδες οκτακόσια πενήντα μέτρα πάνω από την επιφάνεια της θάλασσας."),
    Z("La primera tarde camina por el centro histórico: iglesias blancas, balcones de madera y calles que suben, y suben, y suben.",
      "Am ersten Nachmittag spaziert sie durch die Altstadt: weiße Kirchen, Holzbalkone und Straßen, die hinaufgehen, und hinaufgehen, und hinaufgehen.",
      "On the first afternoon she walks around the old town: white churches, wooden balconies and streets that go up, and up, and up.",
      "Το πρώτο απόγευμα περπατάει στο ιστορικό κέντρο: λευκές εκκλησίες, ξύλινα μπαλκόνια και δρόμοι που ανεβαίνουν, κι ανεβαίνουν, κι ανεβαίνουν."),
    Z("El sol quema, pero el aire está frío. Un niño que vende chicles se mete las manos en los bolsillos y dice: —¡Achachay, qué frío!",
      "Die Sonne brennt, aber die Luft ist kalt. Ein Junge, der Kaugummis verkauft, steckt die Hände in die Taschen und sagt: „Achachay, ist das kalt!“",
      "The sun is burning, but the air is cold. A boy selling chewing gum puts his hands in his pockets and says: “Achachay, it's cold!”",
      "Ο ήλιος καίει, αλλά ο αέρας είναι κρύος. Ένα αγόρι που πουλάει τσίχλες βάζει τα χέρια στις τσέπες και λέει: «Achachay, τι κρύο!»"),
    Z("«Achachay», aprende Lotte, es lo que dicen los ecuatorianos cuando tienen frío. Es casi un temblor convertido en palabra.",
      "„Achachay“, lernt Lotte, sagen die Ecuadorianer, wenn ihnen kalt ist. Es ist fast ein Zittern, das zu einem Wort geworden ist.",
      "“Achachay”, Lotte learns, is what Ecuadorians say when they're cold. It's almost a shiver turned into a word.",
      "Το «achachay», μαθαίνει η Λότε, το λένε οι Εκουαδοριανοί όταν κρυώνουν. Είναι σχεδόν ένα ρίγος που έγινε λέξη."),
    Z("Esa noche no duerme. Le duele la cabeza, el corazón le late muy rápido, y en las escaleras del hostal tiene que parar dos veces.",
      "In dieser Nacht schläft sie nicht. Sie hat Kopfschmerzen, ihr Herz schlägt sehr schnell, und auf der Treppe im Hostel muss sie zweimal stehen bleiben.",
      "That night she doesn't sleep. Her head aches, her heart beats very fast, and on the hostel stairs she has to stop twice.",
      "Εκείνη τη νύχτα δεν κοιμάται. Πονάει το κεφάλι της, η καρδιά της χτυπάει πολύ γρήγορα, και στις σκάλες του χόστελ πρέπει να σταματήσει δύο φορές."),
    Z("Por la mañana no tiene hambre. Se mira en el espejo: el pelo rojo, la cara blanca como el papel.",
      "Am Morgen hat sie keinen Hunger. Sie schaut in den Spiegel: die roten Haare, das Gesicht weiß wie Papier.",
      "In the morning she isn't hungry. She looks in the mirror: red hair, a face as white as paper.",
      "Το πρωί δεν πεινάει. Κοιτάζεται στον καθρέφτη: τα κόκκινα μαλλιά, το πρόσωπο άσπρο σαν χαρτί."),
    Z("—Es el soroche —le dice el chico de la recepción—. El mal de altura. Vaya a la farmacia de la esquina, donde doña Carmen. Ella sabe más que un médico.",
      "„Das ist der Soroche“, sagt der junge Mann an der Rezeption. „Die Höhenkrankheit. Gehen Sie in die Apotheke an der Ecke, zu Doña Carmen. Die weiß mehr als ein Arzt.“",
      "“It's soroche,” the young man at reception tells her. “Altitude sickness. Go to the chemist's on the corner, to Doña Carmen. She knows more than a doctor.”",
      "«Είναι το soroche», της λέει το παιδί στη ρεσεψιόν. «Η νόσος του υψομέτρου. Πηγαίνετε στο φαρμακείο στη γωνία, στην κυρία Κάρμεν. Ξέρει περισσότερα από γιατρό.»"),
    Z("La farmacia es pequeña y huele a eucalipto. Detrás del mostrador hay una señora de pelo blanco, con los lentes colgados de una cadena y una bata blanca.",
      "Die Apotheke ist klein und riecht nach Eukalyptus. Hinter dem Tresen steht eine Frau mit weißen Haaren, die Brille an einer Kette und im weißen Kittel.",
      "The chemist's is small and smells of eucalyptus. Behind the counter is a woman with white hair, her glasses hanging on a chain, in a white coat.",
      "Το φαρμακείο είναι μικρό και μυρίζει ευκάλυπτο. Πίσω από τον πάγκο στέκεται μια κυρία με άσπρα μαλλιά, τα γυαλιά κρεμασμένα σε ένα κορδονάκι και λευκή ποδιά."),
    Z("—Buenos días, mijita. ¿En qué le puedo ayudar?",
      "Guten Morgen, Kindchen. Wie kann ich Ihnen helfen?",
      "Good morning, dear. How can I help you?",
      "Καλημέρα, κοριτσάκι μου. Πώς μπορώ να σας βοηθήσω;"),
    Z("—Buenos días. Llegué ayer a Quito y me duele mucho la cabeza.",
      "Guten Morgen. Ich bin gestern in Quito angekommen und habe starke Kopfschmerzen.",
      "Good morning. I arrived in Quito yesterday and I've got a bad headache.",
      "Καλημέρα. Έφτασα χθες στο Κίτο και με πονάει πολύ το κεφάλι."),
    Z("—Seguro es el soroche, por la altura. ¿Tiene mareos? ¿Duerme bien?",
      "Das ist sicher der Soroche, wegen der Höhe. Ist Ihnen schwindelig? Schlafen Sie gut?",
      "It's soroche for sure, because of the altitude. Do you feel dizzy? Are you sleeping well?",
      "Σίγουρα είναι το soroche, από το υψόμετρο. Ζαλίζεστε; Κοιμάστε καλά;"),
    Z("—Sí, un poco de mareo, y anoche dormí muy mal. ¿Qué me recomienda?",
      "Ja, mir ist etwas schwindelig, und letzte Nacht habe ich sehr schlecht geschlafen. Was empfehlen Sie mir?",
      "Yes, a little dizzy, and I slept very badly last night. What do you recommend?",
      "Ναι, ζαλίζομαι λίγο, και χθες το βράδυ κοιμήθηκα πολύ άσχημα. Τι μου συνιστάτε;"),
    Z("—Ah, claro. Usted viene de abajo, y aquí estamos a casi tres mil metros. Le recomiendo que tome mucha agua y que descanse hoy. Tome esta pastilla cada ocho horas.",
      "Ah, natürlich. Sie kommen von unten, und hier sind wir auf fast dreitausend Metern. Ich empfehle Ihnen, viel Wasser zu trinken und sich heute auszuruhen. Nehmen Sie diese Tablette alle acht Stunden.",
      "Ah, of course. You've come up from lower down, and here we're at almost three thousand metres. I recommend that you drink plenty of water and rest today. Take this tablet every eight hours.",
      "Α, βέβαια. Έρχεστε από χαμηλά, κι εδώ είμαστε σχεδόν στα τρεις χιλιάδες μέτρα. Σας συνιστώ να πίνετε πολύ νερό και να ξεκουραστείτε σήμερα. Να παίρνετε αυτό το χάπι κάθε οκτώ ώρες."),
    Z("—¿Cada ocho horas, con comida? ¿Y puedo tomar café?",
      "Alle acht Stunden, mit Essen? Und darf ich Kaffee trinken?",
      "Every eight hours, with food? And can I drink coffee?",
      "Κάθε οκτώ ώρες, με φαγητό; Και μπορώ να πιω καφέ;"),
    Z("—Sí, con comida. Mejor no tome café; pruebe una horchata lojana, es de hierbas.",
      "Ja, mit Essen. Trinken Sie lieber keinen Kaffee; probieren Sie eine Horchata lojana, die ist aus Kräutern.",
      "Yes, with food. Better not to drink coffee; try a horchata lojana, it's made from herbs.",
      "Ναι, με φαγητό. Καλύτερα να μην πίνετε καφέ· δοκιμάστε μια horchata lojana, είναι από βότανα."),
    Z("—¿Horchata? ¿Como la de México?",
      "Horchata? Wie die aus Mexiko?",
      "Horchata? Like the Mexican kind?",
      "Horchata; Σαν αυτή του Μεξικού;"),
    Z("—No, mijita, nada que ver. La de México es de arroz. Aquí la horchata es de Loja, en el sur del país: una infusión de muchas hierbas, de color rosado. Es suave y le va a hacer bien.",
      "Nein, Kindchen, ganz und gar nicht. Die aus Mexiko ist aus Reis. Hier kommt die Horchata aus Loja, im Süden des Landes: ein Aufguss aus vielen Kräutern, rosa in der Farbe. Er ist mild und wird Ihnen guttun.",
      "No, dear, nothing like it. The Mexican one is made from rice. Here horchata comes from Loja, in the south of the country: an infusion of lots of herbs, pink in colour. It's gentle and it'll do you good.",
      "Όχι, κοριτσάκι μου, καμία σχέση. Του Μεξικού είναι από ρύζι. Εδώ η horchata είναι από τη Λόχα, στον νότο της χώρας: ένα αφέψημα από πολλά βότανα, ροζ στο χρώμα. Είναι ήπιο και θα σας κάνει καλό."),
    Z("—Y escúcheme bien. Le recomiendo que tome por lo menos tres litros de agua al día, que descanse también mañana y que coma liviano: sopa, arroz, nada de fritura. Y que no tome alcohol.",
      "Und hören Sie mir gut zu. Ich empfehle Ihnen, mindestens drei Liter Wasser am Tag zu trinken, sich auch morgen auszuruhen und leicht zu essen: Suppe, Reis, nichts Frittiertes. Und keinen Alkohol zu trinken.",
      "And listen carefully. I recommend that you drink at least three litres of water a day, that you rest tomorrow as well and that you eat light: soup, rice, nothing fried. And that you don't drink alcohol.",
      "Και ακούστε με καλά. Σας συνιστώ να πίνετε τουλάχιστον τρία λίτρα νερό τη μέρα, να ξεκουραστείτε και αύριο και να τρώτε ελαφριά: σούπα, ρύζι, τίποτα τηγανητό. Και να μην πίνετε αλκοόλ."),
    Z("—¿Nada de alcohol?",
      "Gar keinen Alkohol?",
      "No alcohol at all?",
      "Καθόλου αλκοόλ;"),
    Z("—Ni una cerveza. Aquí arriba, una cerveza vale por tres.",
      "Nicht ein Bier. Hier oben zählt ein Bier wie drei.",
      "Not a single beer. Up here, one beer counts as three.",
      "Ούτε μία μπίρα. Εδώ πάνω, μία μπίρα μετράει για τρεις."),
    Z("—¿Y si mañana sigo igual?",
      "Und wenn es mir morgen immer noch so geht?",
      "And if I'm still the same tomorrow?",
      "Κι αν αύριο είμαι ακόμα έτσι;"),
    Z("—Si mañana sigue igual, o si le cuesta respirar, vaya al médico. Pero no se preocupe: en dos o tres días el cuerpo se acostumbra.",
      "Wenn es Ihnen morgen immer noch so geht oder wenn Ihnen das Atmen schwerfällt, gehen Sie zum Arzt. Aber keine Sorge: In zwei, drei Tagen gewöhnt sich der Körper daran.",
      "If you're still the same tomorrow, or if you find it hard to breathe, go to the doctor. But don't worry: in two or three days your body gets used to it.",
      "Αν αύριο είστε ακόμα έτσι, ή αν δυσκολεύεστε να αναπνεύσετε, πηγαίνετε στον γιατρό. Αλλά μην ανησυχείτε: σε δύο τρεις μέρες το σώμα συνηθίζει."),
    Z("—A ver si entendí bien: una pastilla cada ocho horas, con comida; mucha agua, descansar, nada de café y nada de alcohol.",
      "Mal sehen, ob ich es richtig verstanden habe: eine Tablette alle acht Stunden, mit Essen; viel Wasser, ausruhen, kein Kaffee und kein Alkohol.",
      "Let me see if I've got it right: one tablet every eight hours, with food; lots of water, rest, no coffee and no alcohol.",
      "Για να δω αν κατάλαβα καλά: ένα χάπι κάθε οκτώ ώρες, με φαγητό· πολύ νερό, ξεκούραση, καθόλου καφές και καθόλου αλκοόλ."),
    Z("—Perfecto. Y camine despacito, mijita. Despacito. Aquí arriba, el que corre llega último.",
      "Perfekt. Und gehen Sie ganz langsam, Kindchen. Ganz langsam. Hier oben kommt, wer rennt, als Letzter an.",
      "Perfect. And walk slowly, dear. Nice and slowly. Up here, whoever runs arrives last.",
      "Τέλεια. Και να περπατάτε σιγά σιγά, κοριτσάκι μου. Σιγά σιγά. Εδώ πάνω, όποιος τρέχει φτάνει τελευταίος."),
    Z("—¿Cuánto vale todo?",
      "Was kostet alles zusammen?",
      "How much is it all?",
      "Πόσο κάνουν όλα;"),
    Z("Lotte se escucha a sí misma. «¿Cuánto vale?»: así preguntan aquí, en Ecuador. Por primera vez en tres meses, la palabra «vale» está en su boca en el lugar correcto.",
      "Lotte hört sich selbst zu. „¿Cuánto vale?“: So fragt man hier in Ecuador. Zum ersten Mal seit drei Monaten ist das Wort „vale“ in ihrem Mund an der richtigen Stelle.",
      "Lotte hears herself. “¿Cuánto vale?”: that's how people ask here in Ecuador. For the first time in three months, the word “vale” is in her mouth in the right place.",
      "Η Λότε ακούει τον εαυτό της. «¿Cuánto vale?»: έτσι ρωτάνε εδώ, στον Ισημερινό. Για πρώτη φορά εδώ και τρεις μήνες, η λέξη «vale» βρίσκεται στο στόμα της στη σωστή θέση."),
    Z("—Son seis dólares con cincuenta.",
      "Das macht sechs Dollar fünfzig.",
      "That's six dollars fifty.",
      "Κάνει έξι δολάρια και πενήντα."),
    Z("Lotte paga con un billete de diez. En Ecuador, el dólar es la moneda de todos los días.",
      "Lotte zahlt mit einem Zehner. In Ecuador ist der Dollar die ganz normale Alltagswährung.",
      "Lotte pays with a ten-dollar note. In Ecuador, the dollar is the everyday currency.",
      "Η Λότε πληρώνει με ένα χαρτονόμισμα των δέκα. Στον Ισημερινό το δολάριο είναι το νόμισμα της καθημερινότητας."),
    Z("Durante dos días obedece a doña Carmen. Duerme, toma horchata rosada, toma agua, toma más agua. En el cuaderno escribe: «Día 1: agua. Día 2: agua. Día 3: ¿?».",
      "Zwei Tage lang gehorcht sie Doña Carmen. Sie schläft, trinkt rosa Horchata, trinkt Wasser, trinkt noch mehr Wasser. Ins Notizbuch schreibt sie: „Tag 1: Wasser. Tag 2: Wasser. Tag 3: ?“",
      "For two days she does as Doña Carmen says. She sleeps, drinks pink horchata, drinks water, drinks more water. In her notebook she writes: “Day 1: water. Day 2: water. Day 3: ?”",
      "Για δύο μέρες υπακούει στην κυρία Κάρμεν. Κοιμάται, πίνει ροζ horchata, πίνει νερό, πίνει κι άλλο νερό. Στο σημειωματάριο γράφει: «Μέρα 1: νερό. Μέρα 2: νερό. Μέρα 3: ;»"),
    Z("Al tercer día se despierta a las seis, sin dolor de cabeza. Abre la cortina.",
      "Am dritten Tag wacht sie um sechs auf, ohne Kopfschmerzen. Sie zieht den Vorhang auf.",
      "On the third day she wakes up at six, with no headache. She opens the curtain.",
      "Την τρίτη μέρα ξυπνάει στις έξι, χωρίς πονοκέφαλο. Ανοίγει την κουρτίνα."),
    Z("Allí, al sur, por encima de las nubes, hay una montaña blanca y perfecta, como dibujada por un niño: el Cotopaxi. Un volcán de casi seis mil metros con un glaciar en la cabeza.",
      "Dort, im Süden, über den Wolken, steht ein weißer, vollkommener Berg, wie von einem Kind gezeichnet: der Cotopaxi. Ein Vulkan von fast sechstausend Metern mit einem Gletscher auf dem Kopf.",
      "There, to the south, above the clouds, is a perfect white mountain, as if drawn by a child: Cotopaxi. A volcano of almost six thousand metres with a glacier on its head.",
      "Εκεί, στον νότο, πάνω από τα σύννεφα, υπάρχει ένα λευκό, τέλειο βουνό, σαν ζωγραφισμένο από παιδί: το Κοτοπάξι. Ένα ηφαίστειο σχεδόν έξι χιλιάδων μέτρων με έναν παγετώνα στο κεφάλι."),
    Z("—¡Qué chévere! —dice el chico de la recepción—. Hoy se ve el Cotopaxi. Eso no pasa todos los días.",
      "„Wie toll!“, sagt der junge Mann an der Rezeption. „Heute sieht man den Cotopaxi. Das passiert nicht jeden Tag.“",
      "“Brilliant!” says the young man at reception. “You can see Cotopaxi today. That doesn't happen every day.”",
      "«Τι ωραία!» λέει το παιδί στη ρεσεψιόν. «Σήμερα φαίνεται το Κοτοπάξι. Αυτό δεν συμβαίνει κάθε μέρα.»"),
    Z("Lotte mira el glaciar y piensa: es agua que espera. Agua de hace cientos de años, guardada en hielo. Cuando se derrite, baja por los ríos hasta los campos, hasta la ciudad, hasta el vaso que ella tiene en la mano.",
      "Lotte schaut auf den Gletscher und denkt: Das ist Wasser, das wartet. Wasser von vor Hunderten von Jahren, im Eis aufbewahrt. Wenn es schmilzt, fließt es über die Flüsse hinunter bis zu den Feldern, bis in die Stadt, bis in das Glas, das sie in der Hand hält.",
      "Lotte looks at the glacier and thinks: it's water that's waiting. Water from hundreds of years ago, kept in ice. When it melts, it flows down the rivers to the fields, to the city, to the glass she's holding in her hand.",
      "Η Λότε κοιτάζει τον παγετώνα και σκέφτεται: είναι νερό που περιμένει. Νερό εκατοντάδων χρόνων, φυλαγμένο στον πάγο. Όταν λιώνει, κατεβαίνει από τα ποτάμια ως τα χωράφια, ως την πόλη, ως το ποτήρι που κρατάει στο χέρι της."),
    Z("Sube a la terraza. Despacito, como dijo doña Carmen. Clic.",
      "Sie steigt auf die Dachterrasse. Ganz langsam, wie Doña Carmen gesagt hat. Klick.",
      "She goes up to the roof terrace. Slowly, as Doña Carmen said. Click.",
      "Ανεβαίνει στην ταράτσα. Σιγά σιγά, όπως είπε η κυρία Κάρμεν. Κλικ."),
    Z("Vibra el celular. Bram: «Lotte, ¿estás bien? Hace cuatro días que no mandas fotos».",
      "Das Handy vibriert. Bram: „Lotte, geht es dir gut? Du hast seit vier Tagen keine Fotos geschickt.“",
      "Her phone buzzes. Bram: “Lotte, are you all right? You haven't sent any pictures for four days.”",
      "Δονείται το κινητό. Ο Μπραμ: «Λότε, είσαι καλά; Έχεις τέσσερις μέρες να στείλεις φωτογραφίες.»"),
    Z("Lotte le manda el Cotopaxi y una frase: «Estaba tomando agua. Por recomendación de la farmacéutica».",
      "Lotte schickt ihm den Cotopaxi und einen Satz: „Ich habe Wasser getrunken. Auf Empfehlung der Apothekerin.“",
      "Lotte sends him Cotopaxi and one sentence: “I was drinking water. On the pharmacist's advice.”",
      "Η Λότε του στέλνει το Κοτοπάξι και μια φράση: «Έπινα νερό. Με σύσταση της φαρμακοποιού.»"),
    Z("Por la tarde pasa por la farmacia. Doña Carmen la mira por encima de los lentes.",
      "Am Nachmittag geht sie an der Apotheke vorbei. Doña Carmen schaut sie über die Brille hinweg an.",
      "In the afternoon she stops by the chemist's. Doña Carmen looks at her over her glasses.",
      "Το απόγευμα περνάει από το φαρμακείο. Η κυρία Κάρμεν την κοιτάζει πάνω από τα γυαλιά."),
    Z("—¿Ya está mejor, mijita?",
      "Geht es Ihnen schon besser, Kindchen?",
      "Feeling better now, dear?",
      "Είστε καλύτερα τώρα, κοριτσάκι μου;"),
    Z("—Mucho mejor. Gracias, doña Carmen. Usted sabe más que un médico.",
      "Viel besser. Danke, Doña Carmen. Sie wissen mehr als ein Arzt.",
      "Much better. Thank you, Doña Carmen. You know more than a doctor.",
      "Πολύ καλύτερα. Ευχαριστώ, κυρία Κάρμεν. Ξέρετε περισσότερα από γιατρό."),
    Z("Palabra del lugar: achachay.",
      "Wort des Ortes: achachay.",
      "Word of the place: achachay.",
      "Λέξη του τόπου: achachay."),
    Z("Postal para Oma Fenna: «Querida Oma: estoy a dos mil ochocientos cincuenta metros. Me dolía la cabeza, pero una señora muy sabia me curó con agua rosada. Desde mi ventana veo un glaciar. Camino despacito, como tú en la bicicleta. Lotte».",
      "Postkarte an Oma Fenna: „Liebe Oma, ich bin auf zweitausendachthundertfünfzig Metern. Ich hatte Kopfweh, aber eine sehr weise Frau hat mich mit rosa Wasser geheilt. Von meinem Fenster aus sehe ich einen Gletscher. Ich gehe ganz langsam, so wie du Fahrrad fährst. Lotte.“",
      "Postcard to Oma Fenna: “Dear Oma, I'm at two thousand eight hundred and fifty metres. I had a headache, but a very wise lady cured me with pink water. From my window I can see a glacier. I walk slowly, like you on your bike. Lotte.”",
      "Καρτ ποστάλ για την Όμα Φένα: «Αγαπημένη γιαγιά, βρίσκομαι στα δύο χιλιάδες οκτακόσια πενήντα μέτρα. Πονούσε το κεφάλι μου, αλλά μια πολύ σοφή κυρία με γιάτρεψε με ροζ νερό. Από το παράθυρό μου βλέπω έναν παγετώνα. Περπατάω σιγά σιγά, όπως εσύ με το ποδήλατο. Λότε.»")
  ]));

  // ── Station 5 · einkaufen ──────────────────────────────
  K.push(S(5, "einkaufen", "¿Me lo deja en sesenta?",
    { de: "Otavalo, der größte Markt der Anden: ein blauer Poncho, eine Großmutter, die besser feilscht als Lotte — und ein Wort, das Lotte hier plötzlich überall hört.",
      en: "Otavalo, the biggest market in the Andes: a blue poncho, a grandmother who bargains better than Lotte — and a word Lotte suddenly hears everywhere.",
      el: "Οταβάλο, η μεγαλύτερη αγορά των Άνδεων: ένα μπλε πόντσο, μια γιαγιά που παζαρεύει καλύτερα από τη Λότε — και μια λέξη που η Λότε ξαφνικά ακούει παντού." },
  [
    Z("Otavalo, un sábado de enero. A las siete de la mañana, la Plaza de los Ponchos ya estaba llena de colores.",
      "Otavalo, ein Samstag im Januar. Um sieben Uhr morgens war die Plaza de los Ponchos schon voller Farben.",
      "Otavalo, a Saturday in January. At seven in the morning, the Plaza de los Ponchos was already full of colour.",
      "Οταβάλο, ένα Σάββατο του Ιανουαρίου. Στις επτά το πρωί, η Πλάσα ντε λος Πόντσος ήταν ήδη γεμάτη χρώματα."),
    Z("Ponchos, cobijas, hamacas, sombreros. Detrás de los puestos se veía el volcán Imbabura, con una nube en la cabeza como un gorro.",
      "Ponchos, Wolldecken, Hängematten, Hüte. Hinter den Ständen sah man den Vulkan Imbabura, mit einer Wolke auf dem Kopf wie eine Mütze.",
      "Ponchos, blankets, hammocks, hats. Behind the stalls you could see the Imbabura volcano, with a cloud on its head like a woolly hat.",
      "Πόντσο, κουβέρτες, αιώρες, καπέλα. Πίσω από τους πάγκους φαινόταν το ηφαίστειο Ιμπαμπούρα, με ένα σύννεφο στο κεφάλι σαν σκουφί."),
    Z("Lotte había venido por el lago San Pablo. Pero primero, el mercado: en Quito hacía frío por la noche.",
      "Lotte war wegen des Sees San Pablo gekommen. Aber zuerst der Markt: In Quito war es nachts kalt.",
      "Lotte had come for Lake San Pablo. But first, the market: in Quito it was cold at night.",
      "Η Λότε είχε έρθει για τη λίμνη Σαν Πάμπλο. Πρώτα όμως η αγορά: στο Κίτο έκανε κρύο τη νύχτα."),
    Z("Su celular vibró. Un mensaje de voz de Bram, desde Ámsterdam:",
      "Ihr Handy vibrierte. Eine Sprachnachricht von Bram, aus Amsterdam:",
      "Her mobile buzzed. A voice message from Bram, in Amsterdam:",
      "Το κινητό της δόνησε. Ένα φωνητικό μήνυμα από τον Μπραμ, από το Άμστερνταμ:"),
    Z("—Lotte, aquí llueve. Llueve agua holandesa, gris y aburrida. ¿Dónde está tu agua ecuatoriana? Mándame algo azul, por favor. Azul.",
      "Lotte, hier regnet es. Es regnet holländisches Wasser, grau und langweilig. Wo ist dein ecuadorianisches Wasser? Schick mir bitte etwas Blaues. Blau.",
      "Lotte, it's raining here. It's raining Dutch water, grey and boring. Where's your Ecuadorian water? Send me something blue, please. Blue.",
      "Λότε, εδώ βρέχει. Βρέχει ολλανδικό νερό, γκρίζο και βαρετό. Πού είναι το νερό σου από τον Ισημερινό; Στείλε μου κάτι μπλε, σε παρακαλώ. Μπλε."),
    Z("«Azul», pensó Lotte. «Bram siempre quiere azul. Primero necesito un poncho.»",
      "„Blau“, dachte Lotte. „Bram will immer Blau. Zuerst brauche ich einen Poncho.“",
      "‘Blue,’ thought Lotte. ‘Bram always wants blue. First I need a poncho.’",
      "«Μπλε», σκέφτηκε η Λότε. «Ο Μπραμ θέλει πάντα μπλε. Πρώτα χρειάζομαι ένα πόντσο.»"),
    Z("En un puesto de la esquina, una señora tejía sin mirarse las manos. Llevaba una blusa blanca bordada, una falda larga oscura y muchos collares dorados. Se llamaba doña Tránsito.",
      "An einem Stand an der Ecke webte eine Frau, ohne auf ihre Hände zu schauen. Sie trug eine bestickte weiße Bluse, einen langen dunklen Rock und viele goldene Ketten. Sie hieß Doña Tránsito.",
      "At a stall on the corner, a woman was weaving without looking at her hands. She wore an embroidered white blouse, a long dark skirt and lots of golden necklaces. Her name was Doña Tránsito.",
      "Σε έναν πάγκο στη γωνία, μια κυρία ύφαινε χωρίς να κοιτάζει τα χέρια της. Φορούσε μια κεντημένη λευκή μπλούζα, μια μακριά σκούρα φούστα και πολλά χρυσά κολιέ. Τη λέγανε κυρία Τράνσιτο."),
    Z("A su lado, su nieta Sisa, de unos diez años, hacía la tarea en un cuaderno de matemáticas.",
      "Neben ihr machte ihre Enkelin Sisa, etwa zehn Jahre alt, Hausaufgaben in einem Matheheft.",
      "Next to her, her granddaughter Sisa, about ten years old, was doing her homework in a maths exercise book.",
      "Δίπλα της, η εγγονή της η Σίσα, περίπου δέκα χρονών, έκανε τα μαθήματά της σε ένα τετράδιο μαθηματικών."),
    Z("—Buenos días, señora. ¿Me permite mirar?",
      "Guten Morgen. Darf ich mich umschauen?",
      "Good morning. May I have a look?",
      "Καλημέρα σας, κυρία. Μου επιτρέπετε να κοιτάξω;"),
    Z("—¡A la orden! Estos ponchos los tejemos en mi familia, con lana de oveja. Mire nomás, mijita, sin compromiso.",
      "Bitte schön! Diese Ponchos weben wir in meiner Familie, aus Schafwolle. Schauen Sie ruhig, Kindchen, ganz unverbindlich.",
      "At your service! We weave these ponchos in my family, from sheep's wool. Go ahead and look, dear, no obligation.",
      "Ορίστε! Αυτά τα πόντσο τα υφαίνουμε στην οικογένειά μου, με πρόβειο μαλλί. Κοιτάξτε άνετα, κορίτσι μου, χωρίς καμία υποχρέωση."),
    Z("Lotte tocó un poncho rojo y naranja, fino y suave. Arriba, colgado al lado de los sombreros, había otro: azul oscuro, grueso, con dibujos blancos.",
      "Lotte berührte einen rot-orangen Poncho, dünn und weich. Oben, neben den Hüten, hing ein anderer: dunkelblau, dick, mit weißen Mustern.",
      "Lotte touched a red and orange poncho, thin and soft. Up above, hanging next to the hats, was another one: dark blue, thick, with white patterns.",
      "Η Λότε άγγιξε ένα κόκκινο και πορτοκαλί πόντσο, λεπτό και μαλακό. Πάνω, κρεμασμένο δίπλα στα καπέλα, υπήρχε ένα άλλο: σκούρο μπλε, χοντρό, με λευκά σχέδια."),
    Z("—¿Cuánto vale este, el rojo?",
      "Was kostet der hier, der rote?",
      "How much is this one, the red one?",
      "Πόσο κάνει αυτό, το κόκκινο;"),
    Z("—¿El rojo? Cincuenta dólares.",
      "Der rote? Fünfzig Dollar.",
      "The red one? Fifty dollars.",
      "Το κόκκινο; Πενήντα δολάρια."),
    Z("En Ecuador se paga en dólares. Lotte todavía hacía cuentas en euros, y casi siempre se equivocaba.",
      "In Ecuador zahlt man in Dollar. Lotte rechnete immer noch in Euro um und verrechnete sich fast immer.",
      "In Ecuador you pay in dollars. Lotte was still converting into euros, and she almost always got it wrong.",
      "Στον Ισημερινό πληρώνεις σε δολάρια. Η Λότε ακόμα έκανε λογαριασμούς σε ευρώ, και σχεδόν πάντα έκανε λάθος."),
    Z("—Son preciosos. ¿Qué significan los dibujos de aquel poncho azul?",
      "Sie sind wunderschön. Was bedeuten die Muster auf dem blauen Poncho dort drüben?",
      "They're beautiful. What do the patterns on that blue poncho over there mean?",
      "Είναι πανέμορφα. Τι σημαίνουν τα σχέδια σε εκείνο το μπλε πόντσο;"),
    Z("—Son el lago San Pablo y las montañas. Ese cuesta ochenta dólares.",
      "Das sind der San-Pablo-See und die Berge. Der kostet achtzig Dollar.",
      "They're Lake San Pablo and the mountains. That one costs eighty dollars.",
      "Είναι η λίμνη Σαν Πάμπλο και τα βουνά. Αυτό κάνει ογδόντα δολάρια."),
    Z("—Las líneas en zigzag son el agua —explicó Sisa, con el lápiz en la mano—: el lago y los ríos que bajan del Taita Imbabura. Los triángulos son las montañas, y lo del centro es el sol. Sin sol y sin agua no crece nada.",
      "„Die Zickzacklinien sind das Wasser“, erklärte Sisa, den Bleistift in der Hand, „der See und die Flüsse, die vom Taita Imbabura herunterkommen. Die Dreiecke sind die Berge, und das in der Mitte ist die Sonne. Ohne Sonne und ohne Wasser wächst nichts.“",
      "‘The zigzag lines are the water,’ Sisa explained, pencil in hand, ‘the lake and the rivers that come down from Taita Imbabura. The triangles are the mountains, and the thing in the middle is the sun. Without sun and without water, nothing grows.’",
      "«Οι ζιγκ-ζαγκ γραμμές είναι το νερό», εξήγησε η Σίσα με το μολύβι στο χέρι, «η λίμνη και τα ποτάμια που κατεβαίνουν από τον Τάιτα Ιμπαμπούρα. Τα τρίγωνα είναι τα βουνά, κι αυτό στη μέση είναι ο ήλιος. Χωρίς ήλιο και χωρίς νερό δεν φυτρώνει τίποτα.»"),
    Z("—Lo tejió mi hermana en un telar de pedal —añadió doña Tránsito—. Es el mejor que tengo.",
      "„Meine Schwester hat ihn auf einem Trittwebstuhl gewebt“, fügte Doña Tránsito hinzu. „Das ist der beste, den ich habe.“",
      "‘My sister wove it on a foot loom,’ Doña Tránsito added. ‘It's the best one I've got.’",
      "«Το ύφανε η αδερφή μου σε αργαλειό με πεντάλ», πρόσθεσε η κυρία Τράνσιτο. «Είναι το καλύτερο που έχω.»"),
    Z("Lotte miró aquel poncho con amor y su billetera con tristeza.",
      "Lotte sah den Poncho dort oben voller Liebe an und ihren Geldbeutel voller Trauer.",
      "Lotte looked at that poncho with love and at her purse with sadness.",
      "Η Λότε κοίταξε εκείνο το πόντσο με αγάπη και το πορτοφόλι της με θλίψη."),
    Z("Agua, otra vez. El agua la seguía por todo el continente. O ella seguía al agua; ya no estaba segura.",
      "Wasser, schon wieder. Das Wasser folgte ihr über den ganzen Kontinent. Oder sie folgte dem Wasser; sie war sich nicht mehr sicher.",
      "Water, again. The water was following her across the whole continent. Or she was following the water; she wasn't sure any more.",
      "Νερό, πάλι. Το νερό την ακολουθούσε σε όλη την ήπειρο. Ή εκείνη ακολουθούσε το νερό· δεν ήταν πια σίγουρη."),
    Z("—Mi abuela dice que este poncho es más bonito que todos los de Europa —dijo Sisa, sin levantar la vista.",
      "„Meine Oma sagt, dieser Poncho ist schöner als alle in Europa“, sagte Sisa, ohne aufzusehen.",
      "‘My grandma says this poncho is prettier than all the ones in Europe,’ said Sisa, without looking up.",
      "«Η γιαγιά μου λέει ότι αυτό το πόντσο είναι πιο ωραίο από όλα της Ευρώπης», είπε η Σίσα, χωρίς να σηκώσει το βλέμμα."),
    Z("—¿Tú conoces Europa?",
      "Kennst du denn Europa?",
      "Have you been to Europe?",
      "Εσύ ξέρεις την Ευρώπη;"),
    Z("—No. Pero seguro.",
      "Nein. Aber ganz bestimmt.",
      "No. But I'm sure.",
      "Όχι. Αλλά σίγουρα."),
    Z("Lotte sabía que en el mercado se puede regatear. Pero su guía de viaje no explicaba cómo regatear con una abuela que te llama «mijita».",
      "Lotte wusste, dass man auf dem Markt feilschen darf. Aber ihr Reiseführer erklärte nicht, wie man mit einer Großmutter feilscht, die einen „Kindchen“ nennt.",
      "Lotte knew that you can bargain at the market. But her guidebook didn't explain how to bargain with a grandmother who calls you ‘dear’.",
      "Η Λότε ήξερε ότι στην αγορά μπορείς να παζαρέψεις. Αλλά ο ταξιδιωτικός οδηγός της δεν εξηγούσε πώς παζαρεύεις με μια γιαγιά που σε λέει «κορίτσι μου»."),
    Z("—Señora, el azul me encanta. Es más caro que el rojo, ¿no? ¿Me lo deja en sesenta?",
      "Señora, der blaue gefällt mir sehr. Er ist teurer als der rote, oder? Lassen Sie ihn mir für sechzig?",
      "Señora, I love the blue one. It's more expensive than the red one, isn't it? Will you let me have it for sixty?",
      "Κυρία μου, το μπλε μου αρέσει πολύ. Είναι πιο ακριβό από το κόκκινο, έτσι; Μου το αφήνετε στα εξήντα;"),
    Z("Doña Tránsito se puso la mano en el corazón, como en una telenovela.",
      "Doña Tránsito legte sich die Hand aufs Herz, wie in einer Telenovela.",
      "Doña Tránsito put her hand on her heart, like in a soap opera.",
      "Η κυρία Τράνσιτο έβαλε το χέρι στην καρδιά, σαν σε τηλενουβέλα."),
    Z("—¿Sesenta? Ay, mijita. ¿Y la lana? ¿Y las ovejas? ¿Y las tres semanas de trabajo de mi hermana? Sesenta es muy poco. Se lo dejo en setenta, es el mejor que tengo.",
      "Sechzig? Ach, Kindchen. Und die Wolle? Und die Schafe? Und die drei Wochen Arbeit meiner Schwester? Sechzig ist viel zu wenig. Ich lasse ihn Ihnen für siebzig, er ist der beste, den ich habe.",
      "Sixty? Oh, dear. And the wool? And the sheep? And my sister's three weeks of work? Sixty is far too little. I'll let you have it for seventy, it's the best one I've got.",
      "Εξήντα; Αχ, κορίτσι μου. Και το μαλλί; Και τα πρόβατα; Και οι τρεις βδομάδες δουλειά της αδερφής μου; Το εξήντα είναι πολύ λίγο. Σας το αφήνω εβδομήντα, είναι το καλύτερο που έχω."),
    Z("—¿Y en sesenta y cinco?",
      "Und für fünfundsechzig?",
      "And for sixty-five?",
      "Κι εξήντα πέντε;"),
    Z("—El rojo no es tan grueso como el azul. No son iguales. Setenta.",
      "Der rote ist nicht so dick wie der blaue. Die sind nicht gleich. Siebzig.",
      "The red one isn't as thick as the blue one. They're not the same. Seventy.",
      "Το κόκκινο δεν είναι τόσο χοντρό όσο το μπλε. Δεν είναι ίδια. Εβδομήντα."),
    Z("—Está bien, me lo llevo. ¿Puedo pagar con un billete de cien?",
      "In Ordnung, ich nehme ihn. Kann ich mit einem Hundertdollarschein zahlen?",
      "All right, I'll take it. Can I pay with a hundred-dollar note?",
      "Εντάξει, το παίρνω. Μπορώ να πληρώσω με ένα χαρτονόμισμα των εκατό;"),
    Z("—Claro, mijita. ¿Y no quiere también esta bufanda pequeña, para alguien de su familia? Así no le doy tanto vuelto.",
      "Natürlich, Kindchen. Und möchten Sie nicht auch diesen kleinen Schal, für jemanden aus Ihrer Familie? Dann muss ich Ihnen nicht so viel herausgeben.",
      "Of course, dear. And wouldn't you like this little scarf as well, for someone in your family? Then I won't have to give you so much change.",
      "Βεβαίως, κορίτσι μου. Και δεν θέλετε κι αυτό το μικρό κασκόλ, για κάποιον από την οικογένειά σας; Έτσι δεν θα σας δώσω τόσα ρέστα."),
    Z("Doña Tránsito miró a Sisa. Sisa hizo la cuenta en su cuaderno de matemáticas, muy seria.",
      "Doña Tránsito sah Sisa an. Sisa rechnete in ihrem Matheheft nach, sehr ernst.",
      "Doña Tránsito looked at Sisa. Sisa did the sum in her maths book, very seriously.",
      "Η κυρία Τράνσιτο κοίταξε τη Σίσα. Η Σίσα έκανε τον λογαριασμό στο τετράδιο των μαθηματικών, πολύ σοβαρή."),
    Z("—Setenta el poncho y veinticinco la bufanda: noventa y cinco, abuelita.",
      "Siebzig der Poncho und fünfundzwanzig der Schal: fünfundneunzig, Omi.",
      "Seventy for the poncho and twenty-five for the scarf: ninety-five, Grandma.",
      "Εβδομήντα το πόντσο κι είκοσι πέντε το κασκόλ: ενενήντα πέντε, γιαγιάκα."),
    Z("—Ya, ya. Noventa las dos cosas. Pero solo porque usted pregunta por los dibujos. Los turistas no preguntan nada; solo dicen «¿cuánto vale?, ¿cuánto vale?».",
      "Schon gut, schon gut. Neunzig für beides. Aber nur, weil Sie nach den Mustern fragen. Die Touristen fragen gar nichts; sie sagen nur „¿cuánto vale?, ¿cuánto vale?“.",
      "All right, all right. Ninety for both. But only because you ask about the patterns. Tourists don't ask anything; they just say ‘¿cuánto vale?, ¿cuánto vale?’",
      "Καλά, καλά. Ενενήντα και τα δύο. Αλλά μόνο επειδή ρωτάτε για τα σχέδια. Οι τουρίστες δεν ρωτάνε τίποτα· λένε μόνο «¿cuánto vale?, ¿cuánto vale?»."),
    Z("Lotte casi se rió. En la farmacia de Quito ya lo había notado, pero aquí era una fiesta: durante tres meses, todo el mundo le había dicho «Aquí no decimos vale», y ahora, en Otavalo, todo el mundo decía vale. Pero era otro vale: el vale del precio.",
      "Lotte musste fast lachen. In der Apotheke in Quito hatte sie es schon bemerkt, aber hier war es ein richtiges Fest: Drei Monate lang hatten ihr alle gesagt: „Hier sagen wir nicht vale“, und jetzt, in Otavalo, sagten alle vale. Aber es war ein anderes vale: das vale des Preises.",
      "Lotte almost laughed. She had already noticed it at the pharmacy in Quito, but here it was a real party: for three months everyone had told her, ‘We don't say vale here’, and now, in Otavalo, everyone was saying vale. But it was a different vale: the vale of the price.",
      "Η Λότε παραλίγο να γελάσει. Το είχε ήδη προσέξει στο φαρμακείο του Κίτο, αλλά εδώ ήταν σκέτη γιορτή: τρεις μήνες όλοι της έλεγαν «Εδώ δεν λέμε vale», και τώρα, στο Οταβάλο, όλοι έλεγαν vale. Αλλά ήταν άλλο vale: το vale της τιμής."),
    Z("—Entonces... ¿vale? —preguntó Lotte, por costumbre.",
      "Also ... vale?, fragte Lotte, aus Gewohnheit.",
      "‘So... vale?’ Lotte asked, out of habit.",
      "«Λοιπόν... vale;» ρώτησε η Λότε, από συνήθεια."),
    Z("—¿Vale qué, mijita? Noventa dólares vale.",
      "Was soll was kosten, Kindchen? Neunzig Dollar kostet das.",
      "Worth what, dear? It's worth ninety dollars.",
      "Τι κάνει, κορίτσι μου; Ενενήντα δολάρια κάνει."),
    Z("—Quiero decir: de acuerdo. Trato hecho.",
      "Ich meine: einverstanden. Abgemacht.",
      "I mean: agreed. It’s a deal.",
      "Θέλω να πω: σύμφωνοι. Κλείσαμε."),
    Z("—¡Ah, trato hecho!",
      "Ach so, abgemacht!",
      "Ah, it’s a deal!",
      "Α, κλείσαμε!"),
    Z("Lotte pagó con el billete de cien, y Sisa le dio el vuelto con mucha ceremonia. Doña Tránsito le regaló, además, una pulsera de hilo azul.",
      "Lotte zahlte mit dem Hundertdollarschein, und Sisa gab ihr feierlich das Wechselgeld. Doña Tránsito schenkte ihr außerdem ein Armband aus blauem Faden.",
      "Lotte paid with the hundred-dollar note, and Sisa handed her the change with great ceremony. Doña Tránsito also gave her a bracelet of blue thread.",
      "Η Λότε πλήρωσε με το χαρτονόμισμα των εκατό, και η Σίσα της έδωσε τα ρέστα με μεγάλη επισημότητα. Η κυρία Τράνσιτο της χάρισε επιπλέον ένα βραχιόλι από μπλε κλωστή."),
    Z("—Para el viaje. Para que el agua la cuide.",
      "Für die Reise. Damit das Wasser auf Sie aufpasst.",
      "For the journey. So the water looks after you.",
      "Για το ταξίδι. Για να σας προσέχει το νερό."),
    Z("Por la tarde, Lotte tomó un bus hasta el lago San Pablo. El agua estaba quieta y era de un azul profundo, más oscuro que el cielo, casi tan oscuro como su poncho nuevo. El Imbabura se miraba en ella como en un espejo.",
      "Am Nachmittag nahm Lotte einen Bus zum See San Pablo. Das Wasser lag still und war tiefblau, dunkler als der Himmel, fast so dunkel wie ihr neuer Poncho. Der Imbabura spiegelte sich darin wie in einem Spiegel.",
      "In the afternoon, Lotte took a bus to Lake San Pablo. The water was still and a deep blue, darker than the sky, almost as dark as her new poncho. Imbabura looked at itself in it as if in a mirror.",
      "Το απόγευμα, η Λότε πήρε ένα λεωφορείο ως τη λίμνη Σαν Πάμπλο. Το νερό ήταν ακίνητο και βαθύ μπλε, πιο σκούρο από τον ουρανό, σχεδόν τόσο σκούρο όσο το καινούργιο της πόντσο. Ο Ιμπαμπούρα καθρεφτιζόταν μέσα του σαν σε καθρέφτη."),
    Z("Hizo doce fotos. La última era la mejor: una pequeña barca de totora en el centro del lago y, alrededor, solo azul.",
      "Sie machte zwölf Fotos. Das letzte war das beste: ein kleines Boot aus Schilf mitten auf dem See und ringsherum nur Blau.",
      "She took twelve photos. The last one was the best: a small reed boat in the middle of the lake and, all around it, nothing but blue.",
      "Έβγαλε δώδεκα φωτογραφίες. Η τελευταία ήταν η καλύτερη: μια μικρή βάρκα από καλάμια στη μέση της λίμνης και, γύρω της, μόνο μπλε."),
    Z("Se la mandó a Bram. La respuesta llegó cuatro segundos después: «AZUL. Por fin. Te quiero. Profesionalmente».",
      "Sie schickte es Bram. Die Antwort kam vier Sekunden später: „BLAU. Endlich. Ich liebe dich. Beruflich.“",
      "She sent it to Bram. The reply came four seconds later: ‘BLUE. At last. I love you. Professionally.’",
      "Την έστειλε στον Μπραμ. Η απάντηση ήρθε τέσσερα δευτερόλεπτα αργότερα: «ΜΠΛΕ. Επιτέλους. Σ' αγαπώ. Επαγγελματικά»."),
    Z("Esa noche, Lotte escribió en su cuaderno: «Palabra del lugar: ¿cuánto vale? Aquí vale es un precio, no una respuesta. Yo ya no digo vale. Bueno, casi nunca».",
      "An diesem Abend schrieb Lotte in ihr Notizbuch: „Wort des Ortes: ¿cuánto vale? Hier ist vale ein Preis, keine Antwort. Ich sage nicht mehr vale. Na ja, fast nie.“",
      "That night, Lotte wrote in her notebook: ‘Word of the place: ¿cuánto vale? Here vale is a price, not an answer. I don’t say vale any more. Well, hardly ever.’",
      "Εκείνο το βράδυ η Λότε έγραψε στο σημειωματάριό της: «Λέξη του τόπου: ¿cuánto vale? Εδώ το vale είναι τιμή, όχι απάντηση. Εγώ δεν λέω πια vale. Εντάξει, σχεδόν ποτέ»."),
    Z("Y en una postal: «Querida Oma: hoy regateé con una abuela ecuatoriana. Ganó ella, claro. Te mando una bufanda con el lago dibujado. Pagué un poco de más, pero valía la pena. Lotte».",
      "Und auf eine Postkarte: „Liebe Oma, heute habe ich mit einer ecuadorianischen Großmutter gefeilscht. Sie hat gewonnen, natürlich. Ich schicke dir einen Schal, auf den der See gezeichnet ist. Ich habe ein bisschen zu viel bezahlt, aber es hat sich gelohnt. Lotte.“",
      "And on a postcard: ‘Dear Oma, today I haggled with an Ecuadorian grandmother. She won, of course. I’m sending you a scarf with the lake on it. I paid a bit too much, but it was worth it. Lotte.’",
      "Και σε μια καρτ ποστάλ: «Αγαπημένη μου Όμα, σήμερα παζάρεψα με μια γιαγιά από τον Ισημερινό. Κέρδισε εκείνη, φυσικά. Σου στέλνω ένα κασκόλ με τη λίμνη ζωγραφισμένη. Πλήρωσα λίγο παραπάνω, αλλά άξιζε τον κόπο. Λότε».")
  ]));

  // ── Station 6 · bahnhof ──────────────────────────────
  K.push(S(6, "bahnhof", "El bus ya había salido",
    { de: "Busterminal Quitumbe, fünf nach zehn: Lottes Bus ist schon weg. Der nächste fährt in den Regenwald — bis ein Erdrutsch die Straße versperrt.",
      en: "Quitumbe bus terminal, five past ten: Lotte’s bus has already gone. The next one heads for the rainforest — until a landslide blocks the road.",
      el: "Σταθμός λεωφορείων Κιτούμπε, δέκα και πέντε: το λεωφορείο της Λότε έχει ήδη φύγει. Το επόμενο πάει στη ζούγκλα — ώσπου μια κατολίσθηση κλείνει τον δρόμο." },
  [
    Z("Febrero. La Terminal Quitumbe, en el sur de Quito, era enorme: un aeropuerto para buses. Había ventanillas de veinte compañías, gente con mochilas, cajas, sacos de papas y, en un rincón, un señor que vendía helados a las diez de la mañana.",
      "Februar. Das Terminal Quitumbe im Süden von Quito war riesig: ein Flughafen für Busse. Es gab Schalter von zwanzig Busgesellschaften, Leute mit Rucksäcken, Kisten, Kartoffelsäcken und in einer Ecke einen Mann, der um zehn Uhr morgens Eis verkaufte.",
      "February. The Quitumbe Terminal, in the south of Quito, was enormous: an airport for buses. There were ticket windows for twenty companies, people with rucksacks, boxes, sacks of potatoes and, in a corner, a man selling ice cream at ten in the morning.",
      "Φεβρουάριος. Ο σταθμός Κιτούμπε, στο νότιο Κίτο, ήταν τεράστιος: ένα αεροδρόμιο για λεωφορεία. Υπήρχαν θυρίδες από είκοσι εταιρείες, κόσμος με σακίδια, κούτες, τσουβάλια με πατάτες και, σε μια γωνία, ένας κύριος που πουλούσε παγωτά στις δέκα το πρωί."),
    Z("Lotte llegó corriendo a las diez y cinco. Había vuelto al hostal por el trípode, que se había quedado debajo de la cama, y después el taxi se había quedado atrapado en el tráfico.",
      "Lotte kam um fünf nach zehn angerannt. Sie war noch einmal ins Hostel zurückgegangen, wegen des Stativs, das unter dem Bett liegen geblieben war, und dann war das Taxi im Verkehr stecken geblieben.",
      "Lotte came running in at five past ten. She had gone back to the hostel for her tripod, which had been left under the bed, and then the taxi had got stuck in the traffic.",
      "Η Λότε έφτασε τρέχοντας στις δέκα και πέντε. Είχε γυρίσει στον ξενώνα για το τρίποδο, που είχε μείνει κάτω από το κρεβάτι, και μετά το ταξί είχε κολλήσει στην κίνηση."),
    Z("—Buenos días. Quería un pasaje para Tena en el bus de las diez.",
      "Guten Morgen. Ich hätte gern eine Fahrkarte nach Tena für den Bus um zehn.",
      "Good morning. I'd like a ticket to Tena on the ten o'clock bus.",
      "Καλημέρα. Θα ήθελα ένα εισιτήριο για την Τένα με το λεωφορείο των δέκα."),
    Z("La señora de la boletería miró el reloj y puso cara de pena.",
      "Die Frau am Fahrkartenschalter sah auf die Uhr und machte ein bedauerndes Gesicht.",
      "The woman at the ticket office looked at the clock and made a sorry face.",
      "Η κυρία στο εκδοτήριο κοίταξε το ρολόι κι έκανε μια λυπημένη φάτσα."),
    Z("—Ay, lo siento. El bus de las diez acaba de salir, hace cinco minutos.",
      "Ach, das tut mir leid. Der Bus um zehn ist gerade abgefahren, vor fünf Minuten.",
      "Oh, I'm sorry. The ten o'clock bus has just left, five minutes ago.",
      "Αχ, λυπάμαι. Το λεωφορείο των δέκα μόλις έφυγε, πριν από πέντε λεπτά."),
    Z("—¡Qué pena! Mi taxi llegó tarde y el bus ya había salido. ¿Cuándo sale el siguiente?",
      "Wie schade! Mein Taxi kam zu spät, und der Bus war schon abgefahren. Wann fährt der nächste?",
      "What a shame! My taxi was late and the bus had already left. When does the next one leave?",
      "Τι κρίμα! Το ταξί μου άργησε και το λεωφορείο είχε ήδη φύγει. Πότε φεύγει το επόμενο;"),
    Z("—A las once y media. Pero ojo: hubo un derrumbe en la carretera y puede demorarse. ¿Lleva equipaje?",
      "Um halb zwölf. Aber Achtung: Auf der Straße gab es einen Erdrutsch, es kann länger dauern. Haben Sie Gepäck?",
      "At half past eleven. But watch out: there's been a landslide on the road and it may be delayed. Do you have any luggage?",
      "Στις έντεκα και μισή. Αλλά προσοχή: έγινε κατολίσθηση στον δρόμο και μπορεί να καθυστερήσει. Έχετε αποσκευές;"),
    Z("—Sí, una mochila grande. Pero la cámara la llevo conmigo.",
      "Ja, einen großen Rucksack. Aber die Kamera behalte ich bei mir.",
      "Yes, a big rucksack. But I'll keep the camera with me.",
      "Ναι, ένα μεγάλο σακίδιο. Αλλά τη φωτογραφική μηχανή την κρατάω μαζί μου."),
    Z("—Muy bien. La mochila va abajo, en la bodega. Andén siete, asiento doce. Son seis dólares.",
      "Sehr gut. Der Rucksack kommt unten in den Gepäckraum. Steig sieben, Platz zwölf. Das macht sechs Dollar.",
      "Very good. The rucksack goes underneath, in the hold. Platform seven, seat twelve. That's six dollars.",
      "Πολύ καλά. Το σακίδιο πάει κάτω, στο αμπάρι. Αποβάθρα επτά, θέση δώδεκα. Κάνει έξι δολάρια."),
    Z("—Con gusto —dijo Lotte, y pagó.",
      "„Sehr gern“, sagte Lotte und bezahlte.",
      "‘With pleasure,’ said Lotte, and paid.",
      "«Με χαρά», είπε η Λότε, και πλήρωσε."),
    Z("Con gusto. No «vale». Lotte se dio cuenta en ese momento: hacía semanas que el «vale» ya no le salía solo. En su lugar salía «con gusto», como si siempre hubiera estado allí.",
      "Con gusto — nicht „vale“. In diesem Moment merkte Lotte es: Seit Wochen kam ihr das „vale“ nicht mehr von allein über die Lippen. Stattdessen kam „con gusto“, als wäre es schon immer da gewesen.",
      "Con gusto — not “vale”. Lotte realised it at that moment: for weeks now, “vale” hadn't slipped out on its own. Instead out came “con gusto”, as if it had always been there.",
      "Con gusto — όχι «vale». Η Λότε το κατάλαβε εκείνη τη στιγμή: εδώ και βδομάδες το «vale» δεν της έβγαινε πια μόνο του. Στη θέση του έβγαινε το «con gusto», σαν να ήταν πάντα εκεί."),
    Z("La Leica iba en su bolso, contra el pecho. La cámara nunca viajaba abajo. Nunca.",
      "Die Leica steckte in ihrer Tasche, dicht an der Brust. Die Kamera reiste nie unten. Niemals.",
      "The Leica was in her bag, against her chest. The camera never travelled underneath. Never.",
      "Η Leica ήταν στην τσάντα της, πάνω στο στήθος της. Η μηχανή δεν ταξίδευε ποτέ κάτω. Ποτέ."),
    Z("Mientras esperaba, llegó un mensaje de voz de Bram:",
      "Während sie wartete, kam eine Sprachnachricht von Bram:",
      "While she was waiting, a voice message arrived from Bram:",
      "Ενώ περίμενε, ήρθε ένα φωνητικό μήνυμα από τον Μπραμ:"),
    Z("—Lotte, acabo de ver el mapa. ¿Cinco horas en bus? ¿Por qué no tomas un avión, como una persona normal?",
      "Lotte, ich habe mir gerade die Karte angesehen. Fünf Stunden mit dem Bus? Warum nimmst du nicht das Flugzeug, wie ein normaler Mensch?",
      "Lotte, I’ve just looked at the map. Five hours by bus? Why don’t you take a plane, like a normal person?",
      "Λότε, μόλις είδα τον χάρτη. Πέντε ώρες με το λεωφορείο; Γιατί δεν παίρνεις αεροπλάνο, σαν κανονικός άνθρωπος;"),
    Z("Lotte contestó: «Porque desde el avión no se ve el agua, Bram».",
      "Lotte antwortete: „Weil man aus dem Flugzeug das Wasser nicht sieht, Bram.“",
      "Lotte replied: ‘Because you can’t see the water from a plane, Bram.’",
      "Η Λότε απάντησε: «Γιατί από το αεροπλάνο δεν φαίνεται το νερό, Μπραμ»."),
    Z("En el bus de las once y media, a su lado, se sentó doña Julia, que volvía a Tena con una caja de pan y con su nieto Kevin, de ocho años.",
      "Im Bus um halb zwölf setzte sich Doña Julia neben sie. Sie fuhr mit einer Kiste Brot und ihrem achtjährigen Enkel Kevin zurück nach Tena.",
      "On the half past eleven bus, Doña Julia sat down next to her. She was going home to Tena with a box of bread and her eight-year-old grandson, Kevin.",
      "Στο λεωφορείο των έντεκα και μισή κάθισε δίπλα της η κυρία Χούλια, που γύριζε στην Τένα με ένα κουτί ψωμί και με τον εγγονό της τον Κέβιν, οχτώ χρονών."),
    Z("—¿Usted es de Estados Unidos? —preguntó Kevin.",
      "Sind Sie aus den USA?, fragte Kevin.",
      "Are you from the United States? Kevin asked.",
      "«Εσείς είστε από τις Ηνωμένες Πολιτείες;» ρώτησε ο Κέβιν."),
    Z("—No, de los Países Bajos. De Holanda.",
      "Nein, aus den Niederlanden. Aus Holland.",
      "No, from the Netherlands. From Holland.",
      "Όχι, από τις Κάτω Χώρες. Από την Ολλανδία."),
    Z("—¿Allá hay selva?",
      "Gibt es dort Urwald?",
      "Is there jungle there?",
      "Εκεί έχει ζούγκλα;"),
    Z("—No. Allá hay vacas y bicicletas. Y mucha agua, pero toda muy ordenada.",
      "Nein. Dort gibt es Kühe und Fahrräder. Und viel Wasser, aber alles sehr ordentlich.",
      "No. There are cows and bicycles there. And lots of water, but all very tidy.",
      "Όχι. Εκεί έχει αγελάδες και ποδήλατα. Και πολύ νερό, αλλά όλο πολύ τακτοποιημένο."),
    Z("Kevin se rió tanto que se le cayó el pan.",
      "Kevin lachte so sehr, dass ihm das Brot herunterfiel.",
      "Kevin laughed so hard that he dropped the bread.",
      "Ο Κέβιν γέλασε τόσο πολύ που του έπεσε το ψωμί."),
    Z("El bus bajaba y bajaba. Por la ventana, los Andes se convertían poco a poco en selva. Hacía cada vez más calor. Lotte se quitó la chompa, como llaman aquí al suéter, y después la bufanda.",
      "Der Bus fuhr immer weiter bergab. Vor dem Fenster wurden die Anden nach und nach zu Regenwald. Es wurde immer wärmer. Lotte zog die Chompa aus, wie man hier den Pullover nennt, und dann den Schal.",
      "The bus went down and down. Outside the window, the Andes were slowly turning into rainforest. It was getting hotter and hotter. Lotte took off her chompa, as they call a jumper here, and then her scarf.",
      "Το λεωφορείο κατέβαινε και κατέβαινε. Έξω από το παράθυρο, οι Άνδεις γίνονταν σιγά σιγά ζούγκλα. Έκανε όλο και περισσότερη ζέστη. Η Λότε έβγαλε την τσόμπα, όπως λένε εδώ το πουλόβερ, και μετά το κασκόλ."),
    Z("Cerca de Baeza, el bus se detuvo. Delante había una fila larga de carros, camiones y buses.",
      "In der Nähe von Baeza hielt der Bus an. Vor ihnen stand eine lange Schlange aus Autos, Lastwagen und Bussen.",
      "Near Baeza, the bus stopped. Ahead there was a long queue of cars, lorries and buses.",
      "Κοντά στη Μπαέσα, το λεωφορείο σταμάτησε. Μπροστά υπήρχε μια μεγάλη ουρά από αυτοκίνητα, φορτηγά και λεωφορεία."),
    Z("—Señores pasajeros, aquí está el derrumbe —dijo el chofer—. Con la lluvia de anoche se cayó un pedazo de montaña. Las máquinas ya están limpiando. Vamos a esperar una hora, más o menos.",
      "„Meine Damen und Herren, hier ist der Erdrutsch“, sagte der Fahrer. „Durch den Regen heute Nacht ist ein Stück Berg heruntergekommen. Die Maschinen räumen schon. Wir werden ungefähr eine Stunde warten.“",
      "‘Ladies and gentlemen, here's the landslide,’ said the driver. ‘With last night's rain, a piece of mountain came down. The machines are already clearing it. We're going to wait about an hour.’",
      "«Κυρίες και κύριοι επιβάτες, εδώ είναι η κατολίσθηση», είπε ο οδηγός. «Με τη βροχή της νύχτας, έπεσε ένα κομμάτι βουνό. Τα μηχανήματα ήδη καθαρίζουν. Θα περιμένουμε μία ώρα, πάνω κάτω»."),
    Z("—¿Vamos a llegar hoy a Tena? —preguntó Lotte.",
      "Kommen wir heute noch in Tena an?, fragte Lotte.",
      "Are we going to get to Tena today? Lotte asked.",
      "«Θα φτάσουμε σήμερα στην Τένα;» ρώτησε η Λότε."),
    Z("—De ley —dijo doña Julia, muy tranquila—. Seguro, seguro. En la Amazonía uno aprende a esperar. Aquí el agua manda.",
      "Auf jeden Fall, sagte Doña Julia ganz ruhig. Ganz sicher. Im Amazonasgebiet lernt man zu warten. Hier hat das Wasser das Sagen.",
      "Definitely, said Doña Julia, perfectly calm. For sure, for sure. In the Amazon you learn to wait. Here, the water is in charge.",
      "«Σίγουρα», είπε η κυρία Χούλια, πολύ ήρεμη. «Σίγουρα, σίγουρα. Στον Αμαζόνιο μαθαίνεις να περιμένεις. Εδώ το νερό κάνει κουμάντο»."),
    Z("De pronto, Kevin señaló por la ventana.",
      "Plötzlich zeigte Kevin aus dem Fenster.",
      "Suddenly Kevin pointed out of the window.",
      "Ξαφνικά ο Κέβιν έδειξε έξω από το παράθυρο."),
    Z("—¡Mire, señorita! ¡Su bus!",
      "Schauen Sie, Fräulein! Ihr Bus!",
      "Look, miss! Your bus!",
      "Κοιτάξτε, δεσποινίς! Το λεωφορείο σας!"),
    Z("Era verdad. Diez carros más adelante estaba el bus de las diez. El bus que ella había perdido. Había salido antes, había llegado antes al derrumbe... y llevaba una hora más esperando.",
      "Es stimmte. Zehn Autos weiter vorn stand der Bus von zehn Uhr. Der Bus, den sie verpasst hatte. Er war früher abgefahren, er war früher am Erdrutsch angekommen ... und wartete schon eine Stunde länger.",
      "It was true. Ten cars further ahead stood the ten o'clock bus. The bus she had missed. It had left earlier, it had reached the landslide earlier... and it had been waiting an hour longer.",
      "Ήταν αλήθεια. Δέκα αυτοκίνητα πιο μπροστά ήταν το λεωφορείο των δέκα. Το λεωφορείο που είχε χάσει. Είχε φύγει νωρίτερα, είχε φτάσει νωρίτερα στην κατολίσθηση... και περίμενε ήδη μία ώρα παραπάνω."),
    Z("Lotte se rió hasta que le dolió la barriga. Después compró un choclo con queso a un vendedor que apareció de la nada, como aparecen siempre los vendedores en la carretera.",
      "Lotte lachte, bis ihr der Bauch wehtat. Dann kaufte sie einen Maiskolben mit Käse bei einem Verkäufer, der aus dem Nichts auftauchte, so wie Verkäufer an der Landstraße immer auftauchen.",
      "Lotte laughed until her stomach hurt. Then she bought a corn cob with cheese from a vendor who appeared out of nowhere, the way vendors always appear by the roadside.",
      "Η Λότε γέλασε μέχρι που την πόνεσε η κοιλιά της. Μετά αγόρασε ένα καλαμπόκι με τυρί από έναν πωλητή που εμφανίστηκε από το πουθενά, όπως εμφανίζονται πάντα οι πωλητές στον δρόμο."),
    Z("Llegaron a Tena a las seis, con la última luz del día. Lotte bajó enseguida al río Napo. Pasaba ancho y de color café, con prisa, lleno de la lluvia de los Andes. Desde aquí empezaba su largo viaje hasta el Amazonas y hasta el mar.",
      "Sie kamen um sechs in Tena an, im letzten Tageslicht. Lotte ging sofort hinunter zum Fluss Napo. Er floss breit und kaffeebraun vorbei, in Eile, voller Regen aus den Anden. Von hier aus begann seine lange Reise bis zum Amazonas und bis zum Meer.",
      "They reached Tena at six, in the last of the daylight. Lotte went straight down to the Napo River. It flowed past, wide and coffee-coloured, in a hurry, full of rain from the Andes. From here it began its long journey to the Amazon and on to the sea.",
      "Έφτασαν στην Τένα στις έξι, με το τελευταίο φως της μέρας. Η Λότε κατέβηκε αμέσως στον ποταμό Νάπο. Κυλούσε φαρδύς και καφετής, βιαστικός, γεμάτος βροχή από τις Άνδεις. Από εδώ άρχιζε το μακρύ του ταξίδι ως τον Αμαζόνιο και ως τη θάλασσα."),
    Z("Kevin y otros niños saltaban al agua desde una piedra grande. Lotte hizo la foto justo en el momento del salto: cinco niños en el aire, y debajo, el río.",
      "Kevin und andere Kinder sprangen von einem großen Felsen ins Wasser. Lotte machte das Foto genau im Moment des Sprungs: fünf Kinder in der Luft und darunter der Fluss.",
      "Kevin and some other children were jumping into the water from a big rock. Lotte took the photo at the exact moment of the jump: five children in the air, and below them, the river.",
      "Ο Κέβιν και άλλα παιδιά πηδούσαν στο νερό από έναν μεγάλο βράχο. Η Λότε έβγαλε τη φωτογραφία ακριβώς τη στιγμή του άλματος: πέντε παιδιά στον αέρα και από κάτω το ποτάμι."),
    Z("En el cuaderno escribió: «Palabra del lugar: de ley. Quiere decir: seguro, sin duda. Hoy llegué tarde a todo. Pero llegué. De ley».",
      "Ins Notizbuch schrieb sie: „Wort des Ortes: de ley. Das heißt: sicher, ohne Zweifel. Heute kam ich überall zu spät. Aber ich bin angekommen. De ley.“",
      "In her notebook she wrote: ‘Word of the place: de ley. It means: for sure, without a doubt. Today I was late for everything. But I got there. De ley.’",
      "Στο σημειωματάριο έγραψε: «Λέξη του τόπου: de ley. Σημαίνει: σίγουρα, χωρίς αμφιβολία. Σήμερα άργησα παντού. Αλλά έφτασα. De ley»."),
    Z("Y a Oma Fenna: «Querida Oma: hoy perdí un bus, y después lo encontré en medio de una montaña. Aquí los ríos son de color café y tienen prisa. Como yo esta mañana. Un beso, Lotte».",
      "Und an Oma Fenna: „Liebe Oma, heute habe ich einen Bus verpasst und ihn dann mitten auf einem Berg wiedergefunden. Hier sind die Flüsse kaffeebraun und haben es eilig. So wie ich heute Morgen. Ein Kuss, Lotte.“",
      "And to Oma Fenna: ‘Dear Oma, today I missed a bus, and then I found it again in the middle of a mountain. The rivers here are coffee-coloured and in a hurry. Like me this morning. Love, Lotte.’",
      "Και στην Όμα Φένα: «Αγαπημένη μου Όμα, σήμερα έχασα ένα λεωφορείο και μετά το ξαναβρήκα στη μέση ενός βουνού. Εδώ τα ποτάμια είναι καφετιά και βιάζονται. Όπως εγώ σήμερα το πρωί. Φιλιά, Λότε».")
  ]));

  // ── Station 7 · taxi ──────────────────────────────
  K.push(S(7, "taxi", "¿Y usted se quedaría?",
    { de: "Asunción, achtunddreißig Grad: Taxifahrer Don Rolando bringt Lotte ein Wort Guaraní bei, teilt seinen Tereré mit ihr — und stellt ihr eine Frage, die sie nicht mehr loslässt.",
      en: "Asunción, thirty-eight degrees: taxi driver Don Rolando teaches Lotte a word of Guaraní, shares his tereré with her — and asks her a question she can’t stop thinking about.",
      el: "Ασουνσιόν, τριάντα οκτώ βαθμοί: ο ταξιτζής δον Ρολάντο μαθαίνει στη Λότε μια λέξη γκουαρανί, μοιράζεται μαζί της το τερερέ του — και της κάνει μια ερώτηση που δεν της βγαίνει από το μυαλό." },
  [
    Z("Asunción, principios de marzo. A las tres de la tarde, el termómetro de la farmacia de la esquina marcaba treinta y ocho grados.",
      "Asunción, Anfang März. Um drei Uhr nachmittags zeigte das Thermometer der Apotheke an der Ecke achtunddreißig Grad.",
      "Asunción, early March. At three in the afternoon, the thermometer outside the chemist’s on the corner said thirty-eight degrees.",
      "Ασουνσιόν, αρχές Μαρτίου. Στις τρεις το απόγευμα, το θερμόμετρο του φαρμακείου στη γωνία έδειχνε τριάντα οκτώ βαθμούς."),
    Z("Lotte salió del hotel y sintió el calor como una pared. Levantó la mano. Un taxi amarillo se detuvo enseguida.",
      "Lotte trat aus dem Hotel und spürte die Hitze wie eine Wand. Sie hob die Hand. Sofort hielt ein gelbes Taxi an.",
      "Lotte stepped out of the hotel and felt the heat like a wall. She raised her hand. A yellow taxi stopped straight away.",
      "Η Λότε βγήκε από το ξενοδοχείο και ένιωσε τη ζέστη σαν τοίχο. Σήκωσε το χέρι. Ένα κίτρινο ταξί σταμάτησε αμέσως."),
    Z("—Buenas tardes. ¿Me lleva a la costanera, cerca del río, por favor?",
      "Guten Tag. Bringen Sie mich bitte zur Uferpromenade, in die Nähe des Flusses?",
      "Good afternoon. Could you take me to the riverside promenade, near the river, please?",
      "Καλησπέρα σας. Με πηγαίνετε στην παραλιακή, κοντά στο ποτάμι, παρακαλώ;"),
    Z("—Buenas tardes. ¡Mba'éichapa! Así saludamos en guaraní. ¿Mucho calor, señorita?",
      "Guten Tag. Mba'éichapa! So grüßen wir auf Guaraní. Ganz schön heiß, oder, Señorita?",
      "Good afternoon. Mba'éichapa! That's how we say hello in Guaraní. Very hot, miss?",
      "Καλησπέρα. Mba'éichapa! Έτσι χαιρετάμε στα γκουαρανί. Πολλή ζέστη, δεσποινίς;"),
    Z("—Sí, muchísimo. En Holanda ahora hace frío y llueve todo el tiempo.",
      "Ja, sehr. In Holland ist es jetzt kalt, und es regnet ständig.",
      "Yes, very. In Holland it's cold now and it rains all the time.",
      "Ναι, πάρα πολλή. Στην Ολλανδία τώρα κάνει κρύο και βρέχει συνέχεια."),
    Z("El taxista sonrió al ver la cara de Lotte. —Mba'éichapa quiere decir «¿cómo está?». Usted tiene que contestar «Iporã», que es «bien».",
      "Der Taxifahrer lächelte, als er Lottes Gesicht sah. „Mba'éichapa heißt ‚Wie geht es Ihnen?‘. Sie müssen ‚Iporã‘ antworten, das heißt ‚gut‘.“",
      "The taxi driver smiled when he saw Lotte's face. ‘Mba'éichapa means “How are you?”. You have to answer “Iporã”, which means “fine”.’",
      "Ο ταξιτζής χαμογέλασε όταν είδε τη φάτσα της Λότε. «Mba'éichapa σημαίνει “τι κάνετε;”. Εσείς πρέπει να απαντήσετε “Iporã”, που σημαίνει “καλά”»."),
    Z("—Iporã —repitió Lotte.",
      "Iporã, wiederholte Lotte.",
      "Iporã, Lotte repeated.",
      "«Iporã», επανέλαβε η Λότε."),
    Z("—¡Muy bien! Ya es medio paraguaya. Yo soy Rolando. Suba, suba, que adentro hay aire acondicionado. Bueno, más o menos.",
      "Sehr gut! Sie sind schon halbe Paraguayerin. Ich bin Rolando. Steigen Sie ein, drinnen gibt es eine Klimaanlage. Na ja, mehr oder weniger.",
      "Very good! You’re already half Paraguayan. I’m Rolando. Get in, get in, there’s air conditioning inside. Well, sort of.",
      "Πολύ ωραία! Είστε ήδη μισή Παραγουανή. Εγώ είμαι ο Ρολάντο. Ανεβείτε, ανεβείτε, μέσα έχει κλιματισμό. Εντάξει, πάνω κάτω."),
    Z("En Paraguay hay dos idiomas oficiales, el castellano y el guaraní. Don Rolando hablaba los dos, muchas veces en la misma frase.",
      "In Paraguay gibt es zwei Amtssprachen, Spanisch und Guaraní. Don Rolando sprach beide, oft im selben Satz.",
      "Paraguay has two official languages, Spanish and Guaraní. Don Rolando spoke both, often in the same sentence.",
      "Στην Παραγουάη υπάρχουν δύο επίσημες γλώσσες, τα ισπανικά και τα γκουαρανί. Ο δον Ρολάντο μιλούσε και τις δύο, συχνά στην ίδια πρόταση."),
    Z("Entre los asientos llevaba un termo grande, forrado de cuero, y en la mano una guampa, un vaso de madera con una bombilla de metal.",
      "Zwischen den Sitzen hatte er eine große, mit Leder bezogene Thermoskanne und in der Hand eine Guampa, einen Holzbecher mit einem Metallröhrchen.",
      "Between the seats he had a big leather-covered flask, and in his hand a guampa, a wooden cup with a metal straw.",
      "Ανάμεσα στα καθίσματα είχε ένα μεγάλο θερμός ντυμένο με δέρμα, και στο χέρι μια γκουάμπα, ένα ξύλινο ποτήρι με ένα μεταλλικό καλαμάκι."),
    Z("—Por eso aquí tomamos tereré: yerba mate con agua bien fría. ¿Ya lo probó?",
      "Deshalb trinken wir hier Tereré: Mate-Kraut mit eiskaltem Wasser. Haben Sie ihn schon probiert?",
      "That's why we drink tereré here: yerba mate with ice-cold water. Have you tried it yet?",
      "Γι' αυτό εδώ πίνουμε τερερέ: γέρμπα ματέ με παγωμένο νερό. Το έχετε δοκιμάσει;"),
    Z("—Todavía no, pero me encantaría probarlo.",
      "Noch nicht, aber ich würde ihn sehr gern probieren.",
      "Not yet, but I'd love to try it.",
      "Όχι ακόμα, αλλά θα ήθελα πολύ να το δοκιμάσω."),
    Z("—Pruebe, pruebe. Con este calor, el tereré es la vida.",
      "Probieren Sie, probieren Sie. Bei dieser Hitze ist Tereré das Leben.",
      "Go on, try it. In this heat, tereré is life.",
      "Δοκιμάστε, δοκιμάστε. Με αυτή τη ζέστη, το τερερέ είναι ζωή."),
    Z("El tereré era amargo y fresco, como un bosque después de la lluvia. En Paraguay se comparte: hay una sola guampa para todos, y el que sirve es el dueño del termo.",
      "Der Tereré war bitter und frisch, wie ein Wald nach dem Regen. In Paraguay teilt man ihn: Es gibt nur eine Guampa für alle, und wer einschenkt, ist der, dem die Thermoskanne gehört.",
      "The tereré was bitter and fresh, like a forest after the rain. In Paraguay it’s shared: there’s just one guampa for everyone, and the person who pours is the owner of the flask.",
      "Το τερερέ ήταν πικρό και δροσερό, σαν δάσος μετά τη βροχή. Στην Παραγουάη το μοιράζονται: υπάρχει μία μόνο γκουάμπα για όλους, και αυτός που σερβίρει είναι ο ιδιοκτήτης του θερμός."),
    Z("—¿Siempre hace tanto calor?",
      "Ist es immer so heiß?",
      "Is it always this hot?",
      "Κάνει πάντα τόση ζέστη;"),
    Z("—No, señorita. A veces hace más.",
      "Nein, Fräulein. Manchmal ist es heißer.",
      "No, miss. Sometimes it’s hotter.",
      "Όχι, δεσποινίς. Μερικές φορές κάνει περισσότερη."),
    Z("Don Rolando la miró por el espejo.",
      "Don Rolando sah sie im Rückspiegel an.",
      "Don Rolando looked at her in the mirror.",
      "Ο δον Ρολάντο την κοίταξε από τον καθρέφτη."),
    Z("—¿Y usted de dónde es?",
      "Und woher sind Sie?",
      "And where are you from?",
      "Κι εσείς από πού είστε;"),
    Z("—De los Países Bajos. De Utrecht.",
      "Aus den Niederlanden. Aus Utrecht.",
      "From the Netherlands. From Utrecht.",
      "Από τις Κάτω Χώρες. Από την Ουτρέχτη."),
    Z("—¡Holanda! Tengo tres clientes holandeses. Y alemanes, muchos. Muchos europeos vienen a vivir aquí por la calma y el espacio.",
      "Holland! Ich habe drei holländische Kunden. Und Deutsche, viele. Viele Europäer kommen hierher, um hier zu leben, wegen der Ruhe und des Platzes.",
      "Holland! I've got three Dutch customers. And Germans, lots. Many Europeans come to live here for the calm and the space.",
      "Ολλανδία! Έχω τρεις Ολλανδούς πελάτες. Και Γερμανούς, πολλούς. Πολλοί Ευρωπαίοι έρχονται να ζήσουν εδώ για την ηρεμία και τον χώρο."),
    Z("—¿Solo por la calma?",
      "Nur wegen der Ruhe?",
      "Just for the calm?",
      "Μόνο για την ηρεμία;"),
    Z("—Por la calma y por el tiempo, dicen. Aquí nadie corre. La gente saluda en la calle. Los domingos la familia come junta, un asado de cuatro horas. Y no hay nieve, claro.",
      "Wegen der Ruhe und wegen der Zeit, sagen sie. Hier rennt niemand. Die Leute grüßen auf der Straße. Sonntags isst die Familie zusammen, ein Grillfest von vier Stunden. Und es gibt keinen Schnee, natürlich.",
      "For the calm and the time, they say. Nobody rushes here. People say hello in the street. On Sundays the family eats together, a four-hour barbecue. And there's no snow, of course.",
      "Για την ηρεμία και για τον χρόνο, λένε. Εδώ κανείς δεν τρέχει. Ο κόσμος χαιρετάει στον δρόμο. Τις Κυριακές η οικογένεια τρώει μαζί, ένα ψητό τεσσάρων ωρών. Και δεν έχει χιόνι, φυσικά."),
    Z("Se quedó callado un momento. Después preguntó:",
      "Er schwieg einen Moment. Dann fragte er:",
      "He was quiet for a moment. Then he asked:",
      "Έμεινε σιωπηλός για λίγο. Μετά ρώτησε:"),
    Z("—¿Y usted? ¿Usted se quedaría?",
      "Und Sie? Würden Sie bleiben?",
      "And you? Would you stay?",
      "Κι εσείς; Θα μένατε;"),
    Z("Lotte lo pensó en serio. Tendría una casa con patio y un árbol de mango. Tomaría tereré a la sombra. Aprendería guaraní. Haría fotos del río todos los días.",
      "Lotte dachte ernsthaft darüber nach. Sie hätte ein Haus mit Innenhof und einem Mangobaum. Sie würde im Schatten Tereré trinken. Sie würde Guaraní lernen. Sie würde jeden Tag Fotos vom Fluss machen.",
      "Lotte thought about it seriously. She would have a house with a courtyard and a mango tree. She would drink tereré in the shade. She would learn Guaraní. She would take photos of the river every day.",
      "Η Λότε το σκέφτηκε σοβαρά. Θα είχε ένα σπίτι με αυλή και μια μανγκιά. Θα έπινε τερερέ στη σκιά. Θα μάθαινε γκουαρανί. Θα έβγαζε φωτογραφίες του ποταμού κάθε μέρα."),
    Z("Pero... ¿y Oma Fenna? ¿Y Bram? ¿Y el invierno de Holanda, que en el fondo le gustaba un poquito?",
      "Aber ... und Oma Fenna? Und Bram? Und der holländische Winter, den sie im Grunde ein kleines bisschen mochte?",
      "But... what about Oma Fenna? And Bram? And the Dutch winter, which deep down she liked just a little?",
      "Αλλά... και η Όμα Φένα; Και ο Μπραμ; Και ο ολλανδικός χειμώνας, που κατά βάθος της άρεσε λιγάκι;"),
    Z("—Me quedaría un tiempo, sí. Viviría cerca del río y sacaría fotos. —Lo pensó un segundo más—. Sobre todo en enero, cuando en Utrecht todo está gris.",
      "„Ich würde eine Zeit lang bleiben, ja. Ich würde am Fluss wohnen und fotografieren.“ Sie überlegte noch eine Sekunde. „Vor allem im Januar, wenn in Utrecht alles grau ist.“",
      "‘I'd stay for a while, yes. I'd live near the river and take photos.’ She thought for one more second. ‘Especially in January, when everything in Utrecht is grey.’",
      "«Θα έμενα για λίγο καιρό, ναι. Θα ζούσα κοντά στο ποτάμι και θα έβγαζα φωτογραφίες.» Το σκέφτηκε ένα δευτερόλεπτο ακόμα. «Κυρίως τον Ιανουάριο, όταν στην Ουτρέχτη όλα είναι γκρίζα.»"),
    Z("Don Rolando se rió tan fuerte que el taxi se movió un poco.",
      "Don Rolando lachte so laut, dass das Taxi ein bisschen wackelte.",
      "Don Rolando laughed so hard that the taxi shook a little.",
      "Ο δον Ρολάντο γέλασε τόσο δυνατά που το ταξί κουνήθηκε λίγο."),
    Z("—¡Esa es la respuesta de todos los holandeses! Yo, en cambio, nunca viviría en otro lugar. Una vez fui a Buenos Aires, tres días. Mucho ruido. Volví con dolor de cabeza y sin tereré.",
      "Das ist die Antwort aller Holländer! Ich dagegen würde nie woanders leben. Einmal war ich in Buenos Aires, drei Tage. Viel Lärm. Ich kam mit Kopfweh zurück und ohne Tereré.",
      "That’s what all the Dutch say! Me, on the other hand, I’d never live anywhere else. I went to Buenos Aires once, for three days. Lots of noise. I came back with a headache and no tereré.",
      "Αυτή είναι η απάντηση όλων των Ολλανδών! Εγώ, αντίθετα, δεν θα ζούσα ποτέ αλλού. Μια φορά πήγα στο Μπουένος Άιρες, τρεις μέρες. Πολύς θόρυβος. Γύρισα με πονοκέφαλο και χωρίς τερερέ."),
    Z("El celular de Lotte vibró. Bram:",
      "Lottes Handy vibrierte. Bram:",
      "Lotte’s mobile buzzed. Bram:",
      "Το κινητό της Λότε δόνησε. Ο Μπραμ:"),
    Z("—Lotte, aquí hace cuatro grados. Mándame calor en una foto. Y el río. Sobre todo el río.",
      "Lotte, hier hat es vier Grad. Schick mir Wärme auf einem Foto. Und den Fluss. Vor allem den Fluss.",
      "Lotte, it’s four degrees here. Send me some heat in a photo. And the river. Above all, the river.",
      "Λότε, εδώ έχει τέσσερις βαθμούς. Στείλε μου ζέστη σε μια φωτογραφία. Και το ποτάμι. Πάνω απ' όλα το ποτάμι."),
    Z("—¿Su novio? —preguntó don Rolando.",
      "Ihr Freund?, fragte Don Rolando.",
      "Your boyfriend? asked Don Rolando.",
      "«Ο φίλος σας;» ρώτησε ο δον Ρολάντο."),
    Z("—Mi editor. Es peor: él quiere las fotos para ayer.",
      "Mein Lektor. Das ist schlimmer: Er will die Fotos für gestern.",
      "My editor. That’s worse: he wants the photos yesterday.",
      "Ο επιμελητής μου. Είναι χειρότερο: θέλει τις φωτογραφίες για χθες."),
    Z("En la costanera, el río Paraguay era ancho y lento, de color chocolate con leche. La otra orilla era verde y plana, sin una sola montaña. Unos pescadores esperaban en sus botes, sin prisa, como si el río fuera a durar para siempre.",
      "An der Uferpromenade war der Río Paraguay breit und langsam, milchschokoladenbraun. Das andere Ufer war grün und flach, ohne einen einzigen Berg. Ein paar Fischer warteten in ihren Booten, ohne Eile, als würde der Fluss ewig dauern.",
      "At the promenade, the Paraguay River was wide and slow, the colour of milk chocolate. The far bank was green and flat, without a single mountain. A few fishermen waited in their boats, unhurried, as if the river would last for ever.",
      "Στην παραλιακή, ο ποταμός Παραγουάη ήταν φαρδύς και αργός, στο χρώμα της σοκολάτας γάλακτος. Η απέναντι όχθη ήταν πράσινη και επίπεδη, χωρίς ούτε ένα βουνό. Μερικοί ψαράδες περίμεναν στις βάρκες τους, χωρίς βιασύνη, σαν να επρόκειτο το ποτάμι να κρατήσει για πάντα."),
    Z("—¿Cuánto le debo?",
      "Was bin ich Ihnen schuldig?",
      "How much do I owe you?",
      "Πόσο σας χρωστάω;"),
    Z("—Cuarenta mil guaraníes.",
      "Vierzigtausend Guaraníes.",
      "Forty thousand guaraníes.",
      "Σαράντα χιλιάδες γκουαρανί."),
    Z("Cuarenta mil. Lotte hizo la cuenta: unos cinco dólares. En Paraguay la moneda también se llama guaraní, como el idioma. Por un momento se sintió millonaria.",
      "Vierzigtausend. Lotte rechnete nach: ungefähr fünf Dollar. In Paraguay heißt auch die Währung Guaraní, wie die Sprache. Einen Moment lang fühlte sie sich wie eine Millionärin.",
      "Forty thousand. Lotte did the maths: about five dollars. In Paraguay the currency is called guaraní too, like the language. For a moment she felt like a millionaire.",
      "Σαράντα χιλιάδες. Η Λότε έκανε τον λογαριασμό: περίπου πέντε δολάρια. Στην Παραγουάη και το νόμισμα λέγεται γκουαρανί, όπως η γλώσσα. Για μια στιγμή ένιωσε εκατομμυριούχος."),
    Z("—Si un día se queda, me llama —dijo don Rolando, y le dio su tarjeta—. Le enseño guaraní y a preparar un buen tereré.",
      "Wenn Sie eines Tages bleiben, rufen Sie mich an, sagte Don Rolando und gab ihr seine Karte. Ich bringe Ihnen Guaraní bei und wie man einen guten Tereré macht.",
      "If you ever stay, give me a call, said Don Rolando, and he gave her his card. I’ll teach you Guaraní and how to make a good tereré.",
      "«Αν μια μέρα μείνετε, να με πάρετε τηλέφωνο», είπε ο δον Ρολάντο και της έδωσε την κάρτα του. «Θα σας μάθω γκουαρανί και πώς να φτιάχνετε ένα καλό τερερέ»."),
    Z("En el cuaderno: «Palabra del lugar: tereré. Mate frío. Se comparte y se toma despacio. Si tomas uno, ya eres un poco de aquí».",
      "Im Notizbuch: „Wort des Ortes: Tereré. Kalter Mate. Man teilt ihn und trinkt ihn langsam. Wenn du einen trinkst, bist du schon ein bisschen von hier.“",
      "In the notebook: ‘Word of the place: tereré. Cold mate. You share it and you drink it slowly. If you have one, you’re already a little bit from here.’",
      "Στο σημειωματάριο: «Λέξη του τόπου: τερερέ. Κρύο ματέ. Το μοιράζεσαι και το πίνεις αργά. Αν πιεις ένα, είσαι ήδη λίγο από εδώ»."),
    Z("Y en la postal: «Querida Oma: aquí nunca necesitarías calefacción. Yo me quedaría... pero solo en enero. Te echo de menos. Y al frío, un poquito. Lotte».",
      "Und auf der Postkarte: „Liebe Oma, hier bräuchtest du nie eine Heizung. Ich würde bleiben ... aber nur im Januar. Ich vermisse dich. Und die Kälte, ein kleines bisschen. Lotte.“",
      "And on the postcard: ‘Dear Oma, here you’d never need the heating. I’d stay... but only in January. I miss you. And the cold, just a little. Lotte.’",
      "Και στην καρτ ποστάλ: «Αγαπημένη μου Όμα, εδώ δεν θα χρειαζόσουν ποτέ θέρμανση. Εγώ θα έμενα... αλλά μόνο τον Ιανουάριο. Μου λείπεις. Και το κρύο, λιγάκι. Λότε».")
  ]));

  // ── Station 8 · cafe ──────────────────────────────
  K.push(S(8, "cafe", "No creo que el tango sea triste",
    { de: "Buenos Aires, ein hundertjähriges Café: ein Cortado, zwei Medialunas und Don Aníbal am Nebentisch, der vierzig Jahre lang Tango unterrichtet hat — und eine Meinung zu allem hat.",
      en: "Buenos Aires, a hundred-year-old café: a cortado, two medialunas and Don Aníbal at the next table, who taught tango for forty years — and has an opinion about everything.",
      el: "Μπουένος Άιρες, ένα καφέ εκατό χρονών: ένας κορτάδο, δύο μεδιαλούνας και ο δον Ανίμπαλ στο διπλανό τραπέζι, που δίδασκε τάνγκο σαράντα χρόνια — και έχει γνώμη για όλα." },
  [
    Z("Buenos Aires, finales de marzo. Aquí, al sur del mundo, el otoño acababa de empezar. Las hojas de los plátanos caían sobre las veredas, y el aire olía a café y a lluvia.",
      "Buenos Aires, Ende März. Hier, im Süden der Welt, hatte der Herbst gerade begonnen. Die Blätter der Platanen fielen auf die Gehwege, und die Luft roch nach Kaffee und Regen.",
      "Buenos Aires, late March. Here, at the bottom of the world, autumn had only just begun. Leaves from the plane trees were falling on the pavements, and the air smelled of coffee and rain.",
      "Μπουένος Άιρες, τέλη Μαρτίου. Εδώ, στον νότο του κόσμου, το φθινόπωρο μόλις είχε αρχίσει. Τα φύλλα από τα πλατάνια έπεφταν στα πεζοδρόμια, και ο αέρας μύριζε καφέ και βροχή."),
    Z("El café La Esquina de Boedo tenía cien años, mesas de mármol, espejos antiguos y mozos de chaleco negro que se movían entre las mesas como bailarines.",
      "Das Café La Esquina de Boedo war hundert Jahre alt, mit Marmortischen, alten Spiegeln und Kellnern in schwarzen Westen, die sich wie Tänzer zwischen den Tischen bewegten.",
      "Café La Esquina de Boedo was a hundred years old, with marble tables, antique mirrors and waiters in black waistcoats who moved between the tables like dancers.",
      "Το καφέ Λα Εσκίνα ντε Μποέδο ήταν εκατό χρονών, με μαρμάρινα τραπέζια, παλιούς καθρέφτες και σερβιτόρους με μαύρα γιλέκα που κινούνταν ανάμεσα στα τραπέζια σαν χορευτές."),
    Z("—Buenas tardes. ¿Qué le sirvo?",
      "Guten Tag. Was darf ich Ihnen bringen?",
      "Good afternoon. What can I get you?",
      "Καλησπέρα σας. Τι να σας φέρω;"),
    Z("—Un cortado y dos medialunas, por favor.",
      "Einen Cortado und zwei Medialunas, bitte.",
      "A cortado and two medialunas, please.",
      "Έναν κορτάδο και δύο μεδιαλούνας, παρακαλώ."),
    Z("—¿De manteca o de grasa?",
      "Mit Butter oder mit Schmalz?",
      "Butter ones or lard ones?",
      "Με βούτυρο ή με λαρδί;"),
    Z("Lotte no tenía ni idea. En Buenos Aires, la mantequilla se llama manteca, y las medialunas, unos cruasanes pequeños, vienen en dos versiones.",
      "Lotte hatte keine Ahnung. In Buenos Aires heißt Butter manteca, und die Medialunas, kleine Croissants, gibt es in zwei Varianten.",
      "Lotte had no idea. In Buenos Aires, butter is called manteca, and medialunas, little croissants, come in two versions.",
      "Η Λότε δεν είχε ιδέα. Στο Μπουένος Άιρες το βούτυρο λέγεται manteca, και οι μεδιαλούνας, μικρά κρουασάν, υπάρχουν σε δύο εκδοχές."),
    Z("—Una de cada una, por favor. Soy fotógrafa: lo comparo todo.",
      "Eins von jeder Sorte, bitte. Ich bin Fotografin: Ich vergleiche alles.",
      "One of each, please. I’m a photographer: I compare everything.",
      "Μία από την καθεμία, παρακαλώ. Είμαι φωτογράφος: τα συγκρίνω όλα."),
    Z("Mientras esperaba, Lotte sacó la Leica: los espejos, el mármol, la luz que entraba de lado. Clic.",
      "Während sie wartete, holte Lotte die Leica heraus: die Spiegel, der Marmor, das Licht, das von der Seite hereinfiel. Klick.",
      "While she waited, Lotte took out the Leica: the mirrors, the marble, the light coming in from the side. Click.",
      "Όσο περίμενε, η Λότε έβγαλε τη Leica: οι καθρέφτες, το μάρμαρο, το φως που έμπαινε από το πλάι. Κλικ."),
    Z("En la mesa de al lado, un señor muy elegante leía el diario. Tenía más de ochenta años, un sombrero gris y unos zapatos tan brillantes como los espejos del café.",
      "Am Nebentisch las ein sehr eleganter Herr Zeitung. Er war über achtzig, trug einen grauen Hut und Schuhe, die so glänzten wie die Spiegel des Cafés.",
      "At the next table, a very elegant gentleman was reading the paper. He was over eighty, with a grey hat and shoes as shiny as the café’s mirrors.",
      "Στο διπλανό τραπέζι, ένας πολύ κομψός κύριος διάβαζε εφημερίδα. Ήταν πάνω από ογδόντα, με ένα γκρίζο καπέλο και παπούτσια που γυάλιζαν όσο οι καθρέφτες του καφέ."),
    Z("—Perdone que la moleste, señorita. Veo que saca fotos del café. Y un consejo: las medialunas de manteca. Créame. Las de grasa son para la gente que tiene prisa.",
      "Verzeihen Sie, dass ich Sie störe, Fräulein. Ich sehe, Sie fotografieren das Café. Und ein Rat: die Medialunas mit Butter. Glauben Sie mir. Die mit Schmalz sind für Leute, die es eilig haben.",
      "Forgive me for bothering you, miss. I see you're taking photos of the café. And a piece of advice: the butter medialunas. Believe me. The lard ones are for people in a hurry.",
      "Συγγνώμη που σας ενοχλώ, δεσποινίς. Βλέπω ότι φωτογραφίζετε το καφέ. Και μια συμβουλή: τις μεδιαλούνας βουτύρου. Πιστέψτε με. Τις άλλες τις τρώνε όσοι βιάζονται."),
    Z("Se llamaba Aníbal. Había enseñado tango cuarenta años en una academia del barrio.",
      "Er hieß Aníbal. Er hatte vierzig Jahre lang in einer Tanzschule im Viertel Tango unterrichtet.",
      "His name was Aníbal. He had taught tango for forty years at a dance school in the neighbourhood.",
      "Τον έλεγαν Ανίμπαλ. Είχε διδάξει τάνγκο σαράντα χρόνια σε μια σχολή της γειτονιάς."),
    Z("—Ya no enseño. Ahora solo miro. Y opino, que es más fácil.",
      "Ich unterrichte nicht mehr. Jetzt schaue ich nur zu. Und sage meine Meinung, das ist einfacher.",
      "I don’t teach any more. Now I just watch. And give my opinion, which is easier.",
      "Δεν διδάσκω πια. Τώρα μόνο κοιτάζω. Και λέω τη γνώμη μου, που είναι πιο εύκολο."),
    Z("En otra mesa, dos amigos discutían de fútbol y se decían «vos», como se hablan los porteños entre amigos. Pero don Aníbal trataba a Lotte de usted, con una elegancia de otro siglo.",
      "An einem anderen Tisch stritten zwei Freunde über Fußball und sagten „vos“ zueinander, wie die Leute aus Buenos Aires unter Freunden sprechen. Aber Don Aníbal siezte Lotte, mit der Eleganz eines anderen Jahrhunderts.",
      "At another table, two friends were arguing about football and calling each other «vos», the way people from Buenos Aires talk among friends. But Don Aníbal addressed Lotte as «usted», with the elegance of another century.",
      "Σε ένα άλλο τραπέζι, δύο φίλοι συζητούσαν για ποδόσφαιρο και μιλούσαν με «vos», όπως μιλάνε μεταξύ φίλων οι κάτοικοι του Μπουένος Άιρες. Αλλά ο δον Ανίμπαλ μιλούσε στη Λότε στον πληθυντικό ευγενείας, με μια κομψότητα άλλου αιώνα."),
    Z("—¿Le gusta Buenos Aires?",
      "Gefällt Ihnen Buenos Aires?",
      "Do you like Buenos Aires?",
      "Σας αρέσει το Μπουένος Άιρες;"),
    Z("—Me encanta. Creo que es una ciudad elegante y un poco nostálgica. Y me parece que aquí la gente habla con mucha pasión. Hasta del tiempo.",
      "Ich liebe sie. Ich finde, sie ist eine elegante und etwas nostalgische Stadt. Und mir scheint, die Leute hier sprechen mit viel Leidenschaft. Sogar über das Wetter.",
      "I love it. I think it's an elegant city, and a little nostalgic. And it seems to me that people here talk with a lot of passion. Even about the weather.",
      "Μου αρέσει πολύ. Νομίζω ότι είναι μια κομψή και λίγο νοσταλγική πόλη. Και μου φαίνεται ότι εδώ ο κόσμος μιλάει με πολύ πάθος. Ακόμα και για τον καιρό."),
    Z("—Sobre todo del tiempo. ¿Y lo nostálgico? Es el tango, señorita. Lo enseñé cuarenta años. ¿Y a usted le gusta?",
      "Vor allem über das Wetter. Und das Nostalgische? Das ist der Tango, Fräulein. Ich habe ihn vierzig Jahre lang unterrichtet. Und gefällt er Ihnen?",
      "Especially about the weather. And the nostalgia? That's the tango, miss. I taught it for forty years. And do you like it?",
      "Κυρίως για τον καιρό. Και το νοσταλγικό; Είναι το τάνγκο, δεσποινίς. Το δίδαξα σαράντα χρόνια. Κι εσάς σας αρέσει;"),
    Z("—Me parece muy bonito, pero no creo que yo pueda bailarlo. Y además, creo que es un poco triste. Todas las canciones hablan de amores perdidos.",
      "Ich finde ihn sehr schön, aber ich glaube nicht, dass ich ihn tanzen kann. Und außerdem finde ich ihn ein bisschen traurig. Alle Lieder handeln von verlorener Liebe.",
      "I think it's lovely, but I don't think I could dance it. And besides, I think it's a bit sad. All the songs are about lost love.",
      "Μου φαίνεται πολύ όμορφο, αλλά δεν νομίζω ότι μπορώ να το χορέψω. Κι εξάλλου, νομίζω ότι είναι λίγο λυπητερό. Όλα τα τραγούδια μιλάνε για χαμένους έρωτες."),
    Z("Don Aníbal dejó el diario sobre la mesa, despacio, como quien deja una copa de cristal.",
      "Don Aníbal legte die Zeitung langsam auf den Tisch, wie jemand, der ein Kristallglas abstellt.",
      "Don Aníbal put the newspaper down on the table, slowly, like someone setting down a crystal glass.",
      "Ο δον Ανίμπαλ άφησε την εφημερίδα στο τραπέζι, αργά, σαν κάποιος που ακουμπάει ένα κρυστάλλινο ποτήρι."),
    Z("—No, no, no. No creo que el tango sea triste. Es nostalgia, que es otra cosa. La tristeza mira al suelo. La nostalgia mira lejos. Al río, por ejemplo.",
      "Nein, nein, nein. Ich glaube nicht, dass Tango traurig ist. Das ist Sehnsucht, und das ist etwas anderes. Die Traurigkeit schaut auf den Boden. Die Sehnsucht schaut in die Ferne. Auf den Fluss zum Beispiel.",
      "No, no, no. I don’t think tango is sad. It’s nostalgia, which is something else. Sadness looks at the ground. Nostalgia looks far away. At the river, for example.",
      "Όχι, όχι, όχι. Δεν νομίζω ότι το τάνγκο είναι λυπητερό. Είναι νοσταλγία, που είναι άλλο πράγμα. Η λύπη κοιτάζει το έδαφος. Η νοσταλγία κοιτάζει μακριά. Το ποτάμι, για παράδειγμα."),
    Z("—Esta mañana fui a ver el Río de la Plata. Me parece que no es un río. Es un mar. No se ve la otra orilla.",
      "Heute Morgen war ich am Río de la Plata. Mir scheint, das ist kein Fluss. Das ist ein Meer. Man sieht das andere Ufer nicht.",
      "This morning I went to see the Río de la Plata. It seems to me it isn’t a river. It’s a sea. You can’t see the other side.",
      "Σήμερα το πρωί πήγα να δω τον Ρίο ντε λα Πλάτα. Μου φαίνεται ότι δεν είναι ποτάμι. Είναι θάλασσα. Δεν φαίνεται η απέναντι όχθη."),
    Z("—Es el río más ancho del mundo. Del otro lado está Uruguay, pero no se ve nunca. Nosotros miramos hacia la ciudad, y el río no se ofende. Espera.",
      "Es ist der breiteste Fluss der Welt. Auf der anderen Seite liegt Uruguay, aber man sieht es nie. Wir schauen zur Stadt hin, und der Fluss ist nicht beleidigt. Er wartet.",
      "It’s the widest river in the world. Uruguay is on the other side, but you never see it. We look towards the city, and the river doesn’t take offence. It waits.",
      "Είναι το πιο φαρδύ ποτάμι του κόσμου. Από την άλλη μεριά είναι η Ουρουγουάη, αλλά δεν φαίνεται ποτέ. Εμείς κοιτάμε προς την πόλη, και το ποτάμι δεν θυμώνει. Περιμένει."),
    Z("—Y lo de bailar… Tengo dos pies izquierdos.",
      "Und was das Tanzen angeht … Ich habe zwei linke Füße.",
      "And as for dancing… I've got two left feet.",
      "Κι όσο για τον χορό… Έχω δύο αριστερά πόδια."),
    Z("—Todos tenemos dos pies izquierdos al principio. Yo enseñé a bailar a un dentista que no sabía ni caminar.",
      "Am Anfang haben wir alle zwei linke Füße. Ich habe einem Zahnarzt das Tanzen beigebracht, der nicht einmal gehen konnte.",
      "We all have two left feet at the start. I taught a dentist to dance who couldn't even walk.",
      "Όλοι έχουμε δύο αριστερά πόδια στην αρχή. Εγώ έμαθα να χορεύει έναν οδοντίατρο που δεν ήξερε ούτε να περπατάει."),
    Z("En ese momento llegó un mensaje de voz de Bram:",
      "In diesem Moment kam eine Sprachnachricht von Bram:",
      "At that moment a voice message arrived from Bram:",
      "Εκείνη τη στιγμή ήρθε ένα φωνητικό μήνυμα από τον Μπραμ:"),
    Z("—Lotte, ¿tango? ¿Me estás diciendo que bailas tango en vez de trabajar? ...Bueno. Si bailas, fotografía los zapatos.",
      "Lotte, Tango? Willst du mir sagen, dass du Tango tanzt, statt zu arbeiten? ... Na gut. Wenn du tanzt, fotografier die Schuhe.",
      "Lotte, tango? Are you telling me you’re dancing tango instead of working? ...Fine. If you dance, photograph the shoes.",
      "Λότε, τάνγκο; Μου λες ότι χορεύεις τάνγκο αντί να δουλεύεις; ...Καλά. Αν χορέψεις, φωτογράφισε τα παπούτσια."),
    Z("Don Aníbal sonrió, como si lo hubiera entendido todo.",
      "Don Aníbal lächelte, als hätte er alles verstanden.",
      "Don Aníbal smiled, as if he had understood everything.",
      "Ο δον Ανίμπαλ χαμογέλασε, σαν να τα είχε καταλάβει όλα."),
    Z("—Todo el mundo puede. Esta noche hay una milonga aquí a la vuelta. ¿Por qué no viene? Es en un club del barrio; una milonga es un baile de tango, para todos. Empieza a las once.",
      "Jeder kann es. Heute Abend gibt es eine Milonga gleich um die Ecke. Warum kommen Sie nicht? Sie ist in einem Klub im Viertel; eine Milonga ist ein Tangoabend, für alle. Sie fängt um elf an.",
      "Everyone can. Tonight there's a milonga just round the corner. Why don't you come? It's at a club in the neighbourhood; a milonga is a tango dance, open to everyone. It starts at eleven.",
      "Όλοι μπορούν. Απόψε έχει μιλόνγκα εδώ στη γωνία. Γιατί δεν έρχεστε; Είναι σε ένα κλαμπ της γειτονιάς· μιλόνγκα είναι μια βραδιά τάνγκο, για όλους. Αρχίζει στις έντεκα."),
    Z("—¿A las once de la noche?",
      "Um elf Uhr nachts?",
      "At eleven at night?",
      "Στις έντεκα το βράδυ;"),
    Z("—Temprano, ya sé. Pero yo soy un hombre mayor. Venga. Si no baila, mira. Y si mira, saca fotos. Creo que le va a gustar.",
      "Früh, ich weiß. Aber ich bin ein alter Mann. Kommen Sie. Wenn Sie nicht tanzen, schauen Sie zu. Und wenn Sie zuschauen, machen Sie Fotos. Ich glaube, es wird Ihnen gefallen.",
      "Early, I know. But I’m an old man. Come along. If you don’t dance, you watch. And if you watch, you take photos. I think you’ll like it.",
      "Νωρίς, το ξέρω. Αλλά εγώ είμαι ηλικιωμένος. Ελάτε. Αν δεν χορέψετε, θα κοιτάτε. Κι αν κοιτάτε, θα βγάζετε φωτογραφίες. Νομίζω ότι θα σας αρέσει."),
    Z("—Bueno, ¿por qué no? Pero creo que voy a mirar más que bailar.",
      "Na gut, warum nicht? Aber ich glaube, ich werde mehr zuschauen als tanzen.",
      "Well, why not? But I think I'll watch more than dance.",
      "Εντάξει, γιατί όχι; Αλλά νομίζω ότι θα κοιτάζω περισσότερο απ' ό,τι θα χορεύω."),
    Z("Cuando Lotte quiso pagar, don Aníbal levantó la mano. «En este café, la primera vez paga el que es de aquí.»",
      "Als Lotte bezahlen wollte, hob Don Aníbal die Hand. „In diesem Café zahlt beim ersten Mal der, der von hier ist.“",
      "When Lotte tried to pay, Don Aníbal raised his hand. ‘In this café, the first time, the one who’s from here pays.’",
      "Όταν η Λότε πήγε να πληρώσει, ο δον Ανίμπαλ σήκωσε το χέρι. «Σε αυτό το καφέ, την πρώτη φορά πληρώνει αυτός που είναι από εδώ»."),
    Z("Esa noche, en la milonga, Lotte miró mucho, como había dicho, e hizo cuarenta fotos de zapatos. Después don Aníbal le ofreció la mano, y ella bailó. A los tres minutos ya no pensaba en sus pies.",
      "An diesem Abend schaute Lotte in der Milonga viel zu, wie sie es gesagt hatte, und machte vierzig Fotos von Schuhen. Dann reichte ihr Don Aníbal die Hand, und sie tanzte. Nach drei Minuten dachte sie nicht mehr an ihre Füße.",
      "That night, at the milonga, Lotte watched a lot, as she had said, and took forty photos of shoes. Then Don Aníbal offered her his hand, and she danced. After three minutes she had stopped thinking about her feet.",
      "Εκείνο το βράδυ, στη μιλόνγκα, η Λότε κοίταξε πολύ, όπως είχε πει, κι έβγαλε σαράντα φωτογραφίες από παπούτσια. Μετά ο δον Ανίμπαλ της έδωσε το χέρι, κι εκείνη χόρεψε. Μετά από τρία λεπτά δεν σκεφτόταν πια τα πόδια της."),
    Z("En el cuaderno: «Palabra del lugar: medialuna. Media luna en el nombre, pero entera en la boca. Y otra más: milonga».",
      "Im Notizbuch: „Wort des Ortes: Medialuna. Ein halber Mond im Namen, aber ein ganzer im Mund. Und noch eins: Milonga.“",
      "In the notebook: ‘Word of the place: medialuna. Half a moon in the name, but a whole one in your mouth. And one more: milonga.’",
      "Στο σημειωματάριο: «Λέξη του τόπου: medialuna. Μισό φεγγάρι στο όνομα, αλλά ολόκληρο στο στόμα. Και άλλη μία: milonga»."),
    Z("Y a Oma Fenna: «Querida Oma: anoche bailé tango con un señor de ochenta y dos años. Él dice que no lo hice mal. Yo no creo que sea verdad, pero es muy amable. Te mando una foto de sus zapatos. Lotte».",
      "Und an Oma Fenna: „Liebe Oma, gestern Abend habe ich mit einem zweiundachtzigjährigen Herrn Tango getanzt. Er sagt, ich habe es nicht schlecht gemacht. Ich glaube nicht, dass das stimmt, aber er ist sehr freundlich. Ich schicke dir ein Foto von seinen Schuhen. Lotte.“",
      "And to Oma Fenna: ‘Dear Oma, last night I danced tango with an eighty-two-year-old gentleman. He says I didn’t do badly. I don’t think that’s true, but he’s very kind. I’m sending you a photo of his shoes. Lotte.’",
      "Και στην Όμα Φένα: «Αγαπημένη μου Όμα, χθες βράδυ χόρεψα τάνγκο με έναν κύριο ογδόντα δύο χρονών. Λέει ότι δεν τα πήγα άσχημα. Εγώ δεν νομίζω ότι είναι αλήθεια, αλλά είναι πολύ ευγενικός. Σου στέλνω μια φωτογραφία με τα παπούτσια του. Λότε».")
  ]));

  // ── Station 9 · restaurant ──────────────────────────────
  K.push(S(9, "restaurant", "Llevo seis meses viajando",
    { de: "April in El Calafate: Die Saison geht zu Ende, Lotte will bleiben — und hat ein Vorstellungsgespräch bei Doña Inés. Vorher: ein Gletscher, der donnert.",
      en: "April in El Calafate: the season is ending, Lotte wants to stay — and has a job interview with Doña Inés. Before that: a glacier that thunders.",
      el: "Απρίλιος στο Ελ Καλαφάτε: η σεζόν τελειώνει, η Λότε θέλει να μείνει — και έχει συνέντευξη για δουλειά με την κυρία Ινές. Πριν από αυτό: ένας παγετώνας που βροντά." },
  [
    Z("En abril, la Patagonia cambia de color. Los árboles se ponen rojos y amarillos, el viento sopla más frío y los turistas empiezan a irse.",
      "Im April wechselt Patagonien die Farbe. Die Bäume werden rot und gelb, der Wind weht kälter, und die Touristen fangen an abzureisen.",
      "In April, Patagonia changes colour. The trees turn red and yellow, the wind blows colder and the tourists begin to leave.",
      "Τον Απρίλιο η Παταγονία αλλάζει χρώμα. Τα δέντρα γίνονται κόκκινα και κίτρινα, ο αέρας φυσάει πιο κρύος και οι τουρίστες αρχίζουν να φεύγουν."),
    Z("Lotte llegó a El Calafate en un bus nocturno, con la Leica colgada del cuello y una mochila llena de ropa que ya no le servía: camisetas de Asunción, un sombrero de Oaxaca.",
      "Lotte kam mit einem Nachtbus in El Calafate an, die Leica um den Hals und einen Rucksack voller Kleidung, die ihr nichts mehr nützte: T-Shirts aus Asunción, ein Hut aus Oaxaca.",
      "Lotte arrived in El Calafate on a night bus, with the Leica round her neck and a rucksack full of clothes that were no use to her any more: T-shirts from Asunción, a hat from Oaxaca.",
      "Η Λότε έφτασε στο Ελ Καλαφάτε με νυχτερινό λεωφορείο, με τη Leica κρεμασμένη στον λαιμό και ένα σακίδιο γεμάτο ρούχα που δεν της χρησίμευαν πια: μπλουζάκια από την Ασουνσιόν, ένα καπέλο από την Οαχάκα."),
    Z("La primera mañana fue directamente al glaciar Perito Moreno. Desde las pasarelas lo vio entero: una pared de hielo azul, de más de cincuenta metros de alto, que entra en el lago Argentino como un barco gigante.",
      "Am ersten Morgen fuhr sie direkt zum Perito-Moreno-Gletscher. Von den Stegen aus sah sie ihn ganz: eine Wand aus blauem Eis, über fünfzig Meter hoch, die wie ein riesiges Schiff in den Lago Argentino hineinragt.",
      "On the first morning she went straight to the Perito Moreno glacier. From the walkways she saw all of it: a wall of blue ice, more than fifty metres high, pushing into Lake Argentino like a giant ship.",
      "Το πρώτο πρωί πήγε κατευθείαν στον παγετώνα Περίτο Μορένο. Από τις διαδρομές τον είδε ολόκληρο: έναν τοίχο από γαλάζιο πάγο, ψηλότερο από πενήντα μέτρα, που μπαίνει στη λίμνη Αρχεντίνο σαν ένα γιγάντιο καράβι."),
    Z("Nadie hablaba. Todos esperaban. De repente se oyó un trueno, y un bloque de hielo del tamaño de una casa cayó al agua.",
      "Niemand sprach. Alle warteten. Plötzlich hörte man einen Donner, und ein Eisblock so groß wie ein Haus stürzte ins Wasser.",
      "Nobody spoke. Everyone was waiting. Suddenly there was a sound like thunder, and a block of ice the size of a house fell into the water.",
      "Κανείς δεν μιλούσε. Όλοι περίμεναν. Ξαφνικά ακούστηκε μια βροντή, και ένα κομμάτι πάγου στο μέγεθος σπιτιού έπεσε στο νερό."),
    Z("—¡Ahí está! —gritó un niño, y todo el mundo aplaudió, como en el teatro.",
      "„Da!“, rief ein Kind, und alle klatschten, wie im Theater.",
      "“There it goes!” shouted a child, and everyone clapped, as if they were at the theatre.",
      "«Να το!» φώναξε ένα παιδί, και όλοι χειροκρότησαν, σαν στο θέατρο."),
    Z("Lotte no aplaudió. Estaba haciendo fotos. Treinta y ocho fotos en un minuto, y en ninguna se veía bien el bloque. Solo agua blanca.",
      "Lotte klatschte nicht. Sie fotografierte. Achtunddreißig Fotos in einer Minute, und auf keinem sah man den Block richtig. Nur weißes Wasser.",
      "Lotte didn't clap. She was taking pictures. Thirty-eight pictures in one minute, and in none of them could you see the block properly. Just white water.",
      "Η Λότε δεν χειροκρότησε. Έβγαζε φωτογραφίες. Τριάντα οκτώ φωτογραφίες σε ένα λεπτό, και σε καμία δεν φαινόταν καλά το κομμάτι. Μόνο άσπρο νερό."),
    Z("Esa noche, en el hostal, escuchó un mensaje de voz de Bram. Hablaba en holandés, como siempre, y preguntaba lo de siempre: dónde estaban las fotos del hielo.",
      "An diesem Abend hörte sie im Hostel eine Sprachnachricht von Bram. Er sprach Niederländisch, wie immer, und fragte, was er immer fragte: Wo die Fotos vom Eis blieben.",
      "That night, at the hostel, she listened to a voice message from Bram. He was speaking Dutch, as always, and asking what he always asked: where were the pictures of the ice?",
      "Εκείνο το βράδυ, στον ξενώνα, άκουσε ένα φωνητικό μήνυμα από τον Μπραμ. Μιλούσε ολλανδικά, όπως πάντα, και ρωτούσε τα ίδια με πάντα: πού ήταν οι φωτογραφίες του πάγου."),
    Z("Al día siguiente, en la puerta de un restaurante de la avenida, vio un cartel escrito a mano: «Se busca moza para fin de temporada. Con alojamiento. Preguntar por Inés.»",
      "Am nächsten Tag sah sie an der Tür eines Restaurants an der Hauptstraße ein handgeschriebenes Schild: „Bedienung für das Saisonende gesucht. Mit Unterkunft. Nach Inés fragen.“",
      "The next day, on the door of a restaurant on the main avenue, she saw a handwritten sign: “Waitress wanted for the end of the season. Accommodation included. Ask for Inés.”",
      "Την επόμενη μέρα, στην πόρτα ενός εστιατορίου στη λεωφόρο, είδε μια χειρόγραφη πινακίδα: «Ζητείται σερβιτόρα για το τέλος της σεζόν. Με διαμονή. Ρωτήστε για την Ινές.»"),
    Z("Lotte conocía la palabra «mesera». «Moza» era nueva. En Argentina, le explicó más tarde el cocinero, la mesera es la moza y el mesero es el mozo. Lotte la anotó enseguida.",
      "Lotte kannte das Wort „mesera“. „Moza“ war neu. In Argentinien, erklärte ihr später der Koch, heißt die Kellnerin „moza“ und der Kellner „mozo“. Lotte schrieb es sofort auf.",
      "Lotte knew the word “mesera”. “Moza” was new. In Argentina, the cook explained to her later, a waitress is a “moza” and a waiter is a “mozo”. Lotte wrote it down at once.",
      "Η Λότε ήξερε τη λέξη «mesera». Το «moza» ήταν καινούργιο. Στην Αργεντινή, της εξήγησε αργότερα ο μάγειρας, η σερβιτόρα λέγεται «moza» και ο σερβιτόρος «mozo». Η Λότε το σημείωσε αμέσως."),
    Z("El restaurante se llamaba La Lenga, como el árbol de la Patagonia. Olía a leña y a cordero. Detrás de la barra, una señora de pelo blanco y corto contaba servilletas.",
      "Das Restaurant hieß La Lenga, wie der Baum Patagoniens. Es roch nach Holzfeuer und Lamm. Hinter der Theke zählte eine Dame mit kurzen weißen Haaren Servietten.",
      "The restaurant was called La Lenga, after the Patagonian tree. It smelled of woodsmoke and lamb. Behind the bar, a lady with short white hair was counting napkins.",
      "Το εστιατόριο λεγόταν La Lenga, όπως το δέντρο της Παταγονίας. Μύριζε ξύλα και αρνί. Πίσω από τον πάγκο, μια κυρία με κοντά άσπρα μαλλιά μετρούσε χαρτοπετσέτες."),
    Z("—Buenas tardes. Me llamo Lotte de Vries. Vengo por el cartel; quería preguntar por el trabajo.",
      "„Guten Tag. Ich heiße Lotte de Vries. Ich komme wegen des Schildes; ich wollte nach der Stelle fragen.“",
      "“Good afternoon. My name's Lotte de Vries. I've come about the sign; I wanted to ask about the job.”",
      "«Καλησπέρα. Με λένε Λότε ντε Φρις. Έρχομαι για την πινακίδα· ήθελα να ρωτήσω για τη δουλειά.»"),
    Z("—Buenas tardes, Lotte. Siéntese, por favor. Cuénteme, ¿qué la trae a El Calafate? —Y antes de que Lotte pudiera contestar, añadió—: Soy Inés. La entrevista es corta: en este restaurante no tenemos tiempo para entrevistas largas.",
      "„Guten Tag, Lotte. Setzen Sie sich bitte. Erzählen Sie, was führt Sie nach El Calafate?“ Und bevor Lotte antworten konnte, fügte sie hinzu: „Ich bin Inés. Das Gespräch ist kurz: In diesem Restaurant haben wir keine Zeit für lange Gespräche.“",
      "“Good afternoon, Lotte. Please sit down. Tell me, what brings you to El Calafate?” And before Lotte could answer, she added: “I'm Inés. The interview is short: in this restaurant we have no time for long interviews.”",
      "«Καλησπέρα, Λότε. Καθίστε, παρακαλώ. Πείτε μου, τι σας φέρνει στο Ελ Καλαφάτε;» Και πριν προλάβει να απαντήσει η Λότε, πρόσθεσε: «Είμαι η Ινές. Η συνέντευξη είναι σύντομη: σε αυτό το εστιατόριο δεν έχουμε χρόνο για μεγάλες συνεντεύξεις.»"),
    Z("Doña Inés trataba de usted a todo el mundo: a los clientes, a los cocineros y, según el cocinero, también al gato.",
      "Doña Inés siezte alle: die Gäste, die Köche und, laut dem Koch, auch die Katze.",
      "Doña Inés addressed everyone formally: the customers, the cooks and, according to the cook, the cat as well.",
      "Η κυρία Ινές μιλούσε σε όλους στον πληθυντικό ευγενείας: στους πελάτες, στους μάγειρες και, σύμφωνα με τον μάγειρα, και στη γάτα."),
    Z("—Llevo seis meses viajando por Latinoamérica y saco fotos para un libro. Empecé en México, en octubre. Es un libro sobre el agua.",
      "„Ich reise seit sechs Monaten durch Lateinamerika und mache Fotos für ein Buch. Ich habe im Oktober in Mexiko angefangen. Es ist ein Buch über das Wasser.“",
      "“I've been travelling around Latin America for six months, taking photos for a book. I started in Mexico, in October. It's a book about water.”",
      "«Ταξιδεύω εδώ και έξι μήνες στη Λατινική Αμερική και βγάζω φωτογραφίες για ένα βιβλίο. Ξεκίνησα από το Μεξικό, τον Οκτώβριο. Είναι ένα βιβλίο για το νερό.»"),
    Z("—Qué interesante. ¿Y ha trabajado alguna vez en un restaurante?",
      "„Wie interessant. Und haben Sie schon einmal in einem Restaurant gearbeitet?“",
      "“How interesting. And have you ever worked in a restaurant?”",
      "«Τι ενδιαφέρον. Και έχετε δουλέψει ποτέ σε εστιατόριο;»"),
    Z("—Sí, he trabajado dos veranos de mesera en un café de Utrecht, cuando estudiaba fotografía. Sé llevar tres platos a la vez. Bueno, casi.",
      "„Ja, ich habe zwei Sommer lang als Kellnerin in einem Café in Utrecht gearbeitet, als ich Fotografie studiert habe. Ich kann drei Teller auf einmal tragen. Na ja, fast.“",
      "“Yes, I've worked two summers as a waitress in a café in Utrecht, when I was studying photography. I can carry three plates at once. Well, almost.”",
      "«Ναι, έχω δουλέψει δύο καλοκαίρια σερβιτόρα σε ένα καφέ στην Ουτρέχτη, όταν σπούδαζα φωτογραφία. Ξέρω να κουβαλάω τρία πιάτα μαζί. Σχεδόν, δηλαδή.»"),
    Z("—¿Casi?",
      "„Fast?“",
      "“Almost?”",
      "«Σχεδόν;»"),
    Z("—El tercero a veces llega con menos sopa.",
      "„Der dritte kommt manchmal mit weniger Suppe an.“",
      "“The third one sometimes arrives with less soup.”",
      "«Το τρίτο καμιά φορά φτάνει με λιγότερη σούπα.»"),
    Z("—Y dice que su libro es sobre el agua… Entonces ha venido al lugar correcto. Aquí tenemos agua de todos los tipos: hielo, lago, nieve y lluvia horizontal.",
      "„Und Ihr Buch handelt also vom Wasser … Dann sind Sie hier richtig. Hier haben wir Wasser in allen Sorten: Eis, See, Schnee und waagerechten Regen.“",
      "“And your book is about water, you say… Then you've come to the right place. We have every kind of water here: ice, lake, snow and horizontal rain.”",
      "«Και λέτε ότι το βιβλίο σας είναι για το νερό… Τότε ήρθατε στο σωστό μέρος. Εδώ έχουμε νερό όλων των ειδών: πάγο, λίμνη, χιόνι και οριζόντια βροχή.»"),
    Z("—¿Horizontal?",
      "„Waagerecht?“",
      "“Horizontal?”",
      "«Οριζόντια;»"),
    Z("—Cuando sopla el viento, aquí la lluvia no cae. Viaja.",
      "„Wenn hier der Wind weht, fällt der Regen nicht. Er reist.“",
      "“When the wind blows here, the rain doesn't fall. It travels.”",
      "«Όταν φυσάει ο αέρας εδώ, η βροχή δεν πέφτει. Ταξιδεύει.»"),
    Z("Lotte se rió, y doña Inés la miró por primera vez con interés. Después le dio la carta del restaurante. Era vieja, con fotos oscuras: un cordero que parecía un zapato, una trucha que parecía triste.",
      "Lotte lachte, und Doña Inés sah sie zum ersten Mal interessiert an. Dann gab sie ihr die Speisekarte des Restaurants. Sie war alt, mit dunklen Fotos: ein Lamm, das wie ein Schuh aussah, eine Forelle, die traurig aussah.",
      "Lotte laughed, and Doña Inés looked at her with interest for the first time. Then she handed her the restaurant's menu. It was old, with dark photos: a lamb that looked like a shoe, a trout that looked sad.",
      "Η Λότε γέλασε, και η κυρία Ινές την κοίταξε για πρώτη φορά με ενδιαφέρον. Μετά της έδωσε τον κατάλογο του εστιατορίου. Ήταν παλιός, με σκοτεινές φωτογραφίες: ένα αρνί που έμοιαζε με παπούτσι, μια πέστροφα που έμοιαζε λυπημένη."),
    Z("—Este es mi problema. La comida es buenísima, pero en las fotos parece horrible. La semana pasada un cliente pidió el cordero y me preguntó si era de cuero.",
      "„Das ist mein Problem. Das Essen ist hervorragend, aber auf den Fotos sieht es furchtbar aus. Letzte Woche hat ein Gast das Lamm bestellt und mich gefragt, ob es aus Leder ist.“",
      "“This is my problem. The food is excellent, but in the photos it looks awful. Last week a customer ordered the lamb and asked me if it was made of leather.”",
      "«Αυτό είναι το πρόβλημά μου. Το φαγητό είναι εξαιρετικό, αλλά στις φωτογραφίες φαίνεται απαίσιο. Την περασμένη εβδομάδα ένας πελάτης παρήγγειλε το αρνί και με ρώτησε αν ήταν από δέρμα.»"),
    Z("—Con la luz de esa ventana, por la mañana, el cordero podría parecer cordero —dijo Lotte, casi sin querer.",
      "„Mit dem Licht von diesem Fenster, am Vormittag, könnte das Lamm wie Lamm aussehen“, sagte Lotte, fast ohne es zu wollen.",
      "‘With the light from that window, in the morning, the lamb could look like lamb,’ said Lotte, almost without meaning to.",
      "«Με το φως από εκείνο το παράθυρο, το πρωί, το αρνί θα μπορούσε να μοιάζει με αρνί», είπε η Λότε, σχεδόν χωρίς να το θέλει."),
    Z("—Perfecto. Necesito a alguien hasta el fin de la temporada. ¿Podría además fotografiar los platos para la carta? Son cuatro semanas: por la mañana, fotos; por la noche, las mesas. Tiene una habitación arriba y la comida incluida.",
      "„Perfekt. Ich brauche jemanden bis zum Ende der Saison. Könnten Sie außerdem die Gerichte für die Speisekarte fotografieren? Es sind vier Wochen: vormittags Fotos, abends die Tische. Sie haben ein Zimmer oben, und das Essen ist inklusive.“",
      "“Perfect. I need someone until the end of the season. Could you also photograph the dishes for the menu? It's four weeks: photos in the morning, tables in the evening. You get a room upstairs and meals included.”",
      "«Τέλεια. Χρειάζομαι κάποιον ως το τέλος της σεζόν. Θα μπορούσατε επιπλέον να φωτογραφίσετε τα πιάτα για τον κατάλογο; Είναι τέσσερις εβδομάδες: το πρωί φωτογραφίες, το βράδυ τα τραπέζια. Έχετε ένα δωμάτιο επάνω και το φαγητό μαζί.»"),
    Z("—Con gusto. Puedo empezar mañana, si le parece bien.",
      "„Sehr gern. Ich kann morgen anfangen, wenn es Ihnen recht ist.“",
      "“With pleasure. I can start tomorrow, if that suits you.”",
      "«Με χαρά. Μπορώ να ξεκινήσω αύριο, αν σας βολεύει.»"),
    Z("«Con gusto»: le salió solo, sin pensar. El «vale» se había quedado en algún lugar entre Quito y la selva, y Lotte no lo extrañaba.",
      "„Con gusto“: Es kam ganz von allein, ohne Nachdenken. Das „vale“ war irgendwo zwischen Quito und dem Regenwald geblieben, und Lotte vermisste es nicht.",
      "“Con gusto”: it came out on its own, without thinking. “Vale” had stayed behind somewhere between Quito and the rainforest, and Lotte didn't miss it.",
      "«Con gusto»: της βγήκε μόνο του, χωρίς σκέψη. Το «vale» είχε μείνει κάπου ανάμεσα στο Κίτο και τη ζούγκλα, και στη Λότε δεν έλειπε καθόλου."),
    Z("—Mañana a las nueve, entonces.",
      "„Dann morgen um neun.“",
      "“Tomorrow at nine, then.”",
      "«Αύριο στις εννιά, λοιπόν.»"),
    Z("—Ay, mañana a las nueve tengo cita con el glaciar. ¿Puedo empezar a las once?",
      "„Oh, morgen um neun habe ich einen Termin mit dem Gletscher. Kann ich um elf anfangen?“",
      "“Oh, tomorrow at nine I have an appointment with the glacier. Can I start at eleven?”",
      "«Αχ, αύριο στις εννιά έχω ραντεβού με τον παγετώνα. Μπορώ να ξεκινήσω στις έντεκα;»"),
    Z("—Ah, el glaciar. Está bien. El glaciar lleva miles de años trabajando aquí. Tiene más antigüedad que yo.",
      "„Ah, der Gletscher. In Ordnung. Der Gletscher arbeitet hier schon seit Tausenden von Jahren. Er ist länger im Betrieb als ich.“",
      "“Ah, the glacier. All right. The glacier has been working here for thousands of years. It has more seniority than I do.”",
      "«Α, ο παγετώνας. Εντάξει. Ο παγετώνας δουλεύει σε αυτό το μέρος εδώ και χιλιάδες χρόνια. Έχει περισσότερη προϋπηρεσία από μένα.»"),
    Z("Antes de despedirse, doña Inés le puso en la mano un frasco pequeño de mermelada oscura.",
      "Bevor sie sich verabschiedeten, drückte Doña Inés ihr ein kleines Glas dunkler Marmelade in die Hand.",
      "Before they said goodbye, Doña Inés put a small jar of dark jam into her hand.",
      "Πριν χαιρετηθούν, η κυρία Ινές της έβαλε στο χέρι ένα μικρό βάζο με σκούρα μαρμελάδα."),
    Z("—Es de calafate, la fruta que le da el nombre al pueblo. Dicen que quien come calafate vuelve a la Patagonia.",
      "„Sie ist aus Calafate, der Beere, nach der der Ort heißt. Man sagt: Wer Calafate isst, kommt nach Patagonien zurück.“",
      "“It's calafate, the berry the town is named after. They say whoever eats calafate comes back to Patagonia.”",
      "«Είναι από καλαφάτε, το φρούτο που έδωσε το όνομά του στην πόλη. Λένε ότι όποιος τρώει καλαφάτε, επιστρέφει στην Παταγονία.»"),
    Z("—¿Y es verdad?",
      "„Und stimmt das?“",
      "“And is it true?”",
      "«Και είναι αλήθεια;»"),
    Z("—Yo lo probé hace cuarenta años. Vine de Buenos Aires para un verano, y aquí sigo.",
      "„Ich habe es vor vierzig Jahren probiert. Ich kam aus Buenos Aires für einen Sommer — und bin immer noch hier.“",
      "“I tried it forty years ago. I came from Buenos Aires for one summer, and I'm still here.”",
      "«Εγώ το δοκίμασα πριν από σαράντα χρόνια. Ήρθα από το Μπουένος Άιρες για ένα καλοκαίρι, και είμαι ακόμα εδώ.»"),
    Z("Esa noche Lotte escribió en su cuaderno la palabra del lugar: calafate. Y debajo: «Quien lo come, vuelve. Cuidado.»",
      "An diesem Abend schrieb Lotte das Wort des Ortes in ihr Notizbuch: calafate. Und darunter: „Wer sie isst, kommt zurück. Vorsicht.“",
      "That night Lotte wrote the word of the place in her notebook: calafate. And underneath: “Whoever eats it comes back. Careful.”",
      "Εκείνο το βράδυ η Λότε έγραψε στο σημειωματάριό της τη λέξη του τόπου: calafate. Και από κάτω: «Όποιος το τρώει, επιστρέφει. Προσοχή.»"),
    Z("Y en una postal para Oma Fenna: «Querida Oma: tengo trabajo en un restaurante cerca de un glaciar. Llevo seis meses viajando y es la primera vez que me pagan por llevar sopa. No te preocupes: el tercer plato ya llega casi lleno.»",
      "Und auf eine Postkarte für Oma Fenna: „Liebe Oma, ich habe Arbeit in einem Restaurant in der Nähe eines Gletschers. Ich bin seit sechs Monaten unterwegs, und zum ersten Mal werde ich dafür bezahlt, Suppe zu tragen. Keine Sorge: Der dritte Teller kommt schon fast voll an.“",
      "And on a postcard for Oma Fenna: “Dear Oma, I've got a job in a restaurant near a glacier. I've been travelling for six months, and it's the first time anyone has paid me to carry soup. Don't worry: the third plate already arrives almost full.”",
      "Και σε μια κάρτα για την Όμα Φένα: «Αγαπημένη μου γιαγιά, έχω δουλειά σε ένα εστιατόριο κοντά σε έναν παγετώνα. Ταξιδεύω εδώ και έξι μήνες και είναι η πρώτη φορά που με πληρώνουν για να κουβαλάω σούπα. Μην ανησυχείς: το τρίτο πιάτο φτάνει πια σχεδόν γεμάτο.»")
  ]));

  // ── Station 10 · wegbeschreibung ──────────────────────────────
  K.push(S(10, "wegbeschreibung", "El río manda",
    { de: "Juli in Canaima, mitten in der Regenzeit: Der Pemón-Führer Ramón erklärt den Weg zum Salto Ángel — Einbaum, Urwald, Aussichtspunkt. Dann steigt in der Nacht der Fluss.",
      en: "July in Canaima, in the middle of the rainy season: the Pemón guide Ramón explains the way to Angel Falls — dugout canoe, forest, viewpoint. Then, overnight, the river rises.",
      el: "Ιούλιος στην Καναΐμα, στην καρδιά της εποχής των βροχών: ο οδηγός Ραμόν, από τον λαό Πεμόν, εξηγεί τη διαδρομή ως τον Καταρράκτη Άντζελ — μονόξυλο, ζούγκλα, παρατηρητήριο. Ύστερα, μέσα στη νύχτα, το ποτάμι φουσκώνει." },
  [
    Z("En julio, en Canaima, llueve todos los días. Por eso Lotte había venido en julio: en la temporada de lluvias, el Salto Ángel tiene más agua que nunca.",
      "Im Juli regnet es in Canaima jeden Tag. Genau deshalb war Lotte im Juli gekommen: In der Regenzeit führt der Salto Ángel mehr Wasser als je sonst.",
      "In July it rains every day in Canaima. That was exactly why Lotte had come in July: in the rainy season, Angel Falls has more water than ever.",
      "Τον Ιούλιο στην Καναΐμα βρέχει κάθε μέρα. Γι' αυτό ακριβώς είχε έρθει η Λότε τον Ιούλιο: την εποχή των βροχών, ο Καταρράκτης Άντζελ έχει περισσότερο νερό από ποτέ."),
    Z("Desde la avioneta vio los tepuyes por primera vez: montañas planas como mesas gigantes, con paredes verticales y la cabeza entre las nubes.",
      "Aus dem kleinen Flugzeug sah sie zum ersten Mal die Tepuis: flache Berge wie riesige Tische, mit senkrechten Wänden und dem Kopf in den Wolken.",
      "From the light aircraft she saw the tepuis for the first time: flat mountains like giant tables, with sheer walls and their heads in the clouds.",
      "Από το μικρό αεροπλάνο είδε για πρώτη φορά τα τεπούι: επίπεδα βουνά σαν γιγάντια τραπέζια, με κάθετα τοιχώματα και το κεφάλι μέσα στα σύννεφα."),
    Z("En la pista de tierra la esperaba el guía. Se llamaba Ramón. Era pemón, del pueblo indígena de esta tierra, y hablaba despacio, como quien tiene todo el tiempo del mundo y no lo piensa regalar.",
      "Auf der Sandpiste wartete der Führer auf sie. Er hieß Ramón. Er war ein Pemón, vom indigenen Volk dieses Landes, und er sprach langsam, wie jemand, der alle Zeit der Welt hat und nicht vorhat, sie zu verschenken.",
      "On the dirt airstrip the guide was waiting for her. His name was Ramón. He was Pemón, from the indigenous people of this land, and he spoke slowly, like someone who has all the time in the world and has no intention of giving it away.",
      "Στον χωμάτινο διάδρομο την περίμενε ο οδηγός. Τον έλεγαν Ραμόν. Ήταν Πεμόν, από τον αυτόχθονα λαό αυτής της γης, και μιλούσε αργά, σαν κάποιος που έχει όλο τον χρόνο του κόσμου και δεν σκοπεύει να τον χαρίσει."),
    Z("—¡Bienvenida a Canaima! Soy Ramón. Mañana vamos al Kerepakupai Merú, el Salto Ángel. Y aquí todos nos tuteamos, ¿sí?",
      "Willkommen in Canaima! Ich bin Ramón. Morgen fahren wir zum Kerepakupai Merú, dem Salto Ángel. Und hier duzen wir uns alle, ja?",
      "Welcome to Canaima! I'm Ramón. Tomorrow we're going to Kerepakupai Merú, Angel Falls. And here we're all on first-name terms, all right?",
      "Καλώς ήρθες στην Καναΐμα! Είμαι ο Ραμόν. Αύριο πάμε στο Κερεπακουπάι Μερού, τον Καταρράκτη Άντζελ. Κι εδώ όλοι μιλάμε στον ενικό, εντάξει;"),
    Z("—¡Qué emoción! ¿Y cómo se llega al mirador?",
      "Wie aufregend! Und wie kommt man zum Aussichtspunkt?",
      "How exciting! And how do you get to the viewpoint?",
      "Τι ωραία, ανυπομονώ! Και πώς πάει κανείς στο παρατηρητήριο;"),
    Z("—Primero subimos el río en curiara, unas cuatro horas. Después caminamos una hora por la selva. La curiara es nuestra canoa, larga, hecha de un solo tronco: subimos por el Carrao y después por el Churún, y caminamos desde la isla Ratoncito hasta el mirador Laime.",
      "Zuerst fahren wir mit der Curiara den Fluss hinauf, etwa vier Stunden. Danach laufen wir eine Stunde durch den Urwald. Die Curiara ist unser Kanu, lang, aus einem einzigen Stamm gemacht: Wir fahren den Carrao und dann den Churún hinauf und laufen von der Insel Ratoncito bis zum Aussichtspunkt Laime.",
      "First we go up the river by curiara, about four hours. Then we walk for an hour through the jungle. The curiara is our canoe, long, made from a single trunk: we go up the Carrao and then the Churún, and we walk from Ratoncito island to the Laime viewpoint.",
      "Πρώτα ανεβαίνουμε το ποτάμι με την κουριάρα, περίπου τέσσερις ώρες. Μετά περπατάμε μία ώρα μέσα στη ζούγκλα. Η κουριάρα είναι το κανό μας, μακρύ, φτιαγμένο από έναν μόνο κορμό: ανεβαίνουμε τον Καράο και μετά τον Τσουρούν, και περπατάμε από το νησί Ρατονσίτο ως το παρατηρητήριο Λάιμε."),
    Z("—O sea, dices que primero vamos en curiara y luego caminamos una hora.",
      "Du sagst also, dass wir zuerst mit der Curiara fahren und dann eine Stunde laufen.",
      "So you're saying we go by curiara first and then walk for an hour.",
      "Δηλαδή λες ότι πρώτα πάμε με την κουριάρα και μετά περπατάμε μία ώρα."),
    Z("—Exacto. Pero el río viene muy fuerte y tardamos más: salimos a las cinco, no a las ocho.",
      "Genau. Aber der Fluss führt viel Wasser, und wir brauchen länger: Wir brechen um fünf auf, nicht um acht.",
      "Exactly. But the river's running very strong and it takes us longer: we leave at five, not at eight.",
      "Ακριβώς. Αλλά το ποτάμι κατεβαίνει πολύ δυνατό κι αργούμε περισσότερο: φεύγουμε στις πέντε, όχι στις οχτώ."),
    Z("—Entendido. Les digo a los demás que salimos a las cinco.",
      "Verstanden. Ich sage den anderen, dass wir um fünf losfahren.",
      "Got it. I'll tell the others we leave at five.",
      "Κατάλαβα. Θα πω στους άλλους ότι φεύγουμε στις πέντε."),
    Z("Los demás esperaban en la posada: dos hermanas de Caracas y un señor canadiense con un sombrero enorme. Las dos hermanas se llamaban María. Eso era un poco complicado.",
      "Die anderen warteten in der Herberge: zwei Schwestern aus Caracas und ein kanadischer Herr mit einem riesigen Hut. Beide Schwestern hießen María. Das war etwas kompliziert.",
      "The others were waiting at the lodge: two sisters from Caracas and a Canadian gentleman with an enormous hat. Both sisters were called María. That was a little complicated.",
      "Οι άλλοι περίμεναν στον ξενώνα: δύο αδερφές από το Καράκας κι ένας Καναδός κύριος με ένα τεράστιο καπέλο. Και οι δύο αδερφές λέγονταν Μαρία. Αυτό ήταν λίγο περίπλοκο."),
    Z("—Ramón dice que salimos a las cinco, no a las ocho —les dijo Lotte—. Me dijo que el río viene muy fuerte.",
      "„Ramón sagt, dass wir um fünf aufbrechen, nicht um acht“, sagte Lotte zu ihnen. „Er hat mir gesagt, dass der Fluss sehr viel Wasser führt.“",
      "“Ramón says we leave at five, not at eight,” Lotte told them. “He told me the river is running very strong.”",
      "«Ο Ραμόν λέει ότι φεύγουμε στις πέντε, όχι στις οχτώ», τους είπε η Λότε. «Μου είπε ότι το ποτάμι κατεβαίνει πολύ δυνατό.»"),
    Z("Por la noche, Ramón les dio las últimas instrucciones: —Siéntense en el centro de la curiara y no se pongan de pie. Sigan siempre el sendero y no toquen las hormigas grandes. Y si se mojan, no se preocupen: se van a mojar.",
      "Am Abend gab Ramón ihnen die letzten Anweisungen: „Setzt euch in die Mitte der Curiara und steht nicht auf. Bleibt immer auf dem Pfad und fasst die großen Ameisen nicht an. Und wenn ihr nass werdet, macht euch keine Sorgen: Ihr werdet nass.“",
      "That evening Ramón gave them their last instructions: “Sit in the middle of the curiara and don't stand up. Always stay on the path and don't touch the big ants. And if you get wet, don't worry: you will get wet.”",
      "Το βράδυ ο Ραμόν τους έδωσε τις τελευταίες οδηγίες: «Καθίστε στη μέση της κουριάρας και μη σηκωθείτε όρθιοι. Ακολουθείτε πάντα το μονοπάτι και μην αγγίζετε τα μεγάλα μυρμήγκια. Κι αν βραχείτε, μην ανησυχείτε: θα βραχείτε.»"),
    Z("Lotte lo escribió todo en el cuaderno. Después grabó un mensaje de voz para Bram, y sin darse cuenta lo grabó en español:",
      "Lotte schrieb alles ins Notizbuch. Dann nahm sie eine Sprachnachricht für Bram auf — und merkte gar nicht, dass sie sie auf Spanisch aufnahm:",
      "Lotte wrote it all down in her notebook. Then she recorded a voice message for Bram, and without realising it she recorded it in Spanish:",
      "Η Λότε τα έγραψε όλα στο σημειωματάριο. Ύστερα ηχογράφησε ένα φωνητικό μήνυμα για τον Μπραμ, και χωρίς να το καταλάβει, το ηχογράφησε στα ισπανικά:"),
    Z("—Bram, el guía dice que salimos a las cinco y que vamos cuatro horas en curiara. Me dijo que me siente en el centro. Y también me dijo que las fotos llegan cuando el salto quiere, no cuando quiere el editor.",
      "„Bram, der Führer sagt, dass wir um fünf aufbrechen und vier Stunden mit der Curiara fahren. Er hat mir gesagt, ich soll mich in die Mitte setzen. Und er hat mir auch gesagt, dass die Fotos kommen, wann der Wasserfall will — nicht, wann der Lektor will.“",
      "“Bram, the guide says we leave at five and spend four hours in the curiara. He told me to sit in the middle. And he also told me that the pictures come when the falls want, not when the editor wants.”",
      "«Μπραμ, ο οδηγός λέει ότι ξεκινάμε στις πέντε και ότι πάμε τέσσερις ώρες με την κουριάρα. Μου είπε να κάτσω στη μέση. Και μου είπε επίσης ότι οι φωτογραφίες έρχονται όταν θέλει ο καταρράκτης, όχι όταν θέλει ο επιμελητής.»"),
    Z("Esa noche llovió como Lotte nunca había visto llover. No eran gotas: era un río que caía del cielo.",
      "In dieser Nacht regnete es, wie Lotte es noch nie gesehen hatte. Das waren keine Tropfen: Das war ein Fluss, der vom Himmel fiel.",
      "That night it rained as Lotte had never seen it rain. It wasn't drops: it was a river falling from the sky.",
      "Εκείνη τη νύχτα έβρεξε όπως η Λότε δεν είχε δει ποτέ να βρέχει. Δεν ήταν σταγόνες: ήταν ένα ποτάμι που έπεφτε από τον ουρανό."),
    Z("A las cinco menos cuarto, Ramón ya estaba en la orilla, mirando el agua. Había subido todavía más. Corría marrón y rápida, y llevaba ramas.",
      "Um Viertel vor fünf stand Ramón schon am Ufer und sah aufs Wasser. Es war noch weiter gestiegen. Es floss braun und schnell und trug Äste mit sich.",
      "At a quarter to five Ramón was already on the bank, watching the water. It had risen even further. It was running brown and fast, and carrying branches.",
      "Στις πέντε παρά τέταρτο ο Ραμόν ήταν ήδη στην όχθη και κοίταζε το νερό. Είχε ανέβει κι άλλο. Κυλούσε καφέ και γρήγορο, και παρέσερνε κλαδιά."),
    Z("—Otro cambio de planes —dijo—. El río está muy alto en el raudal Mayupa. Es peligroso pasar por ahí con gente en la curiara.",
      "„Noch eine Planänderung“, sagte er. „Der Fluss steht an der Stromschnelle Mayupa sehr hoch. Es ist gefährlich, dort mit Leuten in der Curiara durchzufahren.“",
      "“Another change of plans,” he said. “The river is very high at the Mayupa rapids. It's dangerous to go through there with people in the curiara.”",
      "«Κι άλλη αλλαγή σχεδίων», είπε. «Το ποτάμι είναι πολύ ψηλά στα ορμητικά νερά της Μαγιούπα. Είναι επικίνδυνο να περάσουμε από εκεί με ανθρώπους μέσα στην κουριάρα.»"),
    Z("—¿Entonces no vamos? —preguntó una de las Marías.",
      "„Dann fahren wir also nicht?“, fragte eine der beiden Marías.",
      "“So we're not going?” asked one of the Marías.",
      "«Δηλαδή δεν πάμε;» ρώτησε η μία από τις Μαρίες."),
    Z("—Sí vamos, pero distinto. En el raudal ustedes se bajan y caminan por la orilla media hora. Mi primo sube la curiara vacía. Después, todos adentro otra vez.",
      "„Doch, wir fahren, aber anders. An der Stromschnelle steigt ihr aus und geht eine halbe Stunde am Ufer entlang. Mein Cousin bringt die Curiara leer hinauf. Danach steigen alle wieder ein.“",
      "“Yes, we're going, but differently. At the rapids you get out and walk along the bank for half an hour. My cousin takes the curiara up empty. After that, everyone back in.”",
      "«Πάμε, αλλά αλλιώς. Στα ορμητικά νερά κατεβαίνετε και περπατάτε στην όχθη μισή ώρα. Ο ξάδερφός μου ανεβάζει την κουριάρα άδεια. Μετά, όλοι πάλι μέσα.»"),
    Z("—Lleven el impermeable puesto y las cámaras en bolsas de plástico. Y tú, Lotte, guarda bien esa cámara vieja. Si se te cae al río, se va al Orinoco.",
      "„Lasst die Regenjacken an und packt die Kameras in Plastiktüten. Und du, Lotte, pass gut auf diese alte Kamera auf. Wenn sie dir in den Fluss fällt, schwimmt sie bis zum Orinoco.“",
      "“Keep your raincoats on and your cameras in plastic bags. And you, Lotte, look after that old camera. If you drop it in the river, it'll end up in the Orinoco.”",
      "«Κρατήστε τα αδιάβροχα φορεμένα και βάλτε τις κάμερες σε πλαστικές σακούλες. Κι εσύ, Λότε, φύλαξε καλά αυτή την παλιά κάμερα. Αν σου πέσει στο ποτάμι, θα καταλήξει στον Ορινόκο.»"),
    Z("Otra vez en la curiara, el río se calmó. Los tepuyes pasaban a los dos lados, y de sus paredes caían cascadas pequeñas que no tenían nombre.",
      "Wieder in der Curiara wurde der Fluss ruhig. Die Tepuis zogen auf beiden Seiten vorbei, und von ihren Wänden fielen kleine Wasserfälle, die keinen Namen hatten.",
      "Back in the curiara, the river grew calm. The tepuis slid past on both sides, and small waterfalls with no names tumbled from their walls.",
      "Πάλι μέσα στην κουριάρα, το ποτάμι ηρέμησε. Τα τεπούι περνούσαν κι από τις δύο πλευρές, και από τα τοιχώματά τους έπεφταν μικροί καταρράκτες που δεν είχαν όνομα."),
    Z("Llegaron a la isla Ratoncito al mediodía y comieron arepas con queso que la esposa de Ramón había preparado a las cuatro de la mañana. Estaban frías. Eran las mejores arepas del mundo.",
      "Mittags kamen sie auf der Insel Ratoncito an und aßen Arepas mit Käse, die Ramóns Frau um vier Uhr morgens gemacht hatte. Sie waren kalt. Es waren die besten Arepas der Welt.",
      "They reached Ratoncito island at midday and ate arepas with cheese that Ramón's wife had made at four in the morning. They were cold. They were the best arepas in the world.",
      "Έφτασαν στο νησί Ρατονσίτο το μεσημέρι και έφαγαν αρέπας με τυρί που είχε φτιάξει η γυναίκα του Ραμόν στις τέσσερις τα ξημερώματα. Ήταν κρύες. Ήταν οι καλύτερες αρέπας του κόσμου."),
    Z("—¡Qué chévere! —dijo una de las Marías con la boca llena. Lotte ya conocía la palabra de Quito, pero la otra María le explicó que en Venezuela es casi un idioma entero: —Chévere es bueno, bonito, algo que te gusta. Todo lo bueno de Venezuela es chévere.",
      "„Wie chévere!“, sagte eine der Marías mit vollem Mund. Lotte kannte das Wort schon aus Quito, aber die andere María erklärte ihr, dass es in Venezuela fast eine ganze Sprache ist: „Chévere ist gut, schön, etwas, das dir gefällt. Alles Gute in Venezuela ist chévere.“",
      "“¡Qué chévere!” said one of the Marías with her mouth full. Lotte already knew the word from Quito, but the other María explained that in Venezuela it's almost a whole language: “Chévere is good, lovely, something you like. Everything good in Venezuela is chévere.”",
      "«Τι chévere!» είπε η μία Μαρία με το στόμα γεμάτο. Η Λότε ήξερε ήδη τη λέξη από το Κίτο, αλλά η άλλη Μαρία της εξήγησε ότι στη Βενεζουέλα είναι σχεδόν μια ολόκληρη γλώσσα: «Chévere θα πει καλό, ωραίο, κάτι που σου αρέσει. Ό,τι καλό έχει η Βενεζουέλα είναι chévere.»"),
    Z("En el mirador Laime no había nada. Solo una nube blanca y gruesa, como una pared de algodón.",
      "Am Aussichtspunkt Laime war nichts. Nur eine dicke weiße Wolke, wie eine Wand aus Watte.",
      "At the Laime viewpoint there was nothing. Just a thick white cloud, like a wall of cotton wool.",
      "Στο παρατηρητήριο Λάιμε δεν υπήρχε τίποτα. Μόνο ένα πυκνό άσπρο σύννεφο, σαν τοίχος από βαμβάκι."),
    Z("—¿Dónde está el salto? —preguntó Lotte.",
      "„Wo ist der Wasserfall?“, fragte Lotte.",
      "“Where are the falls?” asked Lotte.",
      "«Πού είναι ο καταρράκτης;» ρώτησε η Λότε."),
    Z("—Ahí, detrás. Espera. Nosotros lo llamamos Kerepakupai Merú: el salto del lugar más profundo. Y el salto se muestra cuando quiere.",
      "„Da, dahinter. Warte. Wir nennen ihn Kerepakupai Merú: den Wasserfall vom tiefsten Ort. Und der Wasserfall zeigt sich, wann er will.“",
      "“There, behind it. Wait. We call it Kerepakupai Merú: the waterfall of the deepest place. And the falls show themselves when they want to.”",
      "«Εκεί, από πίσω. Περίμενε. Εμείς τον λέμε Κερεπακουπάι Μερού: ο καταρράκτης του πιο βαθιού τόπου. Και ο καταρράκτης φανερώνεται όταν θέλει.»"),
    Z("Esperaron veinte minutos. El canadiense se comió una galleta. Una de las Marías casi se durmió de pie. Lotte no levantó la cámara: Ramón le había dicho que esperara, y ella esperó.",
      "Sie warteten zwanzig Minuten. Der Kanadier aß einen Keks. Eine der Marías schlief im Stehen fast ein. Lotte hob die Kamera nicht: Ramón hatte ihr gesagt, sie solle warten, und sie wartete.",
      "They waited twenty minutes. The Canadian ate a biscuit. One of the Marías almost fell asleep standing up. Lotte didn't raise her camera: Ramón had told her to wait, and she waited.",
      "Περίμεναν είκοσι λεπτά. Ο Καναδός έφαγε ένα μπισκότο. Η μία Μαρία παραλίγο να αποκοιμηθεί όρθια. Η Λότε δεν σήκωσε την κάμερα: ο Ραμόν της είχε πει να περιμένει, και περίμενε."),
    Z("Y entonces la nube se abrió. Desde lo alto del Auyantepuy, a casi mil metros, el agua caía, y caía, y seguía cayendo. A mitad de camino ya no era agua: era humo blanco.",
      "Und dann öffnete sich die Wolke. Von der Höhe des Auyantepui, fast tausend Meter hoch, fiel das Wasser, und fiel, und fiel immer weiter. Auf halbem Weg war es kein Wasser mehr: Es war weißer Rauch.",
      "And then the cloud opened. From the top of Auyantepui, almost a thousand metres up, the water fell, and fell, and kept on falling. Halfway down it wasn't water any more: it was white smoke.",
      "Και τότε το σύννεφο άνοιξε. Από την κορυφή του Αουγιαντεπούι, σχεδόν χίλια μέτρα ψηλά, το νερό έπεφτε, κι έπεφτε, και συνέχιζε να πέφτει. Στη μέση της διαδρομής δεν ήταν πια νερό: ήταν άσπρος καπνός."),
    Z("Lotte hizo una sola foto. Después bajó la cámara y miró con los ojos, que no tienen zoom, pero tienen memoria.",
      "Lotte machte ein einziges Foto. Dann ließ sie die Kamera sinken und schaute mit den Augen, die keinen Zoom haben, aber ein Gedächtnis.",
      "Lotte took a single photo. Then she lowered the camera and looked with her eyes, which have no zoom, but do have a memory.",
      "Η Λότε έβγαλε μία μόνο φωτογραφία. Ύστερα κατέβασε την κάμερα και κοίταξε με τα μάτια, που δεν έχουν ζουμ, αλλά έχουν μνήμη."),
    Z("—¿No vas a hacer más fotos? —preguntó Ramón.",
      "„Machst du keine Fotos mehr?“, fragte Ramón.",
      "“Aren't you going to take any more pictures?” asked Ramón.",
      "«Δεν θα βγάλεις άλλες φωτογραφίες;» ρώτησε ο Ραμόν."),
    Z("—No. Me dijiste que el salto se muestra cuando quiere. Ya se mostró. No quiero ser maleducada.",
      "„Nein. Du hast mir gesagt, dass der Wasserfall sich zeigt, wann er will. Er hat sich gezeigt. Ich will nicht unhöflich sein.“",
      "“No. You told me the falls show themselves when they want to. They've shown themselves. I don't want to be rude.”",
      "«Όχι. Μου είπες ότι ο καταρράκτης φανερώνεται όταν θέλει. Φανερώθηκε. Δεν θέλω να είμαι αγενής.»"),
    Z("Ramón se rió. Después le pidió la Leica y le hizo una foto a ella: empapada, con el pelo rojo pegado a la cara, riéndose dentro de la nube del salto.",
      "Ramón lachte. Dann bat er um die Leica und machte ein Foto von ihr: klatschnass, die roten Haare im Gesicht klebend, lachend mitten in der Wolke des Wasserfalls.",
      "Ramón laughed. Then he asked for the Leica and took a photo of her: soaked through, her red hair stuck to her face, laughing inside the cloud of the falls.",
      "Ο Ραμόν γέλασε. Ύστερα της ζήτησε τη Leica και της έβγαλε μια φωτογραφία: μούσκεμα, με τα κόκκινα μαλλιά κολλημένα στο πρόσωπο, να γελάει μέσα στο σύννεφο του καταρράκτη."),
    Z("Esa noche, en el cuaderno, la palabra del lugar: chévere. Y debajo: «El río manda. Ramón traduce.»",
      "An diesem Abend, im Notizbuch, das Wort des Ortes: chévere. Und darunter: „Der Fluss bestimmt. Ramón übersetzt.“",
      "That night, in the notebook, the word of the place: chévere. And underneath: “The river is in charge. Ramón translates.”",
      "Εκείνο το βράδυ, στο σημειωματάριο, η λέξη του τόπου: chévere. Και από κάτω: «Το ποτάμι διατάζει. Ο Ραμόν μεταφράζει.»"),
    Z("Y para Oma Fenna: «Querida Oma: hoy vi la cascada más alta del mundo. El guía me dijo que no fuera impaciente, y le hice caso. Tú me lo dices desde hace treinta y un años. Hoy, por fin, lo entendí.»",
      "Und für Oma Fenna: „Liebe Oma, heute habe ich den höchsten Wasserfall der Welt gesehen. Der Führer hat mir gesagt, ich soll nicht ungeduldig sein, und ich habe auf ihn gehört. Das sagst du mir seit einunddreißig Jahren. Heute habe ich es endlich verstanden.“",
      "And for Oma Fenna: “Dear Oma, today I saw the highest waterfall in the world. The guide told me not to be impatient, and I listened to him. You've been telling me that for thirty-one years. Today, at last, I understood it.”",
      "Και για την Όμα Φένα: «Αγαπημένη μου γιαγιά, σήμερα είδα τον ψηλότερο καταρράκτη του κόσμου. Ο οδηγός μού είπε να μην είμαι ανυπόμονη, και τον άκουσα. Εσύ μου το λες εδώ και τριάντα ένα χρόνια. Σήμερα, επιτέλους, το κατάλαβα.»")
  ]));

  // ── Station 11 · Epilog ──────────────────────────────
  K.push(S(11, null, "La última agua",
    { de: "Morrocoy, Karibik: das letzte Wasser. Lotte blickt auf zehn Wasser zurück, wählt das Titelbild von «Agua» — und sagt ein einziges Mal mit Absicht „vale“.",
      en: "Morrocoy, the Caribbean: the last water. Lotte looks back on ten waters, chooses the cover of «Agua» — and says “vale” one last time, on purpose.",
      el: "Μορόκοϊ, Καραϊβική: το τελευταίο νερό. Η Λότε κοιτάζει πίσω δέκα νερά, διαλέγει το εξώφυλλο του «Agua» — και λέει μία μόνο φορά, επίτηδες, «vale»." },
  [
    Z("Morrocoy es un parque de mar: islas pequeñas de arena blanca, que aquí llaman cayos, y un agua tan clara que los peces parecen volar.",
      "Morrocoy ist ein Park aus Meer: kleine Inseln aus weißem Sand, die man hier Cayos nennt, und ein Wasser, so klar, dass die Fische zu fliegen scheinen.",
      "Morrocoy is a park made of sea: little islands of white sand, which they call cayos here, and water so clear that the fish seem to fly.",
      "Το Μορόκοϊ είναι ένα πάρκο από θάλασσα: μικρά νησιά με άσπρη άμμο, που εδώ τα λένε κάγιος, και νερό τόσο καθαρό που τα ψάρια μοιάζουν να πετούν."),
    Z("Lotte llegó en lancha a Cayo Sombrero. Llevaba diez meses de viaje, nueve cuadernos llenos y una Leica que ya conocía la lluvia, el polvo, el hielo y el mole de Oaxaca.",
      "Lotte kam mit dem Motorboot nach Cayo Sombrero. Sie war seit zehn Monaten unterwegs, hatte neun volle Notizbücher und eine Leica, die schon Regen, Staub, Eis und die Mole-Soße aus Oaxaca kannte.",
      "Lotte arrived at Cayo Sombrero by motorboat. She had been travelling for ten months, had nine full notebooks and a Leica that had already met rain, dust, ice and the mole sauce of Oaxaca.",
      "Η Λότε έφτασε με βάρκα στο Κάγιο Σομπρέρο. Ταξίδευε εδώ και δέκα μήνες, είχε εννιά γεμάτα σημειωματάρια και μια Leica που είχε γνωρίσει πια τη βροχή, τη σκόνη, τον πάγο και τη σάλτσα μόλε της Οαχάκα."),
    Z("Se sentó a la sombra de una palmera con la computadora sobre las rodillas. Tenía que elegir la portada de «Agua». Bram la esperaba para el lunes. En realidad, Bram la esperaba desde octubre.",
      "Sie setzte sich in den Schatten einer Palme, den Laptop auf den Knien. Sie musste das Titelbild für «Agua» auswählen. Bram erwartete es bis Montag. Eigentlich erwartete Bram es seit Oktober.",
      "She sat down in the shade of a palm tree with the laptop on her knees. She had to choose the cover for «Agua». Bram was expecting it by Monday. In fact, Bram had been expecting it since October.",
      "Κάθισε στη σκιά ενός φοίνικα με τον υπολογιστή στα γόνατα. Έπρεπε να διαλέξει το εξώφυλλο του «Agua». Ο Μπραμ το περίμενε για τη Δευτέρα. Στην πραγματικότητα, ο Μπραμ το περίμενε από τον Οκτώβριο."),
    Z("Abrió las carpetas una por una. Cada carpeta era un agua.",
      "Sie öffnete die Ordner einen nach dem anderen. Jeder Ordner war ein Wasser.",
      "She opened the folders one by one. Each folder was a water.",
      "Άνοιξε τους φακέλους έναν έναν. Κάθε φάκελος ήταν ένα νερό."),
    Z("Ciudad de México: los canales de Xochimilco, con flores y música sobre el agua de un lago que la ciudad casi olvidó.",
      "Mexiko-Stadt: die Kanäle von Xochimilco, mit Blumen und Musik auf dem Wasser eines Sees, den die Stadt fast vergessen hat.",
      "Mexico City: the canals of Xochimilco, with flowers and music on the water of a lake the city has almost forgotten.",
      "Πόλη του Μεξικού: τα κανάλια του Σοτσιμίλκο, με λουλούδια και μουσική πάνω στο νερό μιας λίμνης που η πόλη σχεδόν ξέχασε."),
    Z("Oaxaca: el vaso de agua entre las velas de la ofrenda, al lado de Opa Kees y don Chencho, y los campos de cempasúchil, naranjas después de la lluvia.",
      "Oaxaca: das Glas Wasser zwischen den Kerzen der Ofrenda, neben Opa Kees und Don Chencho, und die Felder voller Cempasúchil, orange nach dem Regen.",
      "Oaxaca: the glass of water among the candles of the ofrenda, next to Opa Kees and Don Chencho, and the fields of cempasúchil, orange after the rain.",
      "Οαχάκα: το ποτήρι με το νερό ανάμεσα στα κεριά της ofrenda, δίπλα στον Όπα Κέις και στον δον Τσέντσο, και τα χωράφια με το cempasúchil, πορτοκαλί μετά τη βροχή."),
    Z("Monteverde: un bosque que se bebe las nubes, y una gota en el musgo con todo el bosque al revés. Quito: el Cotopaxi a lo lejos, con su glaciar, y la horchata rosada de doña Carmen.",
      "Monteverde: ein Wald, der die Wolken trinkt, und ein Tropfen auf dem Moos mit dem ganzen Wald auf dem Kopf. Quito: der Cotopaxi in der Ferne, mit seinem Gletscher, und Doña Carmens rosa Horchata.",
      "Monteverde: a forest that drinks the clouds, and a drop on the moss with the whole forest upside down inside it. Quito: Cotopaxi in the distance, with its glacier, and Doña Carmen's pink horchata.",
      "Μοντεβέρδε: ένα δάσος που πίνει τα σύννεφα, και μια σταγόνα στα βρύα με όλο το δάσος ανάποδα. Κίτο: το Κοτοπάξι στο βάθος, με τον παγετώνα του, και η ροζ horchata της κυρίας Κάρμεν."),
    Z("Otavalo: el lago San Pablo, quieto como un espejo, y el poncho azul de doña Tránsito. Tena: el río Napo, ancho y marrón, el principio del Amazonas, después de un bus que se había ido sin ella.",
      "Otavalo: der San-Pablo-See, still wie ein Spiegel, und Doña Tránsitos blauer Poncho. Tena: der Napo, breit und braun, der Anfang des Amazonas — nach einem Bus, der ohne sie abgefahren war.",
      "Otavalo: Lake San Pablo, still as a mirror, and Doña Tránsito's blue poncho. Tena: the Napo river, wide and brown, the beginning of the Amazon — after a bus that had left without her.",
      "Οταβάλο: η λίμνη Σαν Πάμπλο, ακίνητη σαν καθρέφτης, και το μπλε πόντσο της κυρίας Τράνσιτο. Τένα: ο ποταμός Νάπο, πλατύς και καφετής, η αρχή του Αμαζονίου — μετά από ένα λεωφορείο που είχε φύγει χωρίς εκείνη."),
    Z("Asunción: el río Paraguay, el calor y el termo de tereré de don Rolando. Buenos Aires: el Río de la Plata, tan ancho que parecía un mar, y don Aníbal, que bailaba tango aunque estuviera sentado.",
      "Asunción: der Río Paraguay, die Hitze und Don Rolandos Tereré-Thermoskanne. Buenos Aires: der Río de la Plata, so breit, dass er wie ein Meer aussah, und Don Aníbal, der Tango tanzte, selbst wenn er saß.",
      "Asunción: the Paraguay river, the heat and Don Rolando's tereré flask. Buenos Aires: the Río de la Plata, so wide it looked like a sea, and Don Aníbal, who danced the tango even while sitting down.",
      "Ασουνσιόν: ο ποταμός Παραγουάη, η ζέστη και το θερμός με τερερέ του δον Ρολάντο. Μπουένος Άιρες: ο Ρίο ντε λα Πλάτα, τόσο πλατύς που έμοιαζε με θάλασσα, και ο δον Ανίμπαλ, που χόρευε τάνγκο ακόμα και καθιστός."),
    Z("El Calafate: el trueno del Perito Moreno y la carta nueva de doña Inés, con un cordero que por fin parecía cordero. Canaima: Kerepakupai Merú, que se mostró cuando quiso.",
      "El Calafate: der Donner des Perito Moreno und Doña Inés' neue Speisekarte, mit einem Lamm, das endlich wie Lamm aussah. Canaima: Kerepakupai Merú, der sich zeigte, als er wollte.",
      "El Calafate: the thunder of the Perito Moreno and Doña Inés's new menu, with a lamb that finally looked like lamb. Canaima: Kerepakupai Merú, which showed itself when it chose to.",
      "Ελ Καλαφάτε: η βροντή του Περίτο Μορένο και ο καινούργιος κατάλογος της κυρίας Ινές, με ένα αρνί που επιτέλους έμοιαζε με αρνί. Καναΐμα: ο Κερεπακουπάι Μερού, που φανερώθηκε όταν θέλησε."),
    Z("Antes de decidir, hizo una videollamada. En la pantalla aparecieron, uno por uno, los amigos del viaje: doña Lupita y Ximena desde la cocina de Coyoacán, con Chicharrón en brazos; Mauricio desde la soda de doña Flor, con mala señal; doña Inés desde La Lenga, contando servilletas.",
      "Bevor sie sich entschied, machte sie einen Videoanruf. Auf dem Bildschirm erschienen nacheinander die Freunde der Reise: Doña Lupita und Ximena aus der Küche in Coyoacán, mit Chicharrón auf dem Arm; Mauricio aus Doña Flors Soda, mit schlechtem Empfang; Doña Inés aus dem La Lenga, beim Serviettenzählen.",
      "Before deciding, she made a video call. One by one, the friends from the journey appeared on the screen: Doña Lupita and Ximena from the kitchen in Coyoacán, with Chicharrón in their arms; Mauricio from Doña Flor's soda, with a bad signal; Doña Inés from La Lenga, counting napkins.",
      "Πριν αποφασίσει, έκανε μια βιντεοκλήση. Στην οθόνη εμφανίστηκαν, ένας ένας, οι φίλοι του ταξιδιού: η κυρία Λουπίτα κι η Χιμένα από την κουζίνα στο Κογιοακάν, με τον Τσιτσαρόν αγκαλιά· ο Μαουρίσιο από τη soda της κυρίας Φλορ, με κακό σήμα· η κυρία Ινές από το La Lenga, μετρώντας χαρτοπετσέτες."),
    Z("Lotte les mostró las fotos, una por una. —¡Qué padre, mija! —gritó doña Lupita al ver Xochimilco—. ¡Esa trajinera se llama como yo!",
      "Lotte zeigte ihnen die Fotos, eins nach dem anderen. „Wie toll, Kindchen!“, rief Doña Lupita, als sie Xochimilco sah. „Das Boot heißt ja wie ich!“",
      "Lotte showed them the photos, one by one. “¡Qué padre, mija!” cried Doña Lupita when she saw Xochimilco. “That boat's got my name!”",
      "Η Λότε τους έδειξε τις φωτογραφίες, μία μία. «Τι ωραία, κορίτσι μου!» φώναξε η κυρία Λουπίτα όταν είδε το Σοτσιμίλκο. «Εκείνη η βάρκα έχει το όνομά μου!»"),
    Z("—¿Y cuál va en la portada? —preguntó Ximena. —Todavía no sé —dijo Lotte—. Hoy lo decido.",
      "„Und welches kommt aufs Titelbild?“, fragte Ximena. „Ich weiß es noch nicht“, sagte Lotte. „Heute entscheide ich mich.“",
      "“And which one goes on the cover?” asked Ximena. “I don't know yet,” said Lotte. “I'll decide today.”",
      "«Και ποια μπαίνει στο εξώφυλλο;» ρώτησε η Χιμένα. «Δεν ξέρω ακόμα», είπε η Λότε. «Σήμερα θα αποφασίσω.»"),
    Z("Las fotos más espectaculares eran las del glaciar y las del salto. Bram iba a querer una de esas. Pero Lotte se detuvo en otra.",
      "Die spektakulärsten Fotos waren die vom Gletscher und die vom Wasserfall. Bram würde eines davon wollen. Aber Lotte blieb bei einem anderen hängen.",
      "The most spectacular photos were the ones of the glacier and the falls. Bram would want one of those. But Lotte stopped at another one.",
      "Οι πιο εντυπωσιακές φωτογραφίες ήταν του παγετώνα και του καταρράκτη. Ο Μπραμ θα ήθελε μία από αυτές. Όμως η Λότε σταμάτησε σε μια άλλη."),
    Z("Era la foto que le había hecho Ramón: ella, empapada, riéndose dentro de la nube del salto. No era una foto del agua. Era una foto de alguien dentro del agua. La eligió.",
      "Es war das Foto, das Ramón von ihr gemacht hatte: sie, klatschnass, lachend in der Wolke des Wasserfalls. Es war kein Foto vom Wasser. Es war ein Foto von jemandem im Wasser. Sie wählte es.",
      "It was the photo Ramón had taken of her: soaked, laughing inside the cloud of the falls. It wasn't a photo of water. It was a photo of someone inside the water. She chose it.",
      "Ήταν η φωτογραφία που της είχε βγάλει ο Ραμόν: εκείνη, μούσκεμα, να γελάει μέσα στο σύννεφο του καταρράκτη. Δεν ήταν φωτογραφία του νερού. Ήταν φωτογραφία κάποιου μέσα στο νερό. Τη διάλεξε."),
    Z("Después escuchó el último mensaje de voz de Bram. Esta vez no preguntaba dónde estaban las fotos.",
      "Dann hörte sie Brams letzte Sprachnachricht. Diesmal fragte er nicht, wo die Fotos blieben.",
      "Then she listened to Bram's last voice message. This time he didn't ask where the pictures were.",
      "Ύστερα άκουσε το τελευταίο φωνητικό μήνυμα του Μπραμ. Αυτή τη φορά δεν ρωτούσε πού ήταν οι φωτογραφίες."),
    Z("«Lotte, ya vi las fotos. Son maravillosas. ¿Cuál es la portada? Y otra pregunta: ¿cuándo vuelves?»",
      "„Lotte, ich habe die Fotos gesehen. Sie sind wunderbar. Welches ist das Titelbild? Und noch eine Frage: Wann kommst du zurück?“",
      "“Lotte, I've seen the photos. They're wonderful. Which one is the cover? And another question: when are you coming back?”",
      "«Λότε, είδα τις φωτογραφίες. Είναι υπέροχες. Ποια είναι το εξώφυλλο; Και μια ακόμα ερώτηση: πότε γυρίζεις;»"),
    Z("Lotte le mandó la foto de Ramón, sin explicación. Bram la iba a entender. O no. Los editores también tienen que aprender algunas cosas.",
      "Lotte schickte ihm Ramóns Foto, ohne Erklärung. Bram würde es verstehen. Oder nicht. Auch Lektoren müssen manches lernen.",
      "Lotte sent him Ramón's photo, without explanation. Bram would understand. Or not. Editors have to learn a few things too.",
      "Η Λότε του έστειλε τη φωτογραφία του Ραμόν, χωρίς εξήγηση. Ο Μπραμ θα καταλάβαινε. Ή όχι. Και οι επιμελητές πρέπει να μάθουν μερικά πράγματα."),
    Z("Luego escribió la última postal para Oma Fenna. La escribió en holandés, claro, pero pensó cada frase en español:",
      "Dann schrieb sie die letzte Postkarte an Oma Fenna. Sie schrieb sie natürlich auf Niederländisch, aber jeden Satz dachte sie auf Spanisch:",
      "Then she wrote the last postcard to Oma Fenna. She wrote it in Dutch, of course, but she thought every sentence in Spanish:",
      "Μετά έγραψε την τελευταία κάρτα για την Όμα Φένα. Την έγραψε στα ολλανδικά, φυσικά, αλλά σκέφτηκε κάθε πρόταση στα ισπανικά:"),
    Z("«Querida Oma: estoy en una isla del Caribe. Es la última agua del libro. He visto el agua en todas sus formas: lago, nube, hielo, río, lluvia y mar. Llego el día catorce. Tú prepara el café; yo llevo las historias.»",
      "„Liebe Oma, ich bin auf einer Insel in der Karibik. Das ist das letzte Wasser des Buches. Ich habe das Wasser in all seinen Formen gesehen: See, Wolke, Eis, Fluss, Regen und Meer. Ich komme am Vierzehnten an. Du machst den Kaffee, ich bringe die Geschichten mit.“",
      "“Dear Oma, I'm on an island in the Caribbean. It's the last water of the book. I've seen water in all its forms: lake, cloud, ice, river, rain and sea. I arrive on the fourteenth. You make the coffee; I'll bring the stories.”",
      "«Αγαπημένη μου γιαγιά, είμαι σε ένα νησί της Καραϊβικής. Είναι το τελευταίο νερό του βιβλίου. Έχω δει το νερό σε όλες του τις μορφές: λίμνη, σύννεφο, πάγο, ποτάμι, βροχή και θάλασσα. Φτάνω στις δεκατέσσερις. Εσύ φτιάξε τον καφέ· εγώ φέρνω τις ιστορίες.»"),
    Z("Al atardecer, Lotte guardó la Leica en la mochila y se metió en el mar. El agua estaba tibia. Y pensó en el español.",
      "Bei Sonnenuntergang steckte Lotte die Leica in den Rucksack und ging ins Meer. Das Wasser war lauwarm. Und sie dachte an das Spanische.",
      "At sunset Lotte put the Leica away in her rucksack and walked into the sea. The water was warm. And she thought about Spanish.",
      "Το σούρουπο η Λότε έβαλε τη Leica στο σακίδιο και μπήκε στη θάλασσα. Το νερό ήταν χλιαρό. Και σκέφτηκε τα ισπανικά."),
    Z("Al principio lo había estudiado desde la orilla: un verano, en un aula de Salamanca, con listas, con vosotros y con «vale». Después, en este viaje, había entrado. Primero un pie, después una rodilla, después una conversación. Ahora estaba dentro.",
      "Am Anfang hatte sie es vom Ufer aus gelernt: einen Sommer lang, in einem Klassenzimmer in Salamanca, mit Listen, mit vosotros und mit „vale“. Dann, auf dieser Reise, war sie hineingegangen. Erst ein Fuß, dann ein Knie, dann ein Gespräch. Jetzt war sie drin.",
      "At first she had studied it from the shore: one summer, in a classroom in Salamanca, with lists, with vosotros and with “vale”. Then, on this journey, she had gone in. First a foot, then a knee, then a conversation. Now she was inside.",
      "Στην αρχή τα είχε μάθει από την όχθη: ένα καλοκαίρι, σε μια τάξη στη Σαλαμάνκα, με λίστες, με vosotros και με «vale». Ύστερα, σε αυτό το ταξίδι, είχε μπει μέσα. Πρώτα ένα πόδι, μετά ένα γόνατο, μετά μια κουβέντα. Τώρα ήταν μέσα."),
    Z("Al agua no se la aprende desde la orilla. Se entra. Con una lengua pasa lo mismo.",
      "Wasser lernt man nicht vom Ufer aus. Man geht hinein. Mit einer Sprache ist es genauso.",
      "You don't learn water from the shore. You go in. It's the same with a language.",
      "Το νερό δεν το μαθαίνεις από την όχθη. Μπαίνεις μέσα. Το ίδιο συμβαίνει και με μια γλώσσα."),
    Z("Cuando el sol tocó el mar, el lanchero la llamó desde la playa:",
      "Als die Sonne das Meer berührte, rief der Bootsführer sie vom Strand aus:",
      "When the sun touched the sea, the boatman called to her from the beach:",
      "Όταν ο ήλιος άγγιξε τη θάλασσα, ο βαρκάρης τη φώναξε από την παραλία:"),
    Z("—¡Señorita, la última lancha! ¿La llevo de vuelta?",
      "„Señorita, das letzte Boot! Soll ich Sie zurückbringen?“",
      "“Miss, the last boat! Shall I take you back?”",
      "«Δεσποινίς, η τελευταία βάρκα! Να σας πάω πίσω;»"),
    Z("Hacía meses que Lotte no decía esa palabra. La buscó, la encontró y la dijo a propósito, con una sonrisa enorme:",
      "Seit Monaten hatte Lotte dieses Wort nicht mehr gesagt. Sie suchte es, fand es und sagte es absichtlich, mit einem riesigen Lächeln:",
      "Lotte hadn't said that word for months. She looked for it, found it and said it on purpose, with an enormous smile:",
      "Η Λότε είχε μήνες να πει αυτή τη λέξη. Την έψαξε, τη βρήκε και την είπε επίτηδες, με ένα τεράστιο χαμόγελο:"),
    Z("—¡Vale!",
      "„Vale!“",
      "“¡Vale!”",
      "«Vale!»"),
    Z("—¡Caramba! ¿Usted es española?",
      "„Donnerwetter! Sind Sie Spanierin?“",
      "“Well, I never! Are you Spanish?”",
      "«Μπα! Εσείς είστε Ισπανίδα;»"),
    Z("—No. Holandesa. Empecé a aprender en España, y terminé de aprender aquí. Bueno, terminé no: sigo aprendiendo.",
      "„Nein. Niederländerin. Angefangen zu lernen habe ich in Spanien, und fertig gelernt hier. Na ja, fertig nicht: Ich lerne weiter.“",
      "“No. Dutch. I started learning in Spain, and I finished learning here. Well, not finished: I'm still learning.”",
      "«Όχι. Ολλανδέζα. Άρχισα να μαθαίνω στην Ισπανία και τελείωσα εδώ. Δηλαδή, όχι τελείωσα: συνεχίζω να μαθαίνω.»"),
    Z("El lanchero se rió y encendió el motor. La lancha dio la vuelta hacia tierra, y Lotte, por primera vez en diez meses, no hizo ninguna foto. Esta agua se la llevaba adentro.",
      "Der Bootsführer lachte und ließ den Motor an. Das Boot wendete Richtung Land, und Lotte machte zum ersten Mal seit zehn Monaten kein einziges Foto. Dieses Wasser nahm sie in sich mit.",
      "The boatman laughed and started the engine. The boat turned back towards land, and for the first time in ten months Lotte didn't take a single photo. This water she was taking with her, inside.",
      "Ο βαρκάρης γέλασε κι έβαλε μπρος τη μηχανή. Η βάρκα γύρισε προς τη στεριά, και η Λότε, για πρώτη φορά σε δέκα μήνες, δεν έβγαλε καμία φωτογραφία. Αυτό το νερό το έπαιρνε μαζί της, μέσα της.")
  ]));

  w.SPIKIU_LR_LOTTE = { K: K };
})(window);
